    /**
     * submission/ajax중 에러가 발생한 경우 에러 처리 함수
     *
     * @date 2022.03.14
     * @private
     * @param {Object}
     *            resObj responseData 객체
     * @memberOf
     * @author InswaveSystems
     */
    _sbm_comErrorHandler: function(resObj) {
        //console.log("@@@ _sbm_comErrorHandler resObj-->", resObj)
        // server 오류 경우 200이 아닌경우 분기
        if (resObj.responseStatusCode != 200) {
            var errorMsg;
            try{
                var json = JSON.parse(resObj.responseBody);
                errorMsg = json.errors.errorMessage;            
                if (resObj.responseStatusCode == 550){ // biz Exception 경우 공통 메시지창으로 표시
                    errorMsg = errorMsg.replace("\\n","\n")
                    scutilo.showMsg(scglblo.MSG.ERROR, errorMsg);
                }
                else{                    
                    // 401인 경우 로그인 페이지로 이동
                    if(resObj.responseStatusCode === 401) {            	
						scutilo.showMsg(scglblo.MSG.WARN, json.errors.errorMessage, function(){
							if(PGJ.errorDefaultCallbak !== null && typeof PGJ.errorDefaultCallbak === 'function'){
								PGJ.errorDefaultCallbak();
								PGJ.errorDefaultCallbak = null;
							}else{
								$p.url('/pgj/ui/pgj100/PGJ111M01.xml');
							}
						});
                    } else {						
						var msg = resObj.responseStatusCode + " Error\n요청경로 : ";
						if (json.errors.hostNm) msg += "[" + json.errors.hostNm + "] ";
						msg += json.errors.referedUrl + "\n" + errorMsg;
						scutilo.showMsg(scglblo.MSG.ERROR, msg);
					}
                }
            }catch(ex){
                errorMsg = resObj.responseStatusCode 
                    + " Error\n요청경로 : " + resObj.resourceUri;
                alert(errorMsg);
            }
            return false;
        }

        // 성공인 경우 하단 toast 메시지 출력
        var rsJSON = resObj.responseJSON || null;
        var message = rsJSON && rsJSON.message ? rsJSON.message : '';
        if (message && resObj.responseStatusCode === 200) {
        	com.win.showToastMessage(gcm.MESSAGE_CODE.STATUS_SUCCESS, message);
        }
    },
	/**
	 * submission중 에러가 발생한 경우 호출되는 함수 - 서버 오류(500 error)
	 *
	 * @date 2016.11.15
	 * @private
	 * @param {Object}
	 *            resObj responseData 객체
	 * @memberOf
	 * @author InswaveSystems
	 */
	_sbm_errorHandler: function(resObj) {
		var statusCode = resObj.responseStatusCode;
		if(statusCode === 400){
			alert(resObj.responseJSON.message);
		}


		var scopeCom = gcm._getScope(resObj.id).com;

		var json = JSON.parse(resObj.responseBody);

		/*
		 * var detailStr = "HTTP STATUS INFO"; detailStr +=
		 * resObj.responseReasonPhrase; detailStr += " "; detailStr +=
		 * resObj.responseStatusCode;
		 */
		var detailStr = "";
		detailStr += json.errors.message;
		detailStr += "(URI:";
		detailStr += resObj.resourceUri;
		detailStr += ")";
		// detailStr += resObj.responseBody;

		var msgObj = {
				statusFlag : "E",
				errorCode : "E9998",
				message : "서버 오류입니다. 자세한 내용은 관리자에게 문의하시기 바랍니다.",
				messageDetail : detailStr
			};

		scopeCom.resultMsg(msgObj);
	},
	/**
	 * 특정 컴포넌트가 속한 WFrame Scope을 반환한다.
	 *
