	 *            컴포넌트 객체 또는 아이디(WFrame Scope 경로를 포함한 Full Path Id)
	 * @memberOf
	 * @author InswaveSystems
	 */
	_getScope: function(comObj) {
		if (typeof comObj === "string") {
			var scopeObj = $p.getComponentById(comObj);
