        option.keyInfo = makeKeyInfo;
        $p.data.create( option );

        if ( dataCopyYn == "Y" ) {
            var dataListObj = $p.getComponentById(newId);
            if ( dataListObj != null ) dataListObj.setJSON(descDataMap.getJSON());
