 *
 * @memberOf com.util
 * @date 2020.05.16
 * @param {String|XML} value JSON 문자열 또는 XML Document
 * @return {Object} JSON 객체 or null
 * @author Inswave Systems
 * @example
// 유효하지 않은 JSON 문자열 일 경우
com.util.getJSON("");
// return 예시)   null

// 유효한 JSON 문자열
var json = '{"tbx_sPrjNm":"1","tbx_sPrtLv":"2","tbx_sReqLv":"3"}';
com.util.getJSON(json);
