                if (popupWidth > parentFrameWidth) {
                    popupWidth = parentFrameWidth - 2;
                }

                if (popupHeight > parentFrameHeight) {
                    popupHeight = parentFrameHeight - 2;
                }

                var renderPosition = WebSquare.style.getStyle(comp.render, 'position');
                if (renderPosition !== "relative") {
                    popupTop += comp.render.offsetTop;
                    popupLeft += comp.render.offsetLeft;
                }
            }

            var bLazy = WebSquare.util.getBoolean(WebSquare.core.getConfiguration("/WebSquare/popup/lazyPopup/@value"));
            if (!bLazy) {
                this.popupWin.setPosition(popupLeft + scrollLeft, popupTop + scrollTop);
                this.popupWin.setSize(popupWidth, popupHeight);
            }

            this.popupWin.activate();

            if (_targetFrameObj) {
                this.popupWin.frame.options.popupAutoClose = true;
            } else {
                if (this.options.frameModal) {
                    this.popupWin.frame.options.popupAutoClose = true;
                } else {
                    if (popupParentFrameObj && popupParentFrameObj.options.popupAutoClose === true) {
                        this.popupWin.frame.options.popupAutoClose = true;
                    }
                }
            }

            if (bLazy) {
                this.popupWin.setPosition(popupLeft, popupTop);
                this.popupWin.setSize(popupWidth, popupHeight);
            }

            if (this.options.frameMode === "wframe") {
                //frame에 onsetsize event 전달
                WebSquare.event.fireEvent(this.popupWin.frame, "onsetsize");

                // scroll이 있는 화면에서 wframePopup을 띄운 경우 scroll위치가 다른 곳으로 벗어나는 것을 방지하기 위한 처리 (특히 modal)
                var bFocused = false;
                for (var elem = document.activeElement; elem != null && elem !== document.body; elem = elem.parentElement) {
                    if (this.popupWin.hasClass(elem, "w2popup_window")) {
                        bFocused = true; // 이미 popup 내부에 focus가 존재하는 경우에는 기존 동작 유지를 위해 focus를 주지 않는다.
                        break;
                    }
                }
                if (this.options.accessibility == true) {
                    var btnClose = document.getElementById(this.id + '_close');
                    WebSquare.style.addClass(btnClose, "w2window_close_acc");
                    var titleObj = document.getElementById(this.id+'_header_title');
                    titleObj.role = "h2";/*A*///추가 커스터마이징 원본에 없음
                    if (btnClose) {
                        //btnClose.focus();/*A*/// 원본
                        titleObj.focus();/*A*/// 추가 커스터마이징 포커스 변경
                    } else if (titleObj) {
                        titleObj.focus();
                    }
                } else if (!bFocused) {
                    this.popupWin._focus();
                }
            }

            if (WebSquare.util.isIE(6)) {
                //this.popupWin.resizeForIE6(parseInt(this.options.width) + 1, this.options.height, "popup");
            }

            if (this.options.useControl) {
                var headerControlDiv = document.getElementById(this.popupWin.id + '_header_control');
                var headerControls = headerControlDiv.getElementsByTagName("div");

                // 1. headerControlDiv 너비조정
                WebSquare.style.addClass(headerControlDiv, 'w2window_header_control_inline');

                for (var index = 0, len = headerControls.length; index < len; index++) {
                    WebSquare.style.addClass(headerControls[index], 'w2window_btn_header_control');
                }

                var btnMinimize = document.getElementById(this.id + '_minimize');
                var btnMaximize = document.getElementById(this.id + '_restore');
                var btnClose = document.getElementById(this.id + '_close');

                if (!!!controls.minimize) {
                    WebSquare.style.setStyle(btnMinimize, "display", "none");
                    WebSquare.style.removeClass(btnMinimize, "w2window_btn_header_control");
                }

                if (!!!controls.maximize) {
                    WebSquare.style.setStyle(btnMaximize, "display", "none");
                    WebSquare.style.removeClass(btnMaximize, "w2window_btn_header_control");
                }

                if (!!!controls.close) {
                    WebSquare.style.setStyle(btnClose, "display", "none");
                    WebSquare.style.removeClass(btnClose, "w2window_btn_header_control");
                }

                if (this.options.useATagBtn) {
                    var closeATagBtn = document.getElementById(this.id + '_close');
                    WebSquare.style.addClass(closeATagBtn, "w2window_btn_header_control");
                }
            }

            this.popupWin.movable(!this.popupWin.options || this.popupWin.options.fixPosition !== true);
            if (this.options.alwaysOnTop) {
                var _zIndex = this.popupWin.getStyle("z-index");

                if (WebSquare.uiplugin.popup._zIndex < _zIndex) {
                    WebSquare.uiplugin.popup._zIndex = _zIndex;
                } else {
                    this.popupWin.setStyle("z-index", WebSquare.uiplugin.popup._zIndex);
                }
            }

            this.popupWin.addEvent("onclick", function() {
                if (_this.options.alwaysOnTop && WebSquare.uiplugin.popup._status === "idle") {
                    WebSquare.uiplugin.popup._zIndex++;
                    this.setStyle("z-index", WebSquare.uiplugin.popup._zIndex);
                }

                if (this.options.clickAction) {
                    var tFunc = WebSquare.util.getGlobalFunction(this.options.clickAction, this.scope_id);
                    if (typeof tFunc === "function") {
                        tFunc.call(this, WebSquare.uiplugin.popup._zIndex);
                    }
                }
            });

            this.popupWin.addEvent("ondragstart", function() {
                if (_this.options.alwaysOnTop && WebSquare.uiplugin.popup._status === "idle") {
                    WebSquare.uiplugin.popup._zIndex++;
                    this.setStyle("z-index", WebSquare.uiplugin.popup._zIndex);
                }
            });

            this.popupWin.addEvent("onwindowmousedown", function() {
                if (_this.options.alwaysOnTop && WebSquare.uiplugin.popup._status === "idle") {
                    WebSquare.uiplugin.popup._zIndex++;
                    this.setStyle("z-index", WebSquare.uiplugin.popup._zIndex);
                }

                if (this.options.clickAction) {
                    var tFunc = WebSquare.util.getGlobalFunction(this.options.clickAction, this.scope_id);
                    if (typeof tFunc === "function") {
                        tFunc.call(this, WebSquare.uiplugin.popup._zIndex);
                    }
                }
            });

            try {
                switch (typeof this.options.openAction) {
                    case "function":
                        this.options.openAction.apply(this, this);
                        break;
                    case "string":
                        var tFunc = WebSquare.util.getGlobalFunction(this.options.openAction, this.scope_id);
                        if (typeof tFunc === "function") {
                            this.options.openAction = tFunc;
                            tFunc.apply(this, this);
                        }
                        break;
                    default:
                        break;
                }
            } catch (e) {
                WebSquare.exception.printStackTrace(e, null, this);
            }
        }

    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};
/**
 * 5.0_4.5245B.20240927.114732_1.5 버전에서 생긴 문제로 이후 버전업 되어을 때 체크 후 삭제 필요
 * multiselect li>button 요소에 tabindex="-1" 제거 WESD-1766
 */
WebSquare.uiplugin.multiselect.prototype.toHTML = function() {
    try {
        var dataIndex = WebSquare.util.getDataPrefix("index");
        var dataChecked = WebSquare.util.getDataPrefix("checked");
        var disabledStr = (this.options.disabled == "") ? "" : "disabled='true'"; //disabled
        // var disabledStyle = (this.options.disabled == "") ? "" : "style='color:#848684'"; //disabledStyle
        var styleStr = (this.options.style == "") ? "" : "style='" + this.options.style + "'"; //style
        var tabIndexStr = (this.options.tabIndex == "") ? "tabIndex='0'" : "tabIndex='" + this.options.tabIndex + "'"; //tabIndex
        var titleStr = (this.options.title == "") ? "" : "title='" + this.options.title + "'"; //title
        var ariaLabelStr = "aria-label='" +((this.options.ariaLabel == "") ? (WebSquare.language.getMessage("multiselect_ariaLabel") || "다중선택 영역") : this.options.ariaLabel) + "'";
        var htmlStr = [];
        if (this.options.accessibility == true) {
            var ilTabindexStr = this.options.accessibility ? "tabindex='-1'" : "";
            //var btnTabindexStr = this.options.accessibility ? "tabindex='-1'" : "";
            var btnTabindexStr = "";
            htmlStr.push("<div " + disabledStr + " id='" + this.id + "' " + styleStr + " class='w2multiselect_acc " + this.options.className + "' " + (this.options.accessibility ? "" : tabIndexStr + " " + titleStr + " " + ariaLabelStr) + ">");
            if (WebSquare.util.isIE(6) || WebSquare.util.isIE(7) || WebSquare.util.isOpera()) {
                htmlStr.push("<div style='overflow:visible;position:relative;height:0px'>"); //IE6 7에서 div아래에 table width:100%가 있으면 div의 스크롤까지 table이 들어감 따라서 tabled을 div로 한번더 감싸줌
            }
            htmlStr.push("<ul id='" + this.id + "_ul' class='w2multiselect_acc_ul' role='listbox' " + (this.options.accessibility ? " " + tabIndexStr + " " + titleStr + " " + ariaLabelStr : "") + ">");
            for (var i = 0; i < this.itemArr.length; i++) {
                var itemId = this.options.accessibility ? "id='" + this.id + "_li_item_" + i + "'" : "";
                var label = (this.options.escape) ? WebSquare.xml._encode(this.itemArr[i].label) : this.itemArr[i].label;
                htmlStr.push("<li " + itemId +" role='option' class='w2multiselect_acc_li' "+ dataIndex + "='" + i + "' " + dataChecked + "='false' aria-selected='false' " + ilTabindexStr + ">");
                htmlStr.push("<button class='w2multiselect_acc_link' " + btnTabindexStr + ">" + label + "</button>");
                htmlStr.push("</li>");
            }
            htmlStr.push("</ul>");
            if (WebSquare.util.isIE(6) || WebSquare.util.isIE(7) || WebSquare.util.isOpera()) {
                htmlStr.push("</div>");
            }
            htmlStr.push("</div>");
        } else {
            var paddingStr = "cellpadding='0' cellspacing='0'";
            var paddingDisplay = WebSquare.core.getConfiguration("/WebSquare/paddingDisplay/@value");
            if (paddingDisplay == "false") {
                paddingStr = "";
            }

            htmlStr.push("<div " + disabledStr + " id='" + this.id + "' " + styleStr + " class='w2multiselect_div " + this.options.className + "'" + " " + tabIndexStr + " " + titleStr + " " + ariaLabelStr + ">");
            if (WebSquare.util.isIE(6) || WebSquare.util.isIE(7) || WebSquare.util.isOpera()) {
                htmlStr.push("<div style='overflow:visible;position:relative;height:0px'>"); //IE6 7에서 div아래에 table width:100%가 있으면 div의 스크롤까지 table이 들어감 따라서 tabled을 div로 한번더 감싸줌
            }
            htmlStr.push("<table id='" + this.id + "_table' class='w2multiselect_table' role='listbox' " + paddingStr + ">");
            for (var i = 0; i < this.itemArr.length; i++) {
                var label = (this.options.escape) ? WebSquare.xml._encode(this.itemArr[i].label) : this.itemArr[i].label;
                htmlStr.push("<tr role='option' class='w2multiselect_tr' " + dataIndex + "='" + i + "' " + dataChecked + "='false' aria-selected='false'>");
