                        var headerWidth = srcElem.offsetWidth;
                        var headerOrgWidth = this.colWidthList[bodyColumnIndex];
                        for (var i = 1; i < colSpan; i++) {
                            headerOrgWidth += this.colWidthList[bodyColumnIndex + i];
                        }
                        var lastBodyColIdx = this.getColumnIndex(bodyColumnID) + colSpan - 1;
                        var colWidthSum = 0;
                        for (var i = 0; i <= lastBodyColIdx; i++) {
                            if (this.hiddenList[i] !== true) {
                                colWidthSum += this.colWidthList[i];
                            }
                        }
                        var gap = colWidthSum - (scrollLeft + scrollXDiv.offsetWidth);
                        if (gap > 0) {
                            this.setScrollLeft(scrollLeft + gap);
                        } else {
                            if (headerWidth < headerOrgWidth) {
                                this.setScrollLeft(scrollLeft - (headerOrgWidth - headerWidth));
                            }
                        }
                    }
                }
                WebSquare.util.requestAnimationFrame(function() {
                    targetBtn.focus();
                });
                if (this.options.senseReader == true) {
                    this.addGridScroll(0 - this.rowIndex);
                }
            }
        }
    }
    this.noevent = false;
};

