WebSquare.uiplugin.input.prototype.defaultOptions.checkMaxByteOnInput = false;
WebSquare.validator.validateInvoker.prototype.validateKorean = function(value, dataType) {
    try {
        var retStr = value;
        if (dataType === "number" || dataType === "float") {
            var regex = /[ㄱ-ㅎ|ㅏ-ㅣ|가-힣]/g;
            retStr = value.replace(regex, '');
        }
        return retStr;
    } catch (e) {
        WebSquare.exception.printStackTrace(e);
    }
};
WebSquare.util.getStringByByteSize = function(str, maxByteLength, ignoreChar, inputTextInfo) {
    if (!str) {
        return "";
    }
    var encoding = WebSquare.core.getConfiguration("/WebSquare/byteCheckEncoding/@value");
    if (!encoding) {
        encoding = "UTF-8";
    }
    encoding = encoding.toUpperCase();
    switch (encoding) {
        case "UTF-8":
            return WebSquare.util.getByteStringByLengthUtf8(str, maxByteLength, ignoreChar, inputTextInfo);
            break;
        default:
            return WebSquare.util.getByteStringByLength(str, maxByteLength, ignoreChar, inputTextInfo);
            break;
