        var value = this.render.value;
        if (this._editFormat) {
            var mask = WebSquare.text.whichMask(this.removeSignValue, this.removeSignToken);
            var maskValueObj = WebSquare.text.maskit2(this.removeSignValue, mask, this._editTokens, this.linkedList);
