    var getParent = function(pWin) {
        if (pWin == null) return null;
        var aObjectType = ['[object]', '[object Window]'];
        switch (String(pWin.dialogArguments)) {
            case "undefined":
                if (pWin.$p.top().scwin.isMain && pWin.scutilo.isFunction(pWin.$p.top().scwin.isMain) && pWin.$p.top().scwin.isMain()) return pWin;
                if (aObjectType.indexOf(String(pWin.opener)) > -1 && (pWin.opener != pWin)) {
                    return pWin.opener.opener === null ? pWin.opener : this.getParent(pWin.opener);
                }
                console.error("부모 객체를 찾을 수 없습니다.");
                scutilo.showMsg(scglblo.MSG.ERROR, scmsgo.COMMON.E_0002);
                return null; 
