     */
    /**
     * <pre>
     * 인자로 넘겨진 문자열에서 영역을 지정한 조건에 해당하는 추출된 문자열을 결과로 돌려준다. 
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * scutilo.setRange(sccorto.getCortLst(), 'cortTypCd', 'T,1-4', true, true); --> 법원 목록에서 법원유형코드 값이 T,1,2,3,4 로 시작하는 데이터를 필터
     * scutilo.setRange(sccorto.getCortLst(), 'cortTypCd', 'T,1-4', false, true); --> 법원 목록에서 법원유형코드 값이 T,1,2,3,4 로 시작하지 않는 데이터를 필터
     * scutilo.setRange(sccorto.getCortLst(), 'cortCd', 'T,1-4', true, true); --> 법원 목록에서 법원코드 값이 T,1,2,3,4 로 시작하는 데이터를 필터
     * scutilo.setRange(sccorto.getCortLst(), 'cortCd', 'T,1-4', false, true); --> 법원 목록에서 법원코드 값이 T,1,2,3,4 로 시작하지 않는 데이터를 필터
     * 
     * @param {String} rangeLst - 범위를 설정하고 싶은 리스트
     * @param {String} rangeLstKey - 범위를 설정하고 싶은 리스트의 키 (해당 키의 값이 숫자만으로 구성된 문자열인경우 숫자로 치환하는 작업있음 '000100' --> '100' 으로 처리)
     * @param {String} filterStr - rangeLst에서 필터할 범위 문자열(예 : "T, 1, 2, 4-6")
     * @param {Boolean} isIncl - 필터대상이 포함인지 제외인지 구분 : true -> 범위 스트링을 포함하는 문자열 / false -> 범위 스트링을 제외하는 문자열
     * @param {Boolean} isLike - 필터링 방법으로 SQL의 LIKE문 유형
     * 
     * @return {Boolean} - 영문 문자열 여부
     * </pre>
     */
    var setRange = function(rangeLst, rangeLstKey, filterStr, isIncl, isLike) {
        var _self = this;
        
        if (rangeLst.length == 0) {
            return [];
        } else {
            var fmt1 = /[A-Za-z0-9, -]+/;
            var fmt2 = /[A-Za-z0-9, ]+/;
            if ((isLike && !fmt2.test(filterStr)) || (!(isLike) && !fmt1.test(filterStr))) {
            	scutilo.showMsg(scglblo.MSG.WARN, "올바른 범위 형식이 아닙니다.");
                return rangeLst;
            }
            filterStr = _self.getRangeStr(filterStr);
            
            return rangeLst.filter(function(_o) {
                var isValidRange = _self.$_h._isValidRange(_o[rangeLstKey], filterStr, isLike);
                return (!(isIncl ^ isValidRange))
            });
        }
    };
    
    /*
     * ============= ============ ==========================
