    /**
     * <pre>
     * 업무(컨텐츠) 영역의 최상단영역을 셋팅하기 위해서 frame을 key로한 데이터로 main을 셋팅한다.
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * scutilo.setMenuScrn();
     * </pre>
     */
    var setMenuScrn = function() {
        $p.getFrame().setUserData("frame", "main");
    };
    

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     * 2022.01.17   임현진                 최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 업무(컨텐츠) 영역의 최상단 영역을 셋팅하기 위해 셋팅한 frame을 key으로 main인지 여부 판단
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * scutilo.isMenuScrn($p);
     * 
     * @param $p - 현재 자기 자신의 영역(웹스퀘어 변수)
     * 
     * @return {Boolean} - main으로 셋팅됐는지 여부를 반환
     * </pre>
     */
    var isMenuScrn = function($p) {
        if ($p.getFrame() && $p.getFrame().getUserData("frame") === "main") {
            return true;
        } else {
            return false;
        }
    };
    
    
