     * 
     * @example ex)
     * scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(scmsgo.COMMON.W_0002, '데이터'), function() {
           console.log('callback start');
       });
     * scutilo.showMsg(scglblo.MSG.WARN, scmsgo.COMMON.W_0015, function() {
           console.log('callback start');
       });
     * scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(scmsgo.COMMON.W_0002, '단어1'), callbackFunc);
