    /**
     * <pre>
     *  waiting progress 를 표시하는 팝업을 호출한다.
     *  
     *  팝업 페이지는 미리 /cm/scui/SCProgBox.xml 로 생성해 놓아야 한다.
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * scutilo.showProg(scglblo.MSG.PROG, scmsgo.COMMON.I_0004);
     * scutilo.showProg(scglblo.MSG.PROG, scutilo.getMsg(scmsgo.COMMON.I_0015, '단어1', '단어2'));
     * 
     * @param {String} title - 제목
     * @param {String} msg - 메시지
     * 
     * </pre>
     */
    var showProg = function(title, msg) {
    	if (scutilo.isEmpty(msg)) msg = '';
    	// 팝업ID는 상수로 고정됨, frame 별 팝업 생성이 아닌 최상위 frame window 에서 팝업 생성 
    	var popupId = scglblo.$_h._const.WAIT_PROG_POPUP_ID;
    	var popupWin = $p.top().$p.getPopupWindow(popupId);
    	scutilo.hideProg(); // 열린 Wait 팝업 모두 닫기 
    	// 옵션 정의 
    	var options = { 
    			id : popupId,
    	        popupName : title || scglblo.MSG.PROG,
    	        modal : true,
    	        type : "wframePopup",
    	        width : 250,
    	        height: 220 
    	};
    	$p.top().com.win.openPopup(scscrno.$_h._getSystmCtxtPathUrl("/cm/scui/SCProgBox.xml"), options, {message : msg});
    };
    
    /*
