	/**
	 * 입력한 글자수 를 넘어갈시 경고창 과 함께 입력을 막아주는 함수
	 *
	 * @param : length(입력 범위) , id(적용시킬 컴포넌트 id)
	 *
	 * ============= ============ ==========================
	 *  Date          Author       Description
	 * ============= ============ ==========================
	 *  2022.12.05.   나해준         [NELS]최초 생성
	 * ============= ============ ==========================
	 */
	checkWordLength : function(length,id){
		let mlength = eval(length)*2 -2;
		let val = id.getValue();
		let availMsg = '';
		let totLen = 0;
		let flag = false;
		for(let i=0;i<val.length;i++){
			flag = (val.charCodeAt(i)>128)? true : false;
			totLen += (flag) ? 2 : 1;
			if(totLen <= mlength){
				availMsg += val.charAt(i);
			}
			if(totLen > mlength){
				scutilo.showMsg("알림창",scutilo.getMsg("입력범위를 초과하였습니다."))
				id.setValue(availMsg);
				id.focus();
				return;
			}
		}
	},

