	 * 						aeeEvlMax : 감정평가최대,
	 * 						lwsAmtMin : 최저매각가최소,
	 * 						lwsAmtMax : 최저매각가최대
	 * 					 }
	 *
	 * @return : 결과값 (최저매각가격이 감정평가액보다 클경우 false 반환 )
	 *
	 * ============= ============ ==========================
	 *  Date          Author       Description
	 * ============= ============ ==========================
	 *  2022.12.01.   나해준       	[NELS]최초 생성
	 * ============= ============ ==========================
	 */
	getComparAmt : function( param ) {
		let aeeAmtMin = param.aeeEvlMin;
		let aeeAmtMax = param.aeeEvlMax;
		let lwsMin = param.lwsAmtMin;
		let lwsMax = param.lwsAmtMax;
		if (aeeAmtMin != "" && aeeAmtMax == ""){
			return true
		} else if (aeeAmtMax != "") {
			if (lwsMin != "" && lwsMax != "") {
				if ((Number(lwsMin) <= Number(lwsMax)) && (Number(aeeAmtMax) >= Number(lwsMax))) {
					return true;
				}else{
					return false;
				}
			} else if (lwsMin != "" && lwsMax == "") {
				if (Number(aeeAmtMax) <= Number(lwsMin)) {
					return false;
				}else{
					return true;
				}
			} else if (lwsMin == "" && lwsMax != "") {
				if (Number(aeeAmtMax) < Number(lwsMax)) {
					return false;
				}else{
					return true;
				}
			}else{
				return true;
			}
		}else{
			return true;
		}
	},


