		const location = window.location.host

		switch(location) {
			case "localhost:81" : /* 로컬 */
				loginUrl = _const.PSP_DEV_URL;
				break;
			case "nt.courtauction.go.kr" : /* 개발 */
				loginUrl = _const.PSP_DEV_URL
				break;
			case "nv.courtauction.go.kr" : /* 검증 */
				loginUrl = _const.PSP_STAG_URL
				break;
			case "www.courtauction.go.kr" : /* 운영 */
				loginUrl = _const.PSP_PROD_URL
				break;
			default : loginUrl = $p.main().wfm_header.getWindow().scwin.loginUrl

		}
		let result = false
		let options ={
            action : '/pgj/getLgnMbrInfo.on',
            mode : 'synchronous',
            method : 'POST',
            mediatype : 'application/json',
            success : function({responseJSON:{data}}) {
        		let lgnMbrsId = data.lgnMbrsId || ''
        		if (!lgnMbrsId) {
