        				if (r.clickValue) {
        						$p.url(`${loginUrl}?m=PSP101M01&n=PSP001M01&ak=tANRmaBAZfPto8hcwvaA2gex1PQbxFqUombVC&ru=`)
        				} else {
        					result = false
        				}
        			})
        		} else {
        			result = true
        		}
            }
	    }
	    await $w.ajax( options )
	    return result
	},
