	setPopUpCloseNextTabEvent : function(frameObj) {

			const retvOpts = {
		        recursive: true, //includePlugin: "trigger input selectbox radio checkbox"
		        includePlugin: "anchor autocomplete checkbox checkcombobox grid input inputbox inputcalendar multiselect radio searchbox selectbox spinner trigger textarea wframe"
		    };
			console.log("$p.getFrame() =====>", frameObj)
		    let compFrst = null;
		    let compLast = null;
		    const compArr = WebSquare.util.getChildren(frameObj, retvOpts);

		    for(let i=0; i<compArr.length; i++) {
		        let plgnNm = compArr[i].options.pluginName;
		        console.log("[#init_pp] " + plgnNm);

		        if ( null!=compFrst ) { compLast = compArr[i]; }
		        /* 첫번째 요소 */
		        if ( null==compFrst ) { compFrst = compArr[i]; }
		    }

		    let postLastCompId = ""
		    if ( null!=compLast && null != compFrst ) { //첫번째가 있으면
		    	postLastCompId = compLast.id.split("_wframe_")[0] + '_header_title';
		    	document.querySelector("#" + postLastCompId).focus();

		    } else if (null != compFrst) {
		    	postLastCompId = compFrst.id.split("_wframe_")[0] + '_header_title';
		    	document.querySelector("#" + postLastCompId).focus();
		    }

	},
