function Map_SetLevelIcon(level)
{
	var Img_Level;
	var obj;
	//占쏙옙占쏙옙占쏙옙 占쏙옙占썸에 占쏙옙占쏙옙 占쏙옙占쏙옙 표占쏙옙 占싱뱄옙占쏙옙 占쏙옙占쏙옙
	if(document.getElementById("nowLevel"+level)!=undefined){
		obj = document.getElementById("nowLevel"+level);
		for(var i = 1; i <= 12; i++){
			if(document.getElementById("nowLevel"+i)!=undefined){
				document.getElementById("nowLevel"+i).style.display = "none";
			}
		}
		obj.style.display = "";
	}
	for(var i=1; i<=12; i++)
	{
		Img_Level = "Img_MLevel" + i;

		if (i <= level)
		{
			eval("document.images."+Img_Level+".src = '/images/level_fill.gif'");
			eval("document.images."+Img_Level+".oSrc = '/images/level_fill.gif'");
		}
		else
		{
			eval("document.images."+Img_Level+".src = '/images/level_empty.gif'");
			eval("document.images."+Img_Level+".oSrc = '/images/level_empty.gif'");
		}
	}
}

