		moveCenter(312760, 544317, 10);
		return;
	}

	for(var i = 1 ; i < data.length ; i++)
	{
		if ((data[i].ptX != 'null') && (data[i].ptX != 0)) {
			drawSanghoMarker(data[i], selIdx);

			maxX = Math.max(maxX, data[i].ptX);
			maxY = Math.max(maxY, data[i].ptY);
			minX = Math.min(minX, data[i].ptX);
			minY = Math.min(minY, data[i].ptY);
		}
	}
	if (selIdx != 0) {
		deleteMarker(selIdx);
		drawSanghoMarker(data[selIdx], selIdx);
	}
	if (nminX == 0) {
		mapObj.setBound(parseInt(minX), parseInt(minY), parseInt(maxX), parseInt(maxY));
	}
	else {
		mapObj.setBound(parseInt(nminX), parseInt(nminY), parseInt(nmaxX), parseInt(nmaxY));
	}
	if(getLevel() == 13){
		zoomout();
	}
	Map_SetLevelIcon(getLevel());
}

// 占싸근뱄옙占쏙옙 占쏙옙커 占싼몌옙占쏙옙
function nearMulMarker(nearIdx)
{
	if(nearIdx == 0)
	{
		return;
	}
	var maxX=0;
	var maxY=0;
	var minX=1000000;
	var minY=1000000;
	var mkChk = 0;

	if(sanghoDataList.length == 0)
	{
		//alert('占쏙옙호占쏙옙占쏙옙占싶곤옙 占쏙옙占쏙옙占싹댐옙.');
		return;
	}
	if(sanghoDataList[1].ptX == 0 || sanghoDataList[1].ptX == 'null')
	{
		return;
	}
	if(sanghoDataList[nearIdx].nearMulData.length == 0)
	{
		moveCenter(sanghoDataList[nearIdx].ptX, sanghoDataList[nearIdx].ptY, 8);
		//alert('占싸깍옙 占쏙옙占쏙옙占쏙옙 占쏙옙占쏙옙占싹댐옙.');
		return;
	}
	var data = sanghoDataList[nearIdx].nearMulData;
	for (var j = 0; j < data.length; j++) {
		if(data[j].lvl != '3'){
			mkChk = 1;
			break;
		}
	}
	for (var i = 0; i < data.length; i++) {
		if ((data[i].ptX != 'null') && (data[i].ptX != 0)) {
			if (data[i].lvl != '3') {
				drawNearMarker(data[i]);

				maxX = Math.max(maxX, data[i].ptX);
				maxY = Math.max(maxY, data[i].ptY);
				minX = Math.min(minX, data[i].ptX);
				minY = Math.min(minY, data[i].ptY);
			}
			else if(data[i].lvl == '3')	{
				if(mkChk == 0){
				maxX = Math.max(maxX, data[i].ptX);
				maxY = Math.max(maxY, data[i].ptY);
				minX = Math.min(minX, data[i].ptX);
				minY = Math.min(minY, data[i].ptY);
				}
			}
		}
	}
	maxX = Math.max(maxX, sanghoDataList[nearIdx].ptX);
	maxY = Math.max(maxY, sanghoDataList[nearIdx].ptY);
	minX = Math.min(minX, sanghoDataList[nearIdx].ptX);
	minY = Math.min(minY, sanghoDataList[nearIdx].ptY);
	nminX = minX;
	nmaxX = maxX;
	nminY = minY;
	nmaxY = maxY;
	mapObj.setBound(parseInt(minX), parseInt(minY), parseInt(maxX), parseInt(maxY));
	Map_SetLevelIcon(getLevel());
}
