FreeMapOption.prototype.getRowCount = function (mLevel) {
	return Math.floor((this.maxY-this.minY) / (this.distancePerPixel(mLevel)*this.tileSize));
};

FreeMapOption.prototype.getColCount=function (mLevel) {
	return Math.floor((this.maxX-this.minX) / (this.distancePerPixel(mLevel)*this.tileSize));
};

FreeMapOption.prototype.indexPerpoint = function (mLevel, colIdx, rowIdx) {
  var pos = new FreeMapPoint(0, 0);

  pos.x = (colIdx * (this.distancePerPixel(mLevel) * this.tileSize)) + this.minX;
  pos.y = (rowIdx * (this.distancePerPixel(mLevel) * this.tileSize)) + this.minY;

  return pos;
};

