function FreeMapSize(width, height) {
	this.set(width,height);
}

FreeMapSize.prototype.set = function (width, height){
	if (width instanceof FreeMapSize) {
		this.width = width.width;
		this.height = width.height;
	}
	else {
		this.width = width;
		this.height = height;
	}
};

FreeMapSize.prototype.add = function (width, height){
	this.width = this.width + width;
	this.height = this.height + height;
	return this;
};

FreeMapSize.prototype.equal = function (other){
	if (other instanceof FreeMapSize){		// Data Type Check
		return ((this.widht == other.widht) && (this.height == other.height));
	}
	return false;
};

FreeMapSize.prototype.copy = function (sizeObj) {
	if (sizeObj) {
		sizeObj.set(this.width,this.height);
		return sizeObj;
	}
	else {
		return new FreeMapSize(this.width, this.height);
	}
};
function FreeMapPoint(x, y){
	this.set(x,y);
}

FreeMapPoint.prototype.set=function (x,y){
	this.x=x;
	this.y=y;
};

FreeMapPoint.prototype.add = function (x,y){
	return this.set(this.x + x, this.y + y);
};

FreeMapPoint.prototype.equal = function (other){
	if (other instanceof FreeMapPoint){		// Data Type Check
		return ((this.x == other.x) && (this.y == other.y));
	}
	return false;
};

FreeMapPoint.prototype.copy = function (other){
	if (other) {
		return other.set(this.x, this.y);
	}
	else {
		return new FreeMapPoint(this.x, this.y);
	}
};

FreeMapPoint.prototype.distance = function (other){
	return Math.sqrt(((this.x - other.x) * (this.x - other.x)) +((this.y - other.y) * (this.y - other.y)));
};

