function FreeMapDivManager( src, mapDiv ) {
	this.src = src;
	setCursor(this.src, "url('"+FreeMapImageServer+"/handCur.cur')");
	this.totalOffset = new FreeMapSize(0,0);
	this.movSize = new FreeMapSize(0,0);
	this.conSize = new FreeMapSize(this.src.offsetWidth, this.src.offsetHeight);
	this.oldPos	= new FreeMapPoint(0,0);
	this.captureObj	= this.src.setCapture ? this.src : window;	// 현재 문서에 속해있는 개체에 마우스 캡쳐를 설정한다.
	this.mapDiv = mapDiv;

	this.fpDrag	= FreeMapEvent.regCallBackFunc(this, this.drag);
	this.fpEndDrag = FreeMapEvent.regCallBackFunc(this,this.endDrag);
}

FreeMapDivManager.prototype.drag = function (evtObj) {
	if (!evtObj) evtObj = window.event;
	this.moveObject(evtObj);
	FreeMapEvent.trigger(this,"drag");
};

FreeMapDivManager.prototype.startDrag =function (evt) {
	if (!evt) evt = window.event;
	this.oldPos.set(evt.clientX,evt.clientY);
	setCursor(this.src,"url('"+FreeMapImageServer+"/handCur.cur'),auto");
	FreeMapEvent.attachEvent(this.captureObj,"mousemove",this.fpDrag);
	FreeMapEvent.attachEvent(this.captureObj,"mouseup",this.fpEndDrag);
	if (this.src.setCapture) {
		this.src.setCapture();
	}
	FreeMapEvent.disableNotifyEvent(evt);
	FreeMapEvent.trigger(this,"startdrag");
};

FreeMapDivManager.prototype.endDrag =function (evtObj) {
	if (!evtObj) evtObj = window.event;
	setCursor(this.src,"url('"+FreeMapImageServer+"/handCur.cur'),auto");
	FreeMapEvent.detachEvent(this.captureObj,"mousemove",this.fpDrag);
	FreeMapEvent.detachEvent(this.captureObj,"mouseup",this.fpEndDrag);
	this.moveObject(evtObj);
	if (document.releaseCapture) {
		document.releaseCapture();
	}
	FreeMapEvent.trigger(this,"enddrag");
	FreeMapEvent.disableNotifyEvent();
	this.totalOffset.set(0, 0);
};

FreeMapDivManager.prototype.moveObject = function (evtObj) {
  if (!evtObj) evtObj = window.event;

  var nowclientX, nowclientY;
	nowclientX = evtObj.clientX;
	nowclientY = evtObj.clientY;
	//var mapboundchk = this.mapDiv.getBound();
	var mapboundchk = this.mapDiv.getBoundOri();

  var tMovSize_width = 0;
  var tMovSize_height = 0;

  var out_minX, out_minY, out_maxX, out_maxY;
  var bmargin = Math.pow(this.mapDiv.getZoomLevel(), 2)

  out_minX = -200000/bmargin;
  out_minY = -200000/bmargin;
  out_maxX = 300000/bmargin;
  out_maxY = 300000/bmargin;

  if(mapboundchk[0] < (this.mapDiv.options.minX+out_minX) || mapboundchk[2] > (this.mapDiv.options.maxX+out_maxX) || mapboundchk[1] > (this.mapDiv.options.maxY+out_maxY) || mapboundchk[3] < (this.mapDiv.options.minY+out_minY))
  {
    if(mapboundchk[0] < (this.mapDiv.options.minX+out_minX) && 0 < (nowclientX - this.oldPos.x))
    {
      tMovSize_width = 0;
    }
    else if(mapboundchk[2] > (this.mapDiv.options.maxX+out_maxX) && 0 > (nowclientX - this.oldPos.x))
    {
      tMovSize_width = 0;
    }
    else
      tMovSize_width = nowclientX - this.oldPos.x;

    if(mapboundchk[1] > (this.mapDiv.options.maxY+out_maxY) && 0 < (nowclientY - this.oldPos.y))
    {
      tMovSize_height = 0;
    }
    else if(mapboundchk[3] < (this.mapDiv.options.minY+out_minY) && 0 > (nowclientY - this.oldPos.y))
    {
	    //alert(mapboundchk[3] + " : " + this.mapDiv.options.minY + " : " + out_minY);
	    //alert(nowclientY + " : " + this.oldPos.y);
      tMovSize_height = 0;
    }
    else
      tMovSize_height = nowclientY - this.oldPos.y;
  }
  else
  {
    tMovSize_width = nowclientX - this.oldPos.x;
    tMovSize_height = nowclientY - this.oldPos.y;
  }

  this.totalOffset.add(tMovSize_width, tMovSize_height);

	var offset = new FreeMapSize(this.movSize.width + tMovSize_width, this.movSize.height + tMovSize_height);

	this.move(offset);
	this.oldPos.set(nowclientX, nowclientY);
	offset = null;

  /* 원본
	if (!evtObj) evtObj = window.event;
	this.totalOffset.add((evtObj.clientX - this.oldPos.x), (evtObj.clientY - this.oldPos.y));
	var offset = new FreeMapSize(this.movSize.width + (evtObj.clientX - this.oldPos.x), this.movSize.height + (evtObj.clientY - this.oldPos.y));
	this.move(offset);
	this.oldPos.set(evtObj.clientX, evtObj.clientY);
	offset = null;
	*/
};

