FreeMapMap.prototype.getTileBound = function() {
	return new Array(this.imgLTCnt.x + this.imgTileOffset.x, this.imgLTCnt.y + this.imgTileOffset.y, this.imgLTCnt.x + this.imgTileSize.width + this.imgTileOffset.x, this.imgLTCnt.y - this.imgTileSize.height + this.imgTileOffset.y);
};

FreeMapMap.prototype.getBoundOri = function () {
	var distancePerPixel = this.options.distancePerPixel(this.mLevel);
	var pxBound			 = this.getPxBound();
	var minX = this.options.minX;
	var minY = this.options.minY;
	return Array(pxBound[0]*distancePerPixel+minX, pxBound[1]*distancePerPixel+minY, pxBound[2]*distancePerPixel+minX, pxBound[3]*distancePerPixel+minY);
};
FreeMapMap.prototype.getBound = function () {
	var outBound = this.getBoundOri();

  if (typeof outChangePointEx == 'function') {
      outBound = outChangePointEx("B", outBound, this.options.OptionMapOpener);
  }

    return outBound;
};

FreeMapMap.prototype.setBound = function (left, top, right, bottom) {
	if ( left instanceof Array ) {
		top = left[1];
		right = left[2];
		bottom = left[3];
		left = left[0];
	}

    var top2 = top;
    var right2 = right;
    var bottom2 = bottom;
    var left2 = left;
    if (this.options.OptionMapOpener == "D") {
        if (typeof inChangePointEx == 'function') {
            var min = inChangePointEx("P", new FreeMapPoint(left, bottom), this.options.OptionMapOpener);
	        var max = inChangePointEx("P", new FreeMapPoint(right, top), this.options.OptionMapOpener);
            left2 = min.x;
            bottom2 = min.y;
            right2 = max.x;
            top2 = max.y;
        }
    }
	var cPoint = new FreeMapPoint(Math.round((parseInt(left2) + parseInt(right2)) / 2), Math.round((parseInt(top2) + parseInt(bottom2)) / 2));
	var width = Math.abs(right - left);
	var height = Math.abs(top - bottom);
	var curLevel = this.mapMaxLevel;
	var distPerPixel = 0;

	for (var i = this.mapMinLevel; i <= this.mapMaxLevel; i++) {
		curLevel = this.mapMaxLevel - i + 1;
		distPerPixel = this.options.distancePerPixel(curLevel);
		if ( (this.scrSize.width - this.offsetBound[0] - this.offsetBound[2]) * distPerPixel > width && (this.scrSize.height + this.offsetBound[1] - this.offsetBound[3]) * distPerPixel > height ) {
			break;
		}
	}
	//alert(cPoint.x + " : " + cPoint.y + " : " + curLevel);
	this.setCenterAndZoomLevel_IN( cPoint.x, cPoint.y, curLevel );
	this.scrGeoBound= new FreeMapBound(left, top, right, bottom);
};

FreeMapMap.prototype.getPxBound = function () {
	var tileSize = this.options.tileSize;
	var left = this.imgLTCnt.x * tileSize + this.marginSize.width - this.imgConDiv.movSize.width + this.offsetBound[0];
	var right = this.imgLTCnt.x * tileSize + this.marginSize.width + this.scrSize.width - this.imgConDiv.movSize.width + this.offsetBound[2];
	var top = (this.imgLTCnt.y+1) * tileSize - this.marginSize.height + this.imgConDiv.movSize.height - this.offsetBound[1];
	var bottom	 = (this.imgLTCnt.y+1) * tileSize - this.marginSize.height - this.scrSize.height + this.imgConDiv.movSize.height - this.offsetBound[3];
	return Array(left, top, right, bottom);
};

