FreeMapMap.prototype.setCenterAndZoomLevel = function (cX, cY, mLevel) {

  if (typeof inChangePointEx == 'function') {
      var tmpCenter = inChangePointEx("P", new FreeMapPoint(cX, cY), this.options.OptionMapOpener);
      cX = tmpCenter.x;
      cY = tmpCenter.y;
  }

	var oldmLevel = -1;
	mLevel = parseInt(mLevel);
	if (this.mLevel!= mLevel) {
		oldmLevel = this.mLevel;
		this.prevLevel = this.mLevel;
		this.mLevel = mLevel;
	}
	this.curMapLevel = mLevel;
	var inCPoint = new FreeMapPoint(cX, cY);
	this.setCenter(inCPoint);
	this.cPoint.set(cX, cY);
	inCPoint = null;
	if (oldmLevel != -1) {
		FreeMapEvent.trigger(this,"zoom", this.mLevel, oldmLevel);
	}
};

