	}
};

FreeMapMap.prototype.setCenter = function (cPoint) {
	var pxCPoint;
	if (this.mLevel == 0 ) {
		this.prevLevel = this.mLevel;
		this.mLevel = 0;
		FreeMapEvent.trigger(this,"zoom", this.mLevel, 0);
	}
	this.mstCPoint.set(cPoint.x, cPoint.y);
	pxCPoint = this.options.tmmidPoint2pixel(this.mstCPoint, this.mLevel);
	this.locateTile(pxCPoint);
	FreeMapEvent.trigger(this, "redrawPath", this.mLevel);
	// 이동 FreeMapEvent.trigger(this, "redrawGraphics", this.mLevel);
};

FreeMapMap.prototype.setCenter_v2 = function (cPoint) {
	var pxCPoint;
	if (this.mLevel == 0 ) {
		this.prevLevel = this.mLevel;
		this.mLevel = 0;
		FreeMapEvent.trigger(this,"zoom", this.mLevel, 0);
	}

	if (typeof inChangePointEx == 'function') {
      var tmpCenter = inChangePointEx("P", new FreeMapPoint(cPoint.x, cPoint.y), this.options.OptionMapOpener);
      cPoint.x = tmpCenter.x;
      cPoint.y = tmpCenter.y;
  }

	this.mstCPoint.set(cPoint.x, cPoint.y);
	pxCPoint = this.options.tmmidPoint2pixel(this.mstCPoint, this.mLevel);
