	FreeMapEvent.trigger(this, "redrawPath", this.mLevel);
	// 이동 FreeMapEvent.trigger(this, "redrawGraphics", this.mLevel);
};

FreeMapMap.prototype.setTileImageArray = function (arrTileImg) {
	var arrImg;
	// 변경으로 사용되지 않는 이미지 관련 테그 삭제
	var imgTileWidth = this.imgTileSize.width;
	var imgTileHeight = this.imgTileSize.height;
	while(arrTileImg.length > imgTileWidth) {
		var column = arrTileImg.pop();
		for (var i = 0; i < column.length; i++) {
			this.mapLayer.removeChild(column[i]);
			delete column[i];
		}
	}
	// 타일 이미지 배열에 배열 추가
	for (var i = arrTileImg.length; i < imgTileWidth; i++) {
		arrTileImg.push([]);
	}
	// 추가된 배열에 이미지 개체 입력.
	var tileSize = this.options.tileSize;
	for (var i = 0; i < imgTileWidth; i++) {
		// 변경으로 사용되지 않는 이미지 관련 테그 삭제
		while(arrTileImg[i].length > imgTileHeight) {
			var elem = arrTileImg[i].pop();
			this.mapLayer.removeChild(elem);
		}
		// 새롭게 이미지 개체 생성 및 이미지 배열에 추가
		for (var j = arrTileImg[i].length; j < imgTileHeight; j++) {
			arrImg = FreeMapImage.create(null, tileSize, tileSize, 0,0,0, this.mapLayer);
			arrImg.colNum = -1;
			arrImg.rowNum = -1;
			arrTileImg[i].push(arrImg);
		}
	}
};

FreeMapMap.prototype.getCenter_New = function () {
	var rtPoint = new FreeMapPoint(0, 0);
	rtPoint.set(this.mstCPoint.x, this.mstCPoint.y);

	// jsy 201605 지도와 레이어 좌표계 틀릴 경우 처리
    if (this.options.OptionMapOpener == "D") {
        if (typeof outChangePointEx == 'function') {
            rtPoint = outChangePointEx("P", rtPoint, this.options.OptionMapOpener);
        }
    }

	return rtPoint;
};

FreeMapMap.prototype.getCenter = function () {
	var rtPoint = new FreeMapPoint(0, 0);
	rtPoint.set(this.mstCPoint.x, this.mstCPoint.y);

	return rtPoint;
};

FreeMapMap.prototype.zoomIn = function () {
	if (this.mLevel < this.mapMaxLevel) {
		this.setZoomLevel(this.mLevel + 1);
	}
	else{
	  alert("더 이상 확대할 수 없습니다.");
	}
};

FreeMapMap.prototype.zoomOut = function () {
  if(this.mapMode == "circle" && this.mLevel == 11)
  {
    return;
  }
	if (this.mLevel > this.mapMinLevel) {
		this.setZoomLevel(this.mLevel - 1);
	}
	else{
	  alert("더 이상 축소할 수 없습니다.");
	}
};

FreeMapMap.prototype.setZoomLevel = function (lv) {
	if(this.mapMinLevel > lv){
		return alert("더 이상 축소할 수 없습니다.");
	}

	if(this.mapMaxLevel < lv){
		return alert("더 이상 확대할 수 없습니다.");
	}
  if(this.zoomCheck == true)  //줌 이벤트 연속 방지 - 2007.12.12 카이네스
  {
  	if (this.mLevel != lv) {
  		this.zoomCheck = false;
  		this.scrGeoBound = null;	// 화면의 표시 영역에 대한 Boundary
  		var cPoint = this.getCenter();
  		var oldmLevel = this.mLevel;
  		this.prevLevel = this.mLevel;
  		this.mLevel = lv;
  		this.setCenter(cPoint);
  		cPoint = null;
  		FreeMapEvent.trigger(this, "zoom", this.mLevel, oldmLevel);
  		this.reLocateTile();
  		//parent.Map_SetLevelIcon(this.mLevel); //YCK
  		/*if (typeof parent.Map_SetLevelIcon == 'function') {
        parent.Map_SetLevelIcon(this.mLevel);
      }*/

  		this.zoomCheck = true;
  	}
  }
};

FreeMapMap.prototype.getZoomLevel = function () {
	return this.mLevel;
};

FreeMapMap.prototype.addControl = function (ctrlObj) {
	this.arrCtrlObj.push(ctrlObj);
	ctrlObj.initialize(this);
	ctrlObj.redrawHandler(this);
};

FreeMapMap.prototype.removeControl = function (ctrlObj) {
	for (var i=0; i<this.arrCtrlObj.length; i++) {
		if (ctrlObj == this.arrCtrlObj[i]) {
			ctrlObj.unloadHandler();
			this.arrCtrlObj.splice(i, 1);	// i번째 위치에 있는 배열을 1개 삭제해서 반환.
			break;
		}
	}
};

FreeMapMap.prototype.addMarker = function (obj) {
	this.arrMkCtrl.push(obj);
};

FreeMapMap.prototype.removeMarker = function (obj) {
	for (var i=0; i<this.arrMkCtrl.length; i++) {
		if (obj == this.arrMkCtrl[i]) {
			this.arrMkCtrl.splice(i,1);
			break;
		}
	}
};

FreeMapMap.prototype.getObjectPosition = function (obj) {
	var objPos = new Array();	// Marker 개체들의 위치 배열
	for (var i=0; i<this.arrMkCtrl.length; i++) {
		objPos[i] = this.arrMkCtrl[i].getPosition();
		for (var j=0; j<i; j++) {
			// Marker 개체들의 간격 조절.
			var sqrtX = (objPos[j].x - objPos[i].x) * (objPos[j].x - objPos[i].x);
			var sqrtY = (objPos[j].y - objPos[i].y) * (objPos[j].y - objPos[i].y);
			if ((sqrtX < 9) && (sqrtY < 9)) {
				objPos[i].add(5,-5);
			}
		}
		if (obj == this.arrMkCtrl[i]) {
			return objPos[i];
		}
	}
};

FreeMapMap.prototype.locateTile = function (pxCPoint) {
  /*
	this.imgLTPos.set(pxCPoint.x - Math.round((this.offsetBound[0] - this.offsetBound[2])/2) - Math.round(this.scrSize.width/2) - this.marginSize.width, pxCPoint.y + Math.round((this.offsetBound[1] - this.offsetBound[3])/2) + Math.round(this.scrSize.height/2) + this.marginSize.height );

  if(this.openchk)
  {
    this.setPretile();
  }
  else
  {
    this.locateTile_ex();
  }
  */
  /* 원본 */
  // 전체 이미지 타일의 left, top 위치. 레벨에 따른 픽셀단위
	var tileSize = this.options.tileSize;
	this.imgLTPos.set(pxCPoint.x - Math.round((this.offsetBound[0] - this.offsetBound[2])/2) - Math.round(this.scrSize.width/2) - this.marginSize.width, pxCPoint.y + Math.round((this.offsetBound[1] - this.offsetBound[3])/2) + Math.round(this.scrSize.height/2) + this.marginSize.height );
	this.imgLTCnt.set( Math.floor(this.imgLTPos.x / tileSize), Math.floor(this.imgLTPos.y / tileSize) );
	this.imgTileOffset.set(0,0);
	//alert(this.scrSize.width +", "+ this.scrSize.height);
	//alert(this.imgLTPos.x +", "+ this.imgLTPos.y);
  //alert(this.imgLTCnt.x +", "+ this.imgLTCnt.y);

	// 타일의 수량의 픽셀 거리와 전체 이미지와의 마진
	var tileMargin = new FreeMapSize(this.imgLTCnt.x * tileSize - this.imgLTPos.x , this.imgLTPos.y - (this.imgLTCnt.y + 1) * tileSize);
//alert(tileMargin.width +", "+tileMargin.height);
	if (tileMargin.width < -this.marginSize.width/2) {
		this.imgLTCnt.x++;
		tileMargin.width += tileSize;
	}
	else if (tileMargin.width > this.marginSize.width/2) {
		this.imgLTCnt.x--;
		tileMargin.width -= tileSize;
	}
	if (tileMargin.height < -this.marginSize.height/2) {
		this.imgLTCnt.y--;
		tileMargin.height += tileSize;
	}
	else if (tileMargin.height > this.marginSize.height/2) {
		this.imgLTCnt.y++;
		tileMargin.height -= tileSize;
	}

	var prevInterval = screen.updateInterval || 0;
	screen.updateInterval = 1000;
	this.imgConDiv.move(tileMargin);
	this.imgLTPos.add(tileMargin.width, - tileMargin.height);
	this.alignImage();
	FreeMapEvent.trigger(this,"redraw");
	screen.updateInterval = prevInterval;

	FreeMapEvent.trigger(this, "redrawGraphics", this.mLevel);
	/**/
}

FreeMapMap.prototype.locateTile_ex = function () {
	// 전체 이미지 타일의 left, top 위치. 레벨에 따른 픽셀단위
	var tileSize = this.options.tileSize;
	this.imgLTCnt.set( Math.floor(this.imgLTPos.x / tileSize), Math.floor(this.imgLTPos.y / tileSize) );
	this.imgTileOffset.set(0,0);

	// 타일의 수량의 픽셀 거리와 전체 이미지와의 마진
	var tileMargin = new FreeMapSize(this.imgLTCnt.x * tileSize - this.imgLTPos.x , this.imgLTPos.y - (this.imgLTCnt.y + 1) * tileSize);

	if (tileMargin.width < -this.marginSize.width/2) {
		this.imgLTCnt.x++;
		tileMargin.width += tileSize;
	}
	else if (tileMargin.width > this.marginSize.width/2) {
		this.imgLTCnt.x--;
		tileMargin.width -= tileSize;
	}
	if (tileMargin.height < -this.marginSize.height/2) {
		this.imgLTCnt.y--;
		tileMargin.height += tileSize;
	}
	else if (tileMargin.height > this.marginSize.height/2) {
		this.imgLTCnt.y++;
		tileMargin.height -= tileSize;
	}

	var prevInterval = screen.updateInterval || 0;
	screen.updateInterval = 1000;
	this.imgConDiv.move(tileMargin);
	this.imgLTPos.add(tileMargin.width, - tileMargin.height);
	this.alignImage();
	FreeMapEvent.trigger(this,"redraw");
	screen.updateInterval = prevInterval;
	this.openchk = true;

	FreeMapEvent.trigger(this, "redrawGraphics", this.mLevel);
};

