	var oWidth = this.imgConDiv.totalOffset.width;
	var oHeight = this.imgConDiv.totalOffset.height;
	var dpp = this.options.distancePerPixel(this.mLevel);
	this.mstCPoint.add(-oWidth * dpp, oHeight * dpp);
	//FreeMapEvent.trigger(this, "enddrag", this.getBound());
	FreeMapEvent.trigger(this, "enddrag", this.getBoundOri());
};

