};

FreeMapMap.prototype.reLocateTile = function () {
	var movSize = this.imgConDiv.movSize;
	var tileSize = this.options.tileSize;
	var tMovSize = new FreeMapSize(movSize.width+this.imgTileOffset.x*tileSize,movSize.height-this.imgTileOffset.y*tileSize);

	if (tMovSize.width < -this.marginSize.width/2) {			// 오른쪽
		this.moveRight(this.arrImgTile, false);
	}
	else if (tMovSize.width > this.marginSize.width/2) {		// 왼쪽
		this.moveLeft(this.arrImgTile, false);
	}

	if (tMovSize.height < -this.marginSize.height/2) {			// 아래쪽
		this.moveBottom(this.arrImgTile, false);
	}
	else if (tMovSize.height > this.marginSize.height/2) {		// 위쪽
		this.moveTop(this.arrImgTile, false);
	}
};

