	if (this.isDblClickMove) {
		var diff = this.getCurrentMousePoint(evtObj);
		//this.pan(diff.x,diff.y);
		diff = null;
	}
};

FreeMapMap.prototype.moveBy = function (cx, cy) {
	var dpp = this.options.distancePerPixel(this.mLevel);
	this.mstCPoint.add(cx * dpp, cy * dpp);	// 중심점의 이동에 따른 변화량 추가.
	this.diffSize = new FreeMapSize(-cx, cy);
	this.imgConMoveSize = this.imgConDiv.movSize.copy();
	this.panObj = new FreeMapPanning(Math.max(20, Math.floor(Math.sqrt(cx*cx + cy*cy)/20)));
	this.controlPan(this.panObj);
};

FreeMapMap.prototype.setMapMode = function (mode) {
  this.mapMode = mode;
};

FreeMapMap.prototype.pan = function ( x, y ) {
	if (this.isDblClickMove) {
		var dpp = this.options.distancePerPixel(this.mLevel);
		this.mstCPoint.add(x * dpp, y * dpp);	// 중심점의 이동에 따른 변화량 추가.
		this.diffSize = new FreeMapSize(-x, y);
		this.imgConMoveSize	= this.imgConDiv.movSize.copy();
		this.panObj = new FreeMapPanning(Math.max(20, Math.floor(Math.sqrt(x*x + y*y)/20)));
		this.controlPan(this.panObj);
	}
};

FreeMapMap.prototype.controlPan = function (panObj) {
	if (this.isDblClickMove) {
		var factor = panObj.getFactor();
		this.imgConDiv.move(new FreeMapSize(this.imgConMoveSize.width+this.diffSize.width*factor, this.imgConMoveSize.height+this.diffSize.height*factor));
		this.dragHandler();
		if (panObj.isMovable()) {
			this.timerID = setTimer(this, function () { this.controlPan(panObj) }, 10);
		}
		else {
			delete panObj;
			panObj = null;
		}
	}
};

