FreeMapMap.prototype.getCenterPointPx = function (pt) {
	if (!(pt instanceof FreeMapPoint)) {
		pt = new FreeMapPoint(0,0);
	}
	pt.set(this.imgLTPos.x + Math.round((this.offsetBound[0] - this.offsetBound[2])/2) + Math.round(this.scrSize.width/2)  + this.marginSize.width - this.imgConDiv.movSize.width, this.imgLTPos.y - Math.round((this.offsetBound[1] - this.offsetBound[3])/2) - Math.round(this.scrSize.height/2) -  this.marginSize.height + this.imgConDiv.movSize.height);
	return pt;
};

FreeMapMap.prototype.getCurrentPointPx = function (evtObj) {
	var pt		 = this.getCurrentMousePoint(evtObj);
	var rtCPoint = this.getCenterPointPx();
	rtCPoint.add(pt.x, pt.y);
	return rtCPoint;
};

FreeMapMap.prototype.resizeHandler = function () {
	if (this.scrSize.width != this.divCon.offsetWidth || this.scrSize.height != this.divCon.offsetHeight) {
		var cpoint = this.getCenterPointPx();
		cpoint.add((this.divCon.offsetWidth - this.scrSize.width) * 0.5 * this.resizeType.x, (this.divCon.offsetHeight - this.scrSize.height) * 0.5 * this.resizeType.y);
		this.scrSize.width	= this.divCon.offsetWidth;
		this.scrSize.height	= this.divCon.offsetHeight;
		this.getTileCountAndMargin();
		this.setTileImageArray(this.arrImgTile);
		this.locateTile(cpoint);
		cpoint = null;
		FreeMapEvent.trigger(this,"resize");
	}
};

FreeMapMap.prototype.onWheelMove = function (evtObj) {
	if (!evtObj) evtObj = window.event;
	//alert(this.zoomCheck);

	if(nowBrowser != "firefox")
	{
  	if(this.zoomCheck == true)  //줌 이벤트 연속 방지 - 2007.12.12 카이네스
  	{
    	//2007.12.12 카이네수 추가 - 연속 휠 막음
    	var startTime = new Date();
    	if((startTime.getTime() - this.wheelTime.getTime()) < 800) {
    	  //alert(startTime.getTime() - this.wheelTime.getTime());
    		return;
    	}
    	//this.wheelTime = new Date();
    	//2007.12.12 카이네수 추가 - 연속 휠 막음
    	var delta = evtObj.wheelDelta;
    	if (delta > 0) {
    		this.zoomIn();
    	}
    	else if (delta < 0) {
    		this.zoomOut();
    	}
  	}
	}
	else
	{
    var delta;
    if (evtObj.wheelDelta) { /* IE/Opera. */
      delta = evtObj.wheelDelta/120;
      /** In Opera 9, delta differs in sign as compared to IE.
      */
      if (window.opera)
        delta = -delta;
    } else if (evtObj.detail) { /** Mozilla case. */
      /** In Mozilla, sign of delta is different than in IE.
      * Also, delta is multiple of 3.
      */
      delta = -evtObj.detail/3;
    }
    if(delta < 0){
      mapObj.zoomOut();
    }
    else if(delta > 0){
      mapObj.zoomIn();
    }
  }
  FreeMapEvent.disableNotifyEvent(evtObj);
	evtObj.cancelBubble = true;
};

FreeMapMap.prototype.enableWheelZoom = function () {
	this.divCon.onmousewheel = falsefunc;
	if(nowBrowser != "firefox")
  	FreeMapEvent.attachEvent(this.divCon, "mousewheel", this.fpWheel);
  else
