FreeMapMap.prototype.disableWheelZoom = function () {
	this.divCon.onmousewheel='';

	if(bIsMSIE)
  	FreeMapEvent.detachEvent(this.divCon, "mousewheel", this.fpWheel);
  else
    FreeMapEvent.detachEvent(this.divCon, "DOMMouseScroll", this.onWheelMove);
};

