FreeMapMap.prototype.getCurrentMapTileIndex = function () {
	var regExp = /\d{4}_\d{4}/g;
	var arrTileImg = this.sortMapTile();

	if ( !arrTileImg ) return;

	var arrTileIdx = new Array();
	for (var i = 0; i < arrTileImg.length; i++) {
		var strSrc = arrTileImg[i].src
		arrTileIdx.push(strSrc.match(regExp));
	};

	return arrTileIdx;
};

FreeMapMap.prototype.sortMapTile = function () {
	if (this.arrImgTile.length < 1) return null;

	var leftBnd = -this.imgConDiv.movSize.width + this.offsetBound[0];
	var rightBnd = this.scrSize.width - this.imgConDiv.movSize.width - this.offsetBound[2];
	var topBnd = -this.imgConDiv.movSize.height + this.offsetBound[1];
	var bottomBnd = this.scrSize.height -this.imgConDiv.movSize.height - this.offsetBound[3];

	var arrTileImg = new Array();
	for ( var i = 0; i < this.arrImgTile.length; i ++) {
		for ( var j = 0; j < this.arrImgTile[i].length; j++) {
			var imgObj = this.arrImgTile[i][j];
			imgObj.xPos = i;
			imgObj.yPos = j;
			var col = Math.min(i, this.arrImgTile.length-i-1);
			var row = Math.min(j, this.arrImgTile[i].length-j-1);
			if (row == 0 || col == 0) {
				imgObj.order = 0;
			}
			else {
				imgObj.order = col + row;
			}
			var left = parseInt(imgObj.style.left);
			var right = left + this.options.tileSize;
			var top = parseInt(imgObj.style.top);
			var bottom = top + this.options.tileSize;
			if (left < leftBnd || right > rightBnd || top < topBnd || bottom > bottomBnd) {
				continue;
			}
			arrTileImg.push(imgObj);
		}
	}
	arrTileImg.sort( function (firstImg, secondImg) { return secondImg.order - firstImg.order} );
	return arrTileImg;
};

