FreeMapMap.prototype.setCenterModify = function () {
	var cPoint = this.options.pixel2tmmidPoint(this.getCenterPointPx(), this.mLevel);
	this.mstCPoint.set(cPoint.x, cPoint.y);
};

FreeMapMap.prototype.moveModifiedCenter = function (cPoint) {
	var mCP = this.options.pixel2tmmidPoint(this.getCenterPointPx(), this.mLevel);
	var mCPPx = this.options.tmmidPoint2pixel(cPoint, this.mLevel);
	var minCPPx = this.options.tmmidPoint2pixel(mCP, this.mLevel);
	var diff = new FreeMapPoint(mCPPx.x-minCPPx.x, mCPPx.y-minCPPx.y);
	if(0!=diff.x || 0!=diff.y) {
		this.moveBy(diff.x,diff.y);
		this.mstCPoint.set(cPoint.x, cPoint.y);
	}
};

FreeMapMap.prototype.isInMaxBound = function () {
	var minX = this.options.minX;
	var minY = this.options.minY;
	var maxX = this.options.maxX;
	var maxY = this.options.maxY;
	var bIn = true;
	if ((minX>this.mstCPoint.x)||(minY>this.mstCPoint.y)||(maxX<this.mstCPoint.x)||(maxY<this.mstCPoint.y)) bIn = false;
	return bIn;
};

