function FreeMapBound(left, top, right, bottom){
	this.left = left;
	this.top = top;
	this.right = right;
	this.bottom = bottom;
}

FreeMapBound.prototype.move = function (x, y){
	this.left += x;
	this.right += x;
	this.top += y;
	this.bottom += y;
};

FreeMapBound.prototype.extend=function (x, y){
	this.left -= x;
	this.right += x;
	this.top -= y;
	this.bottom += y;
};

FreeMapBound.prototype.isIntersect=function (other){
	if (other instanceof FreeMapBound){
		if ((other.left >= this.left ) && (other.left <= this.right)){
			if ((other.top >= this.top) && (other.top <= this.bottom)){
				return true;
			}
			else if ((other.bottom <= this.top) && (other.bottom <= this.bottom)){
				return true;
			}
		}
		else if ((other.right >= this.left) && (other.right <= this.right)){
			if ((other.top >= this.top) && (other.top <= this.bottom)){
				return true;
			}
			else if ((other.bottom >= this.top) && (other.bottom <= this.bottom)){
				return true;
			}
		}
	}
	return false;
};

FreeMapBound.prototype.equal=function (other){
	if (other instanceof FreeMapBound){
		return ((other.left == this.left) && (other.top == this.top) && (other.right == this.right) && (other.bottom == this.bottom));
	}
	return false;
};

FreeMapBound.prototype.getWidth=function (){
	return this.right - this.left;
};

FreeMapBound.prototype.getHeight=function (){
	return this.bottom - this.top;
};

FreeMapBound.prototype.getCenter=function (){
	return new PPoint(this.left + this.getWidth()/2, this.top + this.getHeight()/2);
};
function FreeMapCoorder(srcEllips /* = kBessel1984 */, srcSystem /* = kGeographic */,dstEllips /* = kBessel1984 */, dstSystem /* = kTmMid */)
{
	this.srcEllips = 0;
	this.srcSystem = 0;
	this.dstEllips = 0;
	this.dstSystem = 2;

	// Ellips Factor List
	this.arMajor = new Array(6377397.155, 6378137.0);
	this.arMinor = new Array(6356078.96325, 6356752.3142);

	// System Factor List
	this.arScaleFactor = new Array(1, 1, 1, 1, 0.9999, 0.9996, 0.9996, 1);
	this.arLonCenter = new Array(0.0, 2.18171200985643, 2.21661859489632, 2.2515251799362, 2.23402144255274, 2.25147473507269, 2.14675497995303, 2.21661859489632);
	this.arLatCenter = new Array(0.0, 0.663225115757845, 0.663225115757845, 0.663225115757845, 0.663225115757845, 0.0, 0.0, 0.663225115757845);
	this.arFalseNorthing = new Array(0.0, 500000.0, 500000.0, 500000.0, 600000.0, 0.0, 0.0, 550000.0);
	this.arFalseEasting = new Array(0.0, 200000.0, 200000.0, 200000.0, 400000.0, 500000.0, 500000.0, 200000.0);

	this.srcEllips = srcEllips;
	this.srcSystem = srcSystem;
	this.dstEllips = dstEllips;
	this.dstSystem = dstSystem;

//	if (srcEllips) this.srcEllips = srcEllips;
//	if (srcSystem) this.srcSystem = srcSystem;
//	if (dstEllips) this.dstEllips = dstEllips;
//	if (dstSystem) this.dstSystem = dstSystem;

	// Set Src
	var temp = this.arMinor[this.srcEllips] / this.arMajor[this.srcEllips];
	this.srcEs = 1.0 - temp * temp;
	this.srcE = Math.sqrt(this.srcEs);
	this.srcE0 = this.e0fn(this.srcEs);
	this.srcE1 = this.e1fn(this.srcEs);
	this.srcE2 = this.e2fn(this.srcEs);
	this.srcE3 = this.e3fn(this.srcEs);
	var tmp = this.mlfn(this.srcE0, this.srcE1, this.srcE2, this.srcE3, this.arLatCenter[this.srcSystem]);
	this.srcMl0 = this.arMajor[this.srcEllips] * this.mlfn(this.srcE0, this.srcE1, this.srcE2, this.srcE3, this.arLatCenter[this.srcSystem]);
	this.srcEsp = this.srcEs / (1.0 - this.srcEs);

	if (this.srcEs < 0.00001)
	{
		this.srcInd = 1.0;
	}
	else
	{
		this.srcInd = 0.0;
	}

	// Set Dst
	temp = this.arMinor[this.dstEllips] / this.arMajor[this.dstEllips];
	this.dstEs = 1.0 - temp * temp;
	this.dstE = Math.sqrt(this.dstEs);
	this.dstE0 = this.e0fn(this.dstEs);
	this.dstE1 = this.e1fn(this.dstEs);
	this.dstE2 = this.e2fn(this.dstEs);
	this.dstE3 = this.e3fn(this.dstEs);
	tmp = this.mlfn(this.dstE0, this.dstE1, this.dstE2, this.dstE3, this.arLatCenter[this.dstSystem]);
	this.dstMl0 = this.arMajor[this.dstEllips] * this.mlfn(this.dstE0, this.dstE1, this.dstE2, this.dstE3, this.arLatCenter[this.dstSystem]);
	this.dstEsp = this.dstEs / (1.0 - this.dstEs);

	if (this.dstEs < 0.00001)
	{
		this.dstInd = 1.0;
	}
	else
	{
		this.dstInd = 0.0;
	}

	this.initDatmVar();
};

FreeMapCoorder.prototype.initDatmVar = function ()
{
	var defFact;
	var dF;

	defFact = this.srcEllips - this.dstEllips;
	this.deltaX = defFact * 128;
	this.deltaY = defFact * -481;
	this.deltaZ = defFact * -664;

	this.temp = this.arMinor[this.srcEllips] / this.arMajor[this.srcEllips];
	dF = 1.0 - this.temp;
	this.esTemp = 1.0 - this.temp * this.temp;

	this.deltaA = this.arMajor[this.dstEllips] - this.arMajor[this.srcEllips];
	this.deltaF = this.arMinor[this.srcEllips] / this.arMajor[this.srcEllips] - this.arMinor[this.dstEllips] / this.arMajor[this.dstEllips];
};

FreeMapCoorder.prototype.convert = function (inX, inY)
{
	var inLon;
	var inLat;
	var outLon;
	var outLat;
	var tm;
	var geo;

	if (this.srcSystem == GEOGRAPHIC)
	{
		inLon = inX * Math.PI / 180.0;
		inLat = inY * Math.PI / 180.0;
	}
	else
	{
		geo = this.tm2geo(inX, inY);
		inLon = geo.Lon;
		inLat = geo.Lat;
	}

	if (this.srcEllips == this.dstEllips)					// 구원체가 다르면
	{
		outLon = inLon;
		outLat = inLat;
	}
	else
	{
		geo = this.datumTrans(inLon, inLat);
		outLon = geo.Lon;
		outLat = geo.Lat;
	}

	if (this.dstSystem == GEOGRAPHIC)
	{
		outX = outLon * 180.0 / Math.PI;
		outY = outLat * 180.0 / Math.PI;
	}
	else
	{
		tm = this.geo2tm(outLon, outLat);
		outX = tm.X;
		outY = tm.Y;
	}

	return {X:outX, Y:outY};
};

FreeMapCoorder.prototype.setCoord=function (srcEllips, srcSystem, dstEllips, dstSystem) {
	this.srcEllips = srcEllips || 0;
	this.srcSystem = srcSystem || 0;
	this.dstEllips = dstEllips || 0;
	this.dstSystem = dstSystem || 2;
};

FreeMapCoorder.prototype.getCoord=function () {
	return { srcEllips:this.srcEllips,srcSystem:this.srcSystem, dstEllips:this.dstEllips, dstSystem:this.dstSystem };
};

FreeMapCoorder.prototype.d2dms = function (inVal)
{
	var outD, outM, outS;

	outD = Math.floor(inVal);
	var tmpM = (inVal - outD) * 60.0;
	outM = Math.floor(tmpM);
	outS = (tmpM - outM) * 60.0;

	if ((outS + 0.00001) >= 60.0)
	{
		if (outM == 59)
		{
			outD++;
			outM = 0;
			outS = 0.0;
		}
		else
		{
			outM++;
			outS = 0.0;
		}
	}

	return {D:outD, M:outM, S:outS};
};

FreeMapCoorder.prototype.datumTrans = function (inLon, inLat)
{
	var outLon, outLat;
	var rm = this.arMajor[this.srcEllips] * (1.0 - this.esTemp) / Math.pow(1.0 - this.esTemp * Math.sin(inLat) * Math.sin(inLat), 1.5);
	var rn = this.arMajor[this.srcEllips] / Math.sqrt(1.0 - this.esTemp * Math.sin(inLat) * Math.sin(inLat));

	var deltaPhi = ((((-this.deltaX * Math.sin(inLat) * Math.cos(inLon) - this.deltaY * Math.sin(inLat) * Math.sin(inLon)) + this.deltaZ * Math.cos(inLat)) + this.deltaA * rn * this.esTemp * Math.sin(inLat) * Math.cos(inLat) / this.arMajor[this.srcEllips]) + this.deltaF * (rm / this.temp + rn * this.temp) * Math.sin(inLat) * Math.cos(inLat)) / rm;
	var deltaLamda = (-this.deltaX * Math.sin(inLon) + this.deltaY * Math.cos(inLon)) / (rn * Math.cos(inLat));

	outLat = inLat + deltaPhi;
	outLon = inLon + deltaLamda;

	return {Lon:outLon, Lat:outLat};
};

FreeMapCoorder.prototype.geo2tm = function (lon, lat)
{
	var x, y;
	var deltaLon = lon - this.arLonCenter[this.dstSystem];
	var sinPhi = Math.sin(lat);
	var cosPhi = Math.cos(lat);

	var al, als, b, c, t, tq, con, n, ml;
	if (this.dstInd != 0)
	{
		b = cosPhi * Math.sin(deltaLon);
		if ((Math.abs(b) - 1.0) < 0.0000000001)
		{
			alert("error : 무한대");
		}
	}
	else
	{
		b = 0;
		x = 0.5 * this.arMajor[this.dstEllips] * this.arScaleFactor[this.dstSystem] * Math.log((1.0 + b) / (1.0 - b));
		con = Math.acos(cosPhi * Math.cos(deltaLon) / Math.sqrt(1.0 - b * b));
		if (lat < 0)
		{
			con = -con;
			y = this.arMajor[this.dstEllips] * this.arScaleFactor[this.dstSystem] * (con - this.arLatCenter[this.dstSystem]);
		}
	}

	al = cosPhi * deltaLon;
	als = al * al;
	c = this.dstEsp * cosPhi * cosPhi;
	tq = Math.tan(lat);
	t = tq * tq;
	con = 1.0 - this.dstEs * sinPhi * sinPhi;
	n = this.arMajor[this.dstEllips] / Math.sqrt(con);
	ml = this.arMajor[this.dstEllips] * this.mlfn(this.dstE0, this.dstE1, this.dstE2, this.dstE3, lat);

	x = this.arScaleFactor[this.dstSystem] * n * al * (1.0 + als / 6.0 * (1.0 - t + c + als / 20.0 * (5.0 - 18.0 * t + t * t + 72.0 * c - 58.0 * this.dstEsp))) + this.arFalseEasting[this.dstSystem];
	y = this.arScaleFactor[this.dstSystem] * (ml - this.dstMl0 + n * tq * (als * (0.5 + als / 24.0 * (5.0 - t + 9.0 * c * c + als / 30.0 * (61.0 - 58.0 * t + t * t + 600.0 * c - 330.0 * this.dstEsp))))) + this.arFalseNorthing[this.dstSystem];

	return {X:x, Y:y};
};

FreeMapCoorder.prototype.tm2geo = function (x, y)
{
	var maxIter = 6;
	var lon, lat;
	var f, g, temp, h, con;
	if (this.srcInd != 0)
	{
		f = Math.exp(x / (this.arMajor[this.srcEllips] * this.arScaleFactor[this.srcSystem]));
		g = 0.5 * (f - 1.0 / f);
		temp = this.arLatCenter[this.srcSystem] + y / (this.arMajor[this.srcEllips] * this.arScaleFactor[this.srcSystem]);
		h = Math.cos(temp);
		con = Math.sqrt((1.0 - h * h) / (1.0 + g * g));
		lat = this.asinz(con);

		if (temp < 0) lat *= -1;

		if ((g == 0) && (h == 0))
		{
			lon = this.arLonCenter[this.srcSystem];
		}
		else
		{
			lon = Math.atan(g / h) + this.arLonCenter[this.srcSystem];
		}
	}

	x -= this.arFalseEasting[this.srcSystem];
	y -= this.arFalseNorthing[this.srcSystem];

	con = (this.srcMl0 + y / this.arScaleFactor[this.srcSystem]) / this.arMajor[this.srcEllips];
	var phi = con;
	var i = 0;
	var deltaPhi;
	while (true)
	{
		deltaPhi = ((con + this.srcE1 * Math.sin(2.0 * phi) - this.srcE2 * Math.sin(4.0 * phi) + this.srcE3 * Math.sin(6.0 * phi)) / this.srcE0) - phi;
		phi = phi + deltaPhi;

		if (Math.abs(deltaPhi) <= 0.0000000001) break;

		if (i >= maxIter)
		{
			alert("error : 무한대");
		}
		i++;
	}

	var sinPhi, cosPhi, tanPhi;
	var c, cs, t, ts, n, r, d, ds;
	if (Math.abs(phi) < (Math.PI / 2))
	{
		sinPhi = Math.sin(phi);
		cosPhi = Math.cos(phi);
		tanPhi = Math.tan(phi);
		c = this.srcEsp * cosPhi * cosPhi;
		cs = c * c;
		t = tanPhi * tanPhi;
		ts = t * t;
		con = 1.0 - this.srcEs * sinPhi * sinPhi;
		n = this.arMajor[this.srcEllips] / Math.sqrt(con);
		r = n * (1.0 - this.srcEs) / con;
		d = x / (n * this.arScaleFactor[this.srcSystem]);
		ds = d * d;

		lat = phi - (n * tanPhi * ds / r) * (0.5 - ds / 24.0 * (5.0 + 3.0 * t + 10.0 * c - 4.0 * cs - 9.0 * this.srcEsp - ds / 30.0 * (61.0 + 90.0 * t + 298.0 * c + 45.0 * ts - 252.0 * this.srcEsp - 3.0 * cs)));
		lon = this.arLonCenter[this.srcSystem] + (d * (1.0 - ds / 6.0 * (1.0 + 2.0 * t + c - ds / 20.0 * (5.0 - 2.0 * c + 28.0 * t - 3.0 * cs + 8.0 * this.srcEsp + 24.0 * ts))) / cosPhi);
	}
	else
	{
		lat = Math.PI * 0.5 * Math.sin(y);
		lon = this.arLonCenter[this.srcSystem];
	}

	return {Lon:lon, Lat:lat};
};

FreeMapCoorder.prototype.e0fn = function (x)
{
	return 1.0 - 0.25 * x * (1.0 + x / 16.0 * (3.0 + 1.25 * x));
};

FreeMapCoorder.prototype.e1fn = function (x)
{
	return 0.375 * x * (1.0 + 0.25 * x * (1.0 + 0.46875 * x));
};

FreeMapCoorder.prototype.e2fn = function (x)
{
	return 0.05859375 * x * x * (1.0 + 0.75 * x);
};

FreeMapCoorder.prototype.e3fn = function (x)
{
	return x * x * x * (35.0 / 3072.0);
};

FreeMapCoorder.prototype.e4fn = function (x)
{
	var con;
	var com;

	con = 1.0 + x;
	com = 1.0 - x;
	return Math.sqrt(Math.pow(con, con) * Math.pow(com, com));
};

FreeMapCoorder.prototype.mlfn = function (e0, e1, e2, e3, phi)
{
	return e0 * phi - e1 * Math.sin(2.0 * phi) + e2 * Math.sin(4.0 * phi) - e3 * Math.sin(6.0 * phi);
};

FreeMapCoorder.prototype.asinz = function (x)
{
	if (Math.abs(x) > 1.0)
	{
		x = (x > 0 ? 1 : -1);
	}
	return Math.asin(x);
};

function FreeMapPanning(totalTick) {
	this.totalTick = totalTick;
	this.tick = 0;
}

FreeMapPanning.prototype.resetTick = function () {
	this.tick = 0;
};

FreeMapPanning.prototype.getFactor = function () {
	this.tick++;
	var theta = Math.PI * (this.tick / this.totalTick - 0.5);
	return (Math.sin( theta ) + 1) / 2;
};

FreeMapPanning.prototype.isMovable = function () {
	return this.tick < this.totalTick
};

FreeMapPanning.prototype.getCurrentTick = function () {
	return this.tick;
};
function FreeMapIcon(src, iSize, offsetPos) {
