	}
	if (!iSize) {
		this.iSize = new FreeMapSize(30, 30);
	}
	else {
		this.iSize = iSize;
	}
	if (!offsetPos) {
		this.offsetPos = new FreeMapPoint(Math.round(this.iSize.width/2), Math.round(this.iSize.height));
	}
	else {
		this.offsetPos = new FreeMapPoint(offsetPos.x, offsetPos.y);
	}
	this.zIndex = 0;
}

