function FreeMapMarker(cPoint, mkIcon, mkId) {
	this.cPoint = cPoint;
	if (!mkIcon) {
		this.mkIcon = new FreeMapIcon();
	}
	else {
		this.mkIcon = mkIcon;
	}
	this.mkIconTag = this.mkIcon.create();
	this.parentObj = null;
	this.bNotifyEvent = false;			// 이벤트 상위 단계로 전파 여부.
	this.mkZIndex = 0;					// Marker 개체의 zIndex 값.
	this.mkMotionSize = new FreeMapSize(0, 0);	// Marker에 이벤트 발생시 살짝 움직임을 위한 값.
	this.label = null;					// 정보창 개체
	this.targetURL = null;				// 대상의 URL 주소
	this.mkId = mkId;
}

FreeMapMarker.prototype.initialize = function (parentObj) {
	this.parentObj = parentObj;

	// jsy 201605 지도와 레이어 좌표계 틀릴 경우 처리
  if (this.parentObj.options.OptionMapOpener == "D") {
      if (typeof inChangePointEx == 'function') {
          this.cPoint = inChangePointEx("P", this.cPoint, this.parentObj.options.OptionMapOpener);
      }
  }

	this.parentObj.markLayer.appendChild(this.mkIconTag);
	FreeMapEvent.link(this.mkIconTag,"mouseover",this,this.mouseOverHandler);
	FreeMapEvent.link(this.mkIconTag,"mouseout",this,this.mouseOutHandler);
	FreeMapEvent.link(this.mkIconTag,"mousedown",this,this.mouseDownHandler);
	FreeMapEvent.link(this.mkIconTag,"mouseup",this,this.mouseUpHandler);
	FreeMapEvent.link(this.mkIconTag,"click",this,this.clickHandler);
	FreeMapEvent.link(this.mkIconTag,"dblclick",this,this.dblClickHandler);
	FreeMapEvent.bind(this.parentObj,"unload",this,this.unloadHandler);
	this.parentObj.addMarker(this);
	this.callBackFunc = FreeMapEvent.bind(this.parentObj,"redraw",this,this.redrawHandler);
};

FreeMapMarker.prototype.getMkId = function (mkId) {
	return this.mkId;
};

FreeMapMarker.prototype.setIcon = function (mkIcon) {
	this.mkIcon = mkIcon;
	this.redrawHandler();
};

FreeMapMarker.prototype.setLabel = function (label) {
