};

FreeMapMarker.prototype.show = function () {
	this.mkIconTag.style.display='';
};

FreeMapMarker.prototype.hide = function () {
	this.mkIconTag.style.display='none';
};

FreeMapMarker.prototype.setZindex = function (mkZindex) {
	this.mkIconTag.zindex = mkZindex;
};

FreeMapMarker.prototype.getPosition = function () {
	var pxPos = this.parentObj.getPosition(this.parentObj.options.tmmidPoint2pixel(this.cPoint, this.parentObj.mLevel));
	var offset = this.mkIcon.getOffsetPos();
	var x = pxPos.x - offset.x;
