FreeMapMarker.prototype.mouseOverHandler = function (evtObj) {
	if (!evtObj) evtObj = window.event;
	if (!this.bNotifyEvent && evtObj) {
		FreeMapEvent.disableNotifyEvent(evtObj);
	}
	this.mkZIndex = this.mkIconTag.style.zIndex;
	this.mkIconTag.style.zIndex = 1000;													// 마우스 오버시 최상위로
	this.mkIconTag.style.left = this.mkIconTag.ctrlPos.x - this.mkMotionSize.width + "px";
	this.mkIconTag.style.top = this.mkIconTag.ctrlPos.y - this.mkMotionSize.height + "px";
	FreeMapEvent.trigger(this, "mouseover", this.getPoint());
};

FreeMapMarker.prototype.mouseOutHandler = function (evtObj) {
	if (!evtObj) evtObj = window.event;
	if (!this.bNotifyEvent && evtObj) {
		FreeMapEvent.disableNotifyEvent(evtObj);
	}
	this.mkIconTag.style.zIndex = this.mkZIndex;
	this.mkIconTag.style.left = this.mkIconTag.ctrlPos.x + "px";
	this.mkIconTag.style.top = this.mkIconTag.ctrlPos.y + "px";
	//this.hideInfoWindow(3000);
	FreeMapEvent.trigger(this, "mouseout");
};

FreeMapMarker.prototype.mouseDownHandler = function (evtObj) {
