		FreeMapEvent.disableNotifyEvent(evtObj);
	}
	FreeMapEvent.trigger(this, "mousedown");
};

FreeMapMarker.prototype.mouseUpHandler = function (evtObj) {
	if (!evtObj) evtObj = window.event;
	if (!this.bNotifyEvent && evtObj) {
		FreeMapEvent.disableNotifyEvent(evtObj);
	}
	FreeMapEvent.trigger(this, "mouseup");
};

FreeMapMarker.prototype.clickHandler = function (evtObj) {
