FreeMapMarker.prototype.unloadHandler = function () {
	FreeMapEvent.removeListener(this.parentObj, "zoom", this.callBackFunc);
	if ( this.parentObj && this.parentObj.markLayer ) {
		if (this.mkIconTag) this.parentObj.markLayer.removeChild(this.mkIconTag);
		this.parentObj.removeMarker(this);

	}
	if (this.label != null) this.label.unloadHandler();
	this.mkIconTag = null;
	this.mkIcon = null;
};

