	if (!this.parentObj || !this.mkIconTag) return;
	var mkPos = this.parentObj.getObjectPosition(this);
	this.mkIconTag.style.left = mkPos.x + "px" ;
	this.mkIconTag.style.top = mkPos.y + "px";
	this.mkIconTag.ctrlPos = mkPos;		// marker icon의 위치.
};

