FreeMapInfoWin.prototype.initWindow = function () {
	this.infoDiv.style.backgroundColor = "transparent";
	this.infoDiv.style.padding = "0px 0px 0px 0px";
	this.setOpacity(1);
	this.infoDiv.id="id_infoDiv";
	this.infoDiv.style.display = "none";
	this.contentsDiv = this.parentObj.createDIV(0);
	this.contentsDiv.id="id_contentsDiv";
	this.infoDiv.appendChild(this.contentsDiv);
	this.contentsDiv.style.backgroundColor = "transparent";
	this.contentsDiv.style.position = "relative";
	this.contentsDiv.style.padding = "0px 0px 0px 0px";
	this.contentsDiv.style.left = "0px";
	this.contentsDiv.style.top = "0px";
};

FreeMapInfoWin.prototype.setPanning = function (flag) {
	this.bPan = flag;
};

FreeMapInfoWin.prototype.setMarkerSize = function (mkSize) {
	if (mkSize) this.mkSize.set(mkSize);
};

FreeMapInfoWin.prototype.getMarkerSize = function () {
	return this.mkSize;
};

FreeMapInfoWin.prototype.getContentsDiv = function(){
	return this.contentsDiv;
};

FreeMapInfoWin.prototype.setzIndex = function(zIndex){
	this.contentsDiv.style.zIndex = zIndex;
};

FreeMapInfoWin.prototype.setContents = function (contents) {
	//this.contentsDiv.style.width = this.infoWinSize.width + "px";
	//this.contentsDiv.style.height = this.infoWinSize.width + "px";
	//this.infoDiv.style.width = this.infoWinSize.width + "px";
	//this.infoDiv.style.height = this.infoWinSize.width + "px";

	this.contentsDiv.style.width = '';
	this.contentsDiv.style.height = '';
	//this.contentsDiv.style.cursor = "pointer";
	this.infoDiv.style.width = '';
