	this.contentsDiv.innerHTML = contents;
	if (this.infoDiv.style.display !="none") {
		this.redrawHandler();
	}
};

FreeMapInfoWin.prototype.setPosition = function (pos) {
	this.infoWinPos = pos;
	if (this.infoDiv.style.display !="none") {
		this.redrawHandler();
	}
};

FreeMapInfoWin.prototype.getPosition = function () {
	return this.infoWinPos;
};

FreeMapInfoWin.prototype.setSize = function (winSize) {
	this.infoWinSize.set(winSize.width, winSize.height);
};

FreeMapInfoWin.prototype.getSize = function () {
	return this.infoWinSize;
};

FreeMapInfoWin.prototype.setOpacity = function (op) {
	this.infoDiv.style.opacity = op;
	// IE에서 Opacity의 부모 자식간의 중복시 레이어의 사라짐 때문에 라벨일 경우만 Opacity적용.
	if (this.bLabel) this.infoDiv.style.filter ='alpha(opacity = '+(op*100)+')';
};

FreeMapInfoWin.prototype.getOpacity = function () {
	return this.infoWinOp;
};

FreeMapInfoWin.prototype.show = function () {
	if (this.hideTimeout) {
		window.clearTimeout(this.hideTimeout);
		this.hideTimeout = null;
	}
	this.bShow = true;
	this.alignPos.set(1, 0);
	FreeMapEvent.addListener(this.parentObj, "redraw", this.redrawFunc);
	FreeMapEvent.addListener(this.parentObj, "move", this.redrawFunc);
	this.infoDiv.style.display = '';
	this.redrawHandler();
	this.pan();
};

FreeMapInfoWin.prototype.hide = function () {
	this.bShow = false;
	FreeMapEvent.removeListener(this.parentObj, "redraw", this.redrawFunc);
	FreeMapEvent.removeListener(this.parentObj, "move", this.redrawFunc);
	this.infoDiv.style.display = 'none';
};

FreeMapInfoWin.prototype.set = function (pos, contents) {
	this.infoWinPos = pos;
	this.setContents(contents);
};

FreeMapInfoWin.prototype.set_New = function (info_pos, pos, contents) {
	this.info_pos = info_pos;
	this.infoWinPos = pos;
	this.setContents(contents);
};

FreeMapInfoWin.prototype.redrawHandler = function () {
	if (null == this.parentObj || null == this.infoWinPos || this.infoDiv.style.display=='none') {
		return;
	}
	this.infoDiv.style.width = this.contentsDiv.offsetWidth + "px";
	this.infoDiv.style.height = this.contentsDiv.offsetHeight + "px";
	//alert(this.infoDiv.style.width);
	this.locateInfoWindow();
};

FreeMapInfoWin.prototype.locateInfoWindow = function () {
	var pxPos = this.parentObj.getPosition(this.parentObj.options.tmmidPoint2pixel(this.infoWinPos, this.parentObj.mLevel)); //마커 중심 위치(화면에서)
	var adjustX = 0;
	if(this.gubun == "IN")
		adjustX = (!this.bLabel) ? Math.floor(this.infoDiv.offsetWidth) : -10;
	else
		adjustX = (!this.bLabel) ? Math.floor(this.infoDiv.offsetWidth / 2) : -10;

	//this.info_pos
	var topVal = 0;
	var leftVal = 0;
	if(this.gubun == "IN"){
		if(this.info_pos == 2 || this.info_pos == 4){
          	leftVal = pxPos.x - adjustX;
          	if(this.info_pos == 4)
          		topVal = (pxPos.y - this.infoDiv.offsetHeight - this.mkSize.height - 1)+(this.infoDiv.offsetHeight + this.mkSize.height);
          	else
          		topVal = pxPos.y - this.infoDiv.offsetHeight - this.mkSize.height - 1;
          	this.infoDiv.style.left = leftVal + this.offset.x + "px";
          	this.infoDiv.style.top = topVal + this.offset.y + "px";
		}
		else if(this.info_pos == 3 || this.info_pos == 5){
          	leftVal = pxPos.x;
          	if(this.info_pos == 5)
          		topVal = (pxPos.y - this.infoDiv.offsetHeight - this.mkSize.height - 1)+(this.infoDiv.offsetHeight + this.mkSize.height);
          	else
          		topVal = pxPos.y - this.infoDiv.offsetHeight - this.mkSize.height - 1;
          	this.infoDiv.style.left = leftVal + this.offset.x + "px";
          	this.infoDiv.style.top = topVal + this.offset.y + "px";
      	}
	}
	else{
      	leftVal = pxPos.x - adjustX;
      	topVal = pxPos.y - this.infoDiv.offsetHeight - this.mkSize.height - 1;
      	this.infoDiv.style.left = leftVal + this.offset.x + "px";
      	this.infoDiv.style.top = topVal + this.offset.y + "px";
	}
//alert(this.infoDiv.style.left);
//alert(this.offset.x);
//alert("* pxPos.x : " + pxPos.x + " , leftVal : " + leftVal + " , style.left : " + this.infoDiv.style.left);
};

FreeMapInfoWin.prototype.pan = function () {
	if (!this.bPan) return;
	var adjustX = Math.floor(this.infoDiv.offsetWidth / 2) + 20;
	var adjustY = 40;
	var pxPos = this.parentObj.getPosition(this.parentObj.options.tmmidPoint2pixel(this.infoWinPos, this.parentObj.mLevel));
	var xPos, yPos;
	if ((this.parentObj.imgConDiv.movSize.width + pxPos.x - adjustX) <= this.parentObj.offsetBound[0]) {
		xPos = this.parentObj.imgConDiv.movSize.width + pxPos.x - this.parentObj.offsetBound[0] - adjustX;
	}
	else if ((this.parentObj.imgConDiv.movSize.width + pxPos.x + adjustX) >= (this.parentObj.scrSize.width - this.parentObj.offsetBound[2])) {
		xPos = this.parentObj.imgConDiv.movSize.width + pxPos.x - this.parentObj.scrSize.width + this.parentObj.offsetBound[2] + adjustX;
	}
	else {
		xPos = 0;
	}
	yPos = this.parentObj.imgConDiv.movSize.height + pxPos.y - adjustY;

	var xPan = xPos;
	var yPan = Math.min(Math.max(0, adjustY - (yPos - this.infoDiv.clientHeight - this.parentObj.offsetBound[1])), (this.parentObj.scrSize.height - adjustY - yPos + this.parentObj.offsetBound[3]));
	this.parentObj.pan(xPan, yPan);
	if(this.parentObj.minimapObj) this.parentObj.minimapObj.pan(Math.round(xPan/8), Math.round(yPan/8));
};

FreeMapInfoWin.prototype.mouseOverHandler = function (evtObj) {
	if (!evtObj) evtObj = window.event;
	FreeMapEvent.disableNotifyEvent(evtObj);
	FreeMapEvent.trigger(this, "mouseover");
};

FreeMapInfoWin.prototype.mouseOutHandler = function (evtObj) {
	if (!evtObj) evtObj = window.event;
	FreeMapEvent.disableNotifyEvent(evtObj);
	FreeMapEvent.trigger(this, "mouseout");
};

FreeMapInfoWin.prototype.mouseDownHandler = function (evtObj) {
	if (!evtObj) evtObj = window.event;
	FreeMapEvent.disableNotifyEvent(evtObj);
	FreeMapEvent.trigger(this, "mousedown");
};

FreeMapInfoWin.prototype.delayHideWindow = function (fadeTime) {
	if (!fadeTime) fadeTime = 5000;
	if (this.hideTimeout != null) {
		window.clearTimeout(this.hideTimeout);
	}
	this.hideTimeout = setTimer(this, function () { this.hide() }, fadeTime);
};

FreeMapInfoWin.prototype.unloadHandler = function () {
	if (this.infoDiv != null) this.infoDiv.removeChild(this.contentsDiv);
	this.contentsDiv = null;
	if (this.parentObj != null) this.parentObj.infoLayer.removeChild(this.infoDiv);
	this.infoDiv = null;
	this.infoWinPos = null;
	this.redrawFunc = null;
	this.parentObj = null;
	this.offset = null;
};

FreeMapInfoWin.prototype.isShow = function () {
	return this.bShow;
};

FreeMapInfoWin.prototype.setOffset = function (offset) {
	this.offset.set(offset.x, offset.y);
	this.redrawHandler();
};

FreeMapInfoWin.prototype.getOffset = function () {
	return this.offset;
};
