// Name: tmtoScrPixel
// Desc: 중부좌표를 화면좌표로
// Args:
// Date: 2007-11-15
// Edit: 2007-11-17 파이어폭스 캔버스 여유 추가
FreeMapGraphics.prototype.tmtoScrPixel = function(ptX, ptY, level){
  var point = new FreeMapPoint(ptX, ptY);

  if (this.mapObj.options.OptionMapOpener == "D") {
      if (typeof inChangePointEx == 'function') {
          point = inChangePointEx("P", point, this.mapObj.options.OptionMapOpener);
      }
  }

  point = this.options.tmmidPoint2pixel(point, level);

  if(this.browse == "FF")
  {
    point.x = point.x - this.scrLeft - this.marginLeft - this.movingLeft + this.layerMargin; // 오차계산
    point.y = this.scrTop - point.y - this.marginTop - this.movingTop + this.layerMargin;
  }
  else
  {
    point.x = point.x - this.scrLeft - this.marginLeft; // 오차계산
    point.y = this.scrTop - point.y - this.marginTop;
  }
  return point;
};

// Name: pixtoScrPixel
// Desc: 전체픽셀좌표를 화면좌표로
// Args:
// Date: 2007-11-15
// Edit:
FreeMapGraphics.prototype.pixtoScrPixel = function(ptX, ptY, level){
  var point = new FreeMapPoint(ptX, ptY);

  if(this.browse == "FF")
  {
    point.x = point.x - this.scrLeft - this.marginLeft - this.movingLeft; // 오차계산
    point.y = this.scrTop - point.y - this.marginTop - this.movingTop;
  }
  else
  {
    point.x = point.x - this.scrLeft - this.marginLeft; // 오차계산
    point.y = this.scrTop - point.y - this.marginTop;
  }
  return point;
};

