// 이  름 : calcDist
// 인  자 : x1, y1, x2, y2(시작좌표와 끝좌표)
// 내  용 : 두점사이 거리 구하기
// 날  짜 : 2007-10-23
// 작업자 : 서형진(Kainess)
// 수  정 :
FreeMapGraphics.prototype.calcDist = function(x1, y1, x2, y2){
  // 피타고라스 정리 두점사이거리구하기
  var dist = Math.sqrt(Math.pow((x2-x1), 2) + Math.pow((y2-y1), 2));
  return dist;
};

// 이  름 : calcRadi
// 인  자 : x1, y1, x2, y2(시작좌표와 끝좌표)
// 내  용 : 반지름
// 날  짜 : 2008-10-02
// 작업자 : 서형진(Kainess)
// 수  정 :
FreeMapGraphics.prototype.calcRadi = function(x1, y1, x2, y2){
  // 피타고라스 정리 두점사이거리구하기
  var dist = Math.max(Math.abs(Math.abs(x2)-Math.abs(x1)), Math.abs(Math.abs(y2)-Math.abs(y1)));
  return dist;
};

// 이  름 : calcPolygon
// 인  자 : point - 좌표 배열
// 내  용 : 다각형 넓이구하기(배횡거법)
// 날  짜 : 2007-10-26
// 작업자 : 서형진(Kainess)
// 수  정 :
FreeMapGraphics.prototype.calcPolygon = function(point){  // 배횡거법
  var area = 0;
  for(var i=0; i<=this.clickCnt; i++)
  {
    if(i == 0)
    {
      area = Math.abs(point[i+1].x)*Math.abs(point[i].y/2);
    }
    else if(i==this.clickCnt-1)
    {
      area = area+(Math.abs(point[0].x)-Math.abs(point[i-1].x))*Math.abs(point[i].y/2);
    }
    else if(i==this.clickCnt)
    {
      area = area+(0-Math.abs(point[i-1].x))*Math.abs(point[0].y/2);
    }
    else
    {
      area = area+(Math.abs(point[i+1].x)-Math.abs(point[i-1].x))*Math.abs(point[i].y/2);
    }
  }
  return Math.abs(area);
};

// 이  름 : getPathInfo
// 인  자 : point - 좌표 배열
// 내  용 : 좌표배열을 PathInfo로 추출, 익스플로러용 패스생성
// 날  짜 : 2007-10-26
// 작업자 : 서형진(Kainess)
// 수  정 :
FreeMapGraphics.prototype.getPathInfo = function(point){
  var pathInfo = "";
  var tmpPt = new Array();

	for(var i=0; i<this.clickCnt+1; i++) {
	  if(i==0) {
	    pathInfo += "m";
		}
		tmpPt[i] = this.tmtoScrPixel(point[i].x, point[i].y, this.getLevel());
		pathInfo += tmpPt[i].x + "," + tmpPt[i].y;

    if (i==this.clickCnt) {
		  pathInfo += "xe";
		} else {
		  pathInfo += "l";
		}
	}
	return pathInfo;
};

// 이  름 : getPathInfo2
// 인  자 : point - 좌표 배열
// 내  용 : 좌표배열을 PathInfo로 추출 다각형 리드로우시 사용, 익스플로러용 패스생성
// 날  짜 : 2007-10-26
// 작업자 : 서형진(Kainess)
// 수  정 :
FreeMapGraphics.prototype.getPathInfo2 = function(point){
  var pathInfo = "";
  var tmpPt = new Array();
  var len = point.length;
	for(var i=0; i<len; i++) {
	  if(i==0) {
	    pathInfo += "m";
		}
		tmpPt[i] = this.tmtoScrPixel(point[i].x, point[i].y, this.getLevel());
		pathInfo += tmpPt[i].x + "," + tmpPt[i].y;

    if (i==len-1) {
		  pathInfo += "xe";
		} else {
		  pathInfo += "l";
		}
	}
	return pathInfo;
};

// 이  름 : pttoPath
// 인  자 : point - 좌표배열
// 내  용 : 파이어폭스용 패스 생성
// 날  짜 : 2007-11-15
// 작업자 : 서형진(Kainess)
// 수  정 :
FreeMapGraphics.prototype.pttoPath = function(point){
  var path = "";
  var tmpPt = new Array();
  var len = point.length;
  for(var i=0; i<len; i++)
  {
    tmpPt[i] = this.tmtoScrPixel(point[i].x, point[i].y, this.getLevel());
    path += tmpPt[i].x + ", " + tmpPt[i].y;
    if(i != len)
    {
      path += " ";
    }
  }
  return path;
};

FreeMapGraphics.prototype.getPointsInfo = function(point){
  var points = "";
  var tmpPt = new Array();
  var len = point.length;
  for(var i=0; i<len; i++)
  {
    tmpPt[i] = this.tmtoScrPixel(point[i].x, point[i].y, this.getLevel());
    points += tmpPt[i].x + "pt,"+tmpPt[i].y + "pt";
    if(i != len-1)
    {
      points += ",";
    }
  }
  return points;
};

// 이  름 : distTextbox
// 인  자 : dist - 거리 idx - 인덱스
// 내  용 : 거리 텍스트박스
// 날  짜 : 2007-10-23
// 작업자 : 서형진(Kainess)
// 수  정 : 10-26 단위환산
FreeMapGraphics.prototype.distTextbox = function(dist, idx){
  var onfoot = this.methodTime(dist, 67);
	var bicycle = this.methodTime(dist, 266);
  var unit = "m";
  if(dist >= 1000)
  {
    dist = dist/1000;
    dist = dist.toFixed(2);
    unit = "km";
  }
  else
  {
    dist = parseInt(dist);
  }
  var textBox = "<table style='width:144px; border:2px solid #56ACD5; border-collapse:collapse; border-spacing:0;'>"
              +"<tr><td>"
