// 날  짜 : 2007-11-19
// 작업자 : 서형진(Kainess)
// 수  정 :
FreeMapGraphics.prototype.deleteAllObj = function(){
  var len = this.container.length;
  for(var i=0; i<len; i++)
  {
    if(this.container[i].drawMode != "destroyed")
    {
      if(this.drawingText == true && this.container[i].drawMode != "circle")
        this.textBoxDiv[50+i].parentNode.removeChild(this.textBoxDiv[50+i]);
      this.drawDiv[50+i].parentNode.removeChild(this.drawDiv[50+i]);
    }
  }

  this.drawIdx = 50;
  delete(drawDiv);
  delete(textBoxDiv);
  delete(tmpTextboxDiv);
  delete(pDraw);
  delete(svg);
  delete(this.container);
  //this.drawDiv = new Array();
  this.textBoxDiv = new Array();
  this.tmpTextboxDiv = new Array();
  this.pDraw = new Array();
  this.svg = new Array();
  this.container = new Array();
};

