function FreeMapZoomControlScourt () {
	this.setAlign("right");
	this.setValign("top");
	//var zoomImageUrl = "./";
	var zoomImageUrl = FreeMapImageServer;

	this.flashMapImgURL   = zoomImageUrl + "GIS_wholemap.gif";
	this.stickImgURL   = zoomImageUrl + "GIS_scalebar.gif";
	this.scalerImgURL  = zoomImageUrl + "GIS_scale.gif";
	this.plusImgURL    = zoomImageUrl + "GIS_plus.gif";
	this.minusImgURL   = zoomImageUrl + "GIS_minus.gif";
}

FreeMapZoomControlScourt.prototype = new FreeMapLayer(new FreeMapSize(62,190), new FreeMapPoint(10, 10));

FreeMapZoomControlScourt.prototype.initialize = function (parentObj) {
	FreeMapLayer.prototype.initialize.call(this, parentObj, true);
	this.setZIndex(1);

	this.fpDragStart = FreeMapEvent.regCallBackFunc(this, this.onDragStart);
	this.fpDrag		 = FreeMapEvent.regCallBackFunc(this, this.dragHandler);
	this.fpDragStop	 = FreeMapEvent.regCallBackFunc(this, this.onDragStop);

  this.flashMap = FreeMapImage.create(this.flashMapImgURL, 28, 41, 28, 20, 20);
  this.flashMap.style.filter = 'alpha(Opacity=70)';
	this.appendChild(this.flashMap);
	setCursor( this.flashMap, "pointer");
	FreeMapEvent.link(this.flashMap, "click", this, this.showFlashmap);
	FreeMapEvent.link(this.flashMap, "mouseover", this, this.mouseoverhandler);
	FreeMapEvent.link(this.flashMap, "mouseout", this, this.onmouseouthandler);

	this.zoomStick = FreeMapImage.create(this.stickImgURL, 24, 11, 30, 156, 20);
	this.zoomStick.style.filter = 'alpha(Opacity=60)';
	this.appendChild(this.zoomStick);
	setCursor( this.zoomStick, "pointer");
	FreeMapEvent.attachEvent(this.zoomStick, "mousedown", this.fpDragStart);
	FreeMapEvent.link(this.zoomStick, "mouseover", this, this.mouseoverhandler);
	FreeMapEvent.link(this.zoomStick, "mouseout", this, this.onmouseouthandler);
	this.fpBindOnRedraw = FreeMapEvent.bind(this.parentObj, "redraw", this, this.redrawHandler);

	this.zoomScaler = FreeMapImage.create(this.scalerImgURL, 40, 136, 28, 60, 10);
	this.zoomScaler.style.filter = 'alpha(Opacity=70)';
	this.zoomScaler.style.border = 'none';
	this.appendChild(this.zoomScaler);
	FreeMapEvent.link(this.zoomScaler, "click", this, this.setScale);
	FreeMapEvent.link(this.zoomScaler, "mouseover", this, this.mouseoverhandler);
	FreeMapEvent.link(this.zoomScaler, "mouseout", this, this.onmouseouthandler);

	this.zoomInBtn = FreeMapImage.create(this.plusImgURL, 14, 14, 35, 66, 10);
	this.zoomInBtn.style.filter = 'alpha(Opacity=70)';
	this.appendChild(this.zoomInBtn);
	setCursor(this.zoomInBtn, "pointer");
	FreeMapEvent.link(this.zoomInBtn, "click", this, this.onZoomIn);
	FreeMapEvent.link(this.zoomInBtn, "mouseover", this, this.mouseoverhandler);
	FreeMapEvent.link(this.zoomInBtn, "mouseout", this, this.onmouseouthandler);

	this.zoomOutBtn = FreeMapImage.create(this.minusImgURL, 14, 14, 35, 178, 10);
	this.zoomOutBtn.style.filter = 'alpha(Opacity=70)';
	this.appendChild(this.zoomOutBtn);
	setCursor( this.zoomOutBtn, "pointer");
	FreeMapEvent.link(this.zoomOutBtn, "click", this, this.onZoomOut);
	FreeMapEvent.link(this.zoomOutBtn, "mouseover", this, this.mouseoverhandler);
	FreeMapEvent.link(this.zoomOutBtn, "mouseout", this, this.onmouseouthandler);

	if (!bIsMSIE) {
		FreeMapEvent.link(this.zoomScaler, "mouseout", this, this.onDragStop);
	}
	FreeMapEvent.bind(this.parentObj, "zoom", this, this.onZoomHandler);

	this.zoomSize();
};

FreeMapZoomControlScourt.prototype.onDragStart = function (evtObj) {
	var e = evtObj || window.event;
	this.stickHiehgt	= evtObj.clientY;
	this.stickTop		= parseInt(this.zoomStick.style.top);
	this.fpDrag			= FreeMapEvent.link(this.zoomStick, "mousemove", this, this.dragHandler);
	this.fpDragStop		= FreeMapEvent.link(this.zoomStick, "mouseup", this, this.onDragStop);
	if (this.zoomStick.setCapture) {
		this.zoomStick.setCapture();
	}
	// FreeMapEvent.disableNotifyEvent(e);
};

FreeMapZoomControlScourt.prototype.showFlashmap = function () {
  FreeMapEvent.trigger(this,"showFlashmap");
};

FreeMapZoomControlScourt.prototype.mouseoverhandler = function () {
  FreeMapEvent.trigger(this,"mouseover");
};

FreeMapZoomControlScourt.prototype.onmouseouthandler = function () {
  FreeMapEvent.trigger(this,"mouseout");
};

FreeMapZoomControlScourt.prototype.dragHandler = function (evtObj) {
	var e = evtObj || window.event;

	if(this.parentObj.mapMode == "circle"){
	  return;
	}
	var curStickHeight =  this.stickTop + evtObj.clientY - this.stickHiehgt;

	if (curStickHeight < 84) {
		curStickHeight = 84;
	}

	if (curStickHeight > 162) {
		curStickHeight = 162;
	}
	this.zoomStick.style.top = curStickHeight + "px";
	// FreeMapEvent.disableNotifyEvent(e);
};

FreeMapZoomControlScourt.prototype.onDragStop = function (evtObj) {
	var e = evtObj || window.event;
	var stickTop = parseInt(this.zoomStick.style.top);
	var zoomLevel = Math.max(Math.min(Math.ceil((155 - stickTop) / 6 + 1), 13), 0);
	if(stickTop == 162)
	  zoomLevel = 0;
	this.parentObj.setZoomLevel(zoomLevel);
	FreeMapEvent.detachEvent(this.zoomStick, "mousemove", this.fpDrag);
	FreeMapEvent.detachEvent(this.zoomStick, "mouseup", this.fpDragStop);

	if (document.releaseCapture) {
		document.releaseCapture();
	}
	// FreeMapEvent.disableNotifyEvent(e);
};

FreeMapZoomControlScourt.prototype.unloadHandler = function () {
	this.removeChild(this.zoomStick);
	this.removeChild(this.zoomScaler);
	this.removeChild(this.zoomInBtn);
	this.removeChild(this.zoomOutBtn);
	this.zoomStick	= null;
	this.zoomScaler	= null;
	this.zoomInBtn	= null;
	this.zoomOutBtn	= null;
	FreeMapLayer.prototype.unloadHandler.call(this);
};

FreeMapZoomControlScourt.prototype.zoomSize = function () {
	this.setSize(new FreeMapSize(70, 200));
	this.zoomStick.style.left = "30px";
	this.zoomScaler.style.left = "28px";
	this.zoomInBtn.style.left = "35px";
	this.zoomOutBtn.style.left = "35px";
};

FreeMapZoomControlScourt.prototype.getFlashmap = function () {
  return this.flashMap;
};

FreeMapZoomControlScourt.prototype.setScale = function (evtObj) {
	var e	= evtObj || window.event;

	if(this.parentObj.mapMode == "circle"){
	  return;
	}
	var pos	= FreeMapEvent.getClickPos(e, e.target||e.srcElement);

	if(pos.y < 23 || pos.y > 110)
	  return;
	var zoomStickHeight = pos.y+57;
	if (zoomStickHeight < 84) {
		zoomStickHeight = 84;
	}
	if (zoomStickHeight > 162) {
		zoomStickHeight = 162;
	}
	var curLevel = Math.max(Math.min(Math.round((162 - zoomStickHeight) / 6 + 1), 13), 1);
	if(zoomStickHeight == 162)
	  curLevel = 0;
	this.parentObj.setZoomLevel(curLevel);
	// FreeMapEvent.disableNotifyEvent(e);
};

FreeMapZoomControlScourt.prototype.onZoomIn = function () {
	this.parentObj.zoomIn();
};

FreeMapZoomControlScourt.prototype.onZoomOut = function () {
	this.parentObj.zoomOut();
};

FreeMapZoomControlScourt.prototype.onZoomHandler = function (curLevel) {
	var stickTop = 156 - (curLevel - 1) * 6;
	this.zoomStick.style.top = stickTop + "px";
};

FreeMapZoomControlScourt.prototype.setZIndex = function (zidx) {
	this.ctrlZIndex = zidx;
};
