// Name: initialize
// Args: parentObj - 부모개체(FreeMapMap)
// Desc: 미니맵과 확대/축소를 위한 엘리먼트 생성및 초기화
// Date: 2006-12-01
// Edit:
FreeMapZoomControlKT.prototype.initialize = function (parentObj) {
	FreeMapLayer.prototype.initialize.call(this, parentObj, true);
	this.bgCon = document.createElement("DIV");
	this.appendChild(this.bgCon);
	this.setZIndex(1);
	this.setBackground();

	this.minimapCon = document.createElement("DIV");
	this.minimapCon.id = 'minimapConDiv';
	this.minimapCon.style.position = 'absolute';
	this.minimapCon.style.width = '189px';
	this.minimapCon.style.height = '128px';
	this.minimapCon.style.left = '20px';
	this.minimapCon.style.top = '8px';
	this.minimapCon.style.border = '1px solid gray';
	this.minimapCon.zIndex = 5;
	this.appendChild(this.minimapCon);
	//this.minimapObj = new FreeMapMinimap(parentObj, "minimapConDiv",this.mType);
	//this.parentObj.minimapObj = this.minimapObj;

	this.fpDragStart = FreeMapEvent.regCallBackFunc(this, this.onDragStart);
	this.fpDrag		 = FreeMapEvent.regCallBackFunc(this, this.dragHandler);
	this.fpDragStop	 = FreeMapEvent.regCallBackFunc(this, this.onDragStop);

	this.zoomStick = FreeMapImage.create(this.stickImgURL, 16, 8, 219, 128, 20);
	this.appendChild(this.zoomStick);
	FreeMapEvent.attachEvent(this.zoomStick, "mousedown", this.fpDragStart);

	this.fpBindOnRedraw = FreeMapEvent.bind(this.parentObj, "redraw", this, this.redrawHandler);

	this.zoomScaler = FreeMapImage.create(this.scalerImgURL, 12, 93, 221, 26, 10);
	this.zoomScaler.style.border = 'none';
	this.appendChild(this.zoomScaler);
	FreeMapEvent.link(this.zoomScaler, "click", this, this.setScale);

	this.zoomInBtn = FreeMapImage.create(this.plusImgURL, 14, 14, 220, 8, 10);
	this.appendChild(this.zoomInBtn);
	setCursor(this.zoomInBtn, "pointer");
	FreeMapEvent.link(this.zoomInBtn, "click", this, this.onZoomIn);

	this.zoomOutBtn = FreeMapImage.create(this.minusImgURL, 14, 14, 220, 122, 10);
	this.appendChild(this.zoomOutBtn);
	setCursor( this.zoomOutBtn, "pointer");
	FreeMapEvent.link(this.zoomOutBtn, "click", this, this.onZoomOut);

	this.showHideBtn = FreeMapImage.create(this.showImgURL, 12, 43, 1, 47, 10);
	this.appendChild(this.showHideBtn);
	setCursor( this.showHideBtn, "pointer");
	FreeMapEvent.link(this.showHideBtn, "click", this, this.onToggleMinimap);

	if (!bIsMSIE) {
		FreeMapEvent.link(this.zoomScaler, "mouseout", this, this.onDragStop);
	}
	FreeMapEvent.bind(this.parentObj, "zoom", this, this.onZoomHandler);

	if(!this.bShowMinimap) {
		this.hideMinimap();
	}
	if (bIsMSIE) {
		// 더블클릭 이벤트 막기.
		this.disableDblClick();
	}

};

