// Name: onDragStart
// Desc: 확대/축소 바 버튼 클릭.
// Args: evtObj - 이벤트 발생 개체
// Date: 2006-09-28
// Edit:
FreeMapZoomControlKT.prototype.onDragStart = function (evtObj) {
	var e = evtObj || window.event;
	this.stickHiehgt	= evtObj.clientY;
	this.stickTop		= parseInt(this.zoomStick.style.top);
	this.fpDrag			= FreeMapEvent.link(this.zoomStick, "mousemove", this, this.dragHandler);
	this.fpDragStop		= FreeMapEvent.link(this.zoomStick, "mouseup", this, this.onDragStop);
	if (this.zoomStick.setCapture) {
		this.zoomStick.setCapture();
	}
	// FreeMapEvent.disableNotifyEvent(e);
};

// Name: dragHandler
// Desc: 확대/축소 바 버튼 이동.
// Args: evtObj - 이벤트 개체
// Date: 2006-09-28
// Edit:
FreeMapZoomControlKT.prototype.dragHandler = function (evtObj) {
	var e = evtObj || window.event;
	var curStickHeight =  this.stickTop + evtObj.clientY - this.stickHiehgt;

	if (curStickHeight < 22) {
		curStickHeight = 22;
	}

	if (curStickHeight > 111) {
		curStickHeight = 111;
	}
	this.zoomStick.style.top = curStickHeight;
	// FreeMapEvent.disableNotifyEvent(e);
};

// Name: onDragStop
// Desc: 확대/축소 바 버튼 이동 종료
// Args: evtObj - 이벤트 개체
// Date: 2006-09-28
// Edit:
FreeMapZoomControlKT.prototype.onDragStop = function (evtObj) {
	var e = evtObj || window.event;
	var stickTop = parseInt(this.zoomStick.style.top);
	var zoomLevel = Math.max(Math.min(Math.ceil((104 - stickTop) / 9 + 1), 11), 1);
	this.parentObj.setZoomLevel(zoomLevel);
	FreeMapEvent.detachEvent(this.zoomStick, "mousemove", this.fpDrag);
	FreeMapEvent.detachEvent(this.zoomStick, "mouseup", this.fpDragStop);

	if (document.releaseCapture) {
		document.releaseCapture();
	}
	// FreeMapEvent.disableNotifyEvent(e);
};

// Name: setScale
// Desc: 확대/축소 레벨 설정.
// Args: evtObj - 이벤트 개체
// Date: 2006-09-28
// Edit:
FreeMapZoomControlKT.prototype.setScale = function (evtObj) {
	var e	= evtObj || window.event;
	var pos	= FreeMapEvent.getClickPos(e, e.target||e.srcElement);
	var zoomStickHeight = pos.y;
	if (zoomStickHeight < 0) {
		zoomStickHeight = 0;
	}
	if (zoomStickHeight > 88) {
		zoomStickHeight = 88;
	}
	var curLevel = Math.max(Math.min(Math.round((88 - zoomStickHeight) / 9 + 1), 11), 1);
	this.parentObj.setZoomLevel(curLevel);
	// FreeMapEvent.disableNotifyEvent(e);
};

