// Name: unloadHandler
// Desc: unload 시 처리
// Date: 2006-09-28
// Edit:
FreeMapZoomControlKT.prototype.unloadHandler = function () {

	if(this.minimapObj) {
		this.minimapObj.unloadHandler();
		this.minimapObj = null;
	}

	if(this.bgCon) {
		this.bgCon.innerHTML = "";
		this.removeChild(this.bgCon);
	}
	this.removeChild(this.zoomStick);
	this.removeChild(this.zoomScaler);
	this.removeChild(this.zoomInBtn);
	this.removeChild(this.zoomOutBtn);
	this.zoomStick	= null;
	this.zoomScaler	= null;
	this.zoomInBtn	= null;
	this.zoomOutBtn	= null;
	this.parentObj.minimapObj = null;
	FreeMapLayer.prototype.unloadHandler.call(this);
};

// Name: onToggleMinimap
// Desc: 미니맵 숨김/표시 토글
// Date: 2006-10-02
// Edit:
FreeMapZoomControlKT.prototype.onToggleMinimap = function () {
	if (this.bShowMinimap) {
		this.hideMinimap();
	}
	else {
		this.showMinimap();
	}
	this.setBackground();
};

