/**
 * 좌표변환 정보
 * label : EPSG:4326  - WGS84 / 경위도
 * label : EPSG:4004  - Bessel / 경위도
 * label : EPSG:4019  - GRS80 / 경위도
 * label : EPSG:3857  - Google Mercator
 * label : EPSG:32651 - WGS84 / UTM51N
 * label : EPSG:32652 - WGS84 / UTM52N
 * label : EPSG:2096  - Bessel / 보정안된 국토지리정보원 표준-동부원점
 * label : EPSG:2097  - Bessel / 보정안된 국토지리정보원 표준-중부원점
 * label : EPSG:2098  - Bessel / 보정안된 국토지리정보원 표준-서부원점
 * label : EPSG:5173  - Bessel / 보정된 국토지리정보원 표준-보정된 서부원점 KLIS
 * label : EPSG:5174  - Bessel / 보정된 국토지리정보원 표준-보정된 중부원점 KLIS
 * label : EPSG:5175  - Bessel / 보정된 국토지리정보원 표준-보정된 제주원점 KLIS
 * label : EPSG:5176  - Bessel / 보정된 국토지리정보원 표준-보정된 동부원점 KLIS
 * label : EPSG:5177  - Bessel / 보정된 국토지리정보원 표준-보정된 울릉원점 KLIS
 * label : EPSG:5178  - Bessel / UTM-K 도로명주소지도
 * label : EPSG:5179  - GRS80 / UTM-K 네이버지도
 * label : KATEC      - Bessel / KATEC 카이네스
 * label : EPSG:5180  - GRS80 / 국토지리정보원 표준-서부원점-falseY:500000
 * label : EPSG:5181  - GRS80 / 국토지리정보원 표준-중부원점-falseY:500000
 * label : EPSG:5182  - GRS80 / 국토지리정보원 표준-제주원점-falseY:550000
 * label : EPSG:5183  - GRS80 / 국토지리정보원 표준-동부원점-falseY:500000
 * label : EPSG:5184  - GRS80 / 국토지리정보원 표준-울릉원점-falseY:500000
 * label : EPSG:5185  - GRS80 / 현재 국토지리정보원 표준-서부원점-falseY:600000
 * label : EPSG:5186  - GRS80 / 현재 국토지리정보원 표준-중부원점-falseY:600000
 * label : EPSG:5187  - GRS80 / 현재 국토지리정보원 표준-동부원점-falseY:600000
 * label : EPSG:5188  - GRS80 / 현재 국토지리정보원 표준-울릉원점-falseY:600000
 * @param point
 * @returns {x,y}
 */

function getEPSG(vStr)
{
    var outEPSG = "";
    var arrEPSG = new Array("KATEC", "EPSG:4326", "EPSG:4004", "", "", "", "EPSG:32652", "EPSG:32651", "", "", "EPSG:5186", "EPSG:5179");

    for ( var i = 0; i < arrEPSG.length; i++) {
        outEPSG = arrEPSG[vStr];
    }

    return outEPSG;
}

function Convert_Point_In_Out(vcx, vcy, vintype, vouttype)
{
    var x = vcx;
    var y = vcy;
    var returnPt = {
        x : 0,
        y : 0
    };

    if (!vintype) vintype = "11";
    if (!vouttype) vouttype = "11";

    if (!x || !y || x == 0 || y == 0) {
        // alert("좌표 변환", "입력 좌표 없음");
        return returnPt;
    }

    var tmpInType = new Proj4js.Proj(getEPSG(vintype));
    var tmpInOutType = new Proj4js.Proj(getEPSG(vouttype));
    var tmpPt = new Proj4js.Point(x + "," + y);

    var transPt = new Array();
    if (tmpInType != tmpInOutType) {
        transPt = Proj4js.transform(tmpInType, tmpInOutType, tmpPt);
        returnPt.x = transPt.x;
        returnPt.y = transPt.y;
    } else {
        transPt.x = x;
        transPt.y = y;
    }

    return returnPt;
}

