function Convert_WGS84_KATEC(point)
{
    var x = point.x;
    var y = point.y;
    var returnPt = {
        x : 0,
        y : 0
    };

    if (!x || !y || x == 0 || y == 0) {
        // alert("좌표 변환", "입력 좌표 없음");
        return returnPt;
