    var wgs84 = new Proj4js.Proj('EPSG:4326'); // 경위도(WGS84)
    var katec = new Proj4js.Proj('KATEC'); // KATEC

    var tmpPt = new Proj4js.Point(x + "," + y);
    var transPt = Proj4js.transform(wgs84, katec, tmpPt);

    returnPt.x = transPt.x;
    returnPt.y = transPt.y;

    return returnPt;
}

// 좌표 변환
function Convert_KATEC_WGS84(point)
{
    var x = point.x;
    var y = point.y;
    var returnPt = {
        x : 0,
        y : 0
    };

    if (!x || !y || x == 0 || y == 0) {
        // alert("좌표 변환", "입력 좌표 없음");
        return returnPt;
    }

    var katec = new Proj4js.Proj('KATEC'); // KATEC
    var wgs84 = new Proj4js.Proj('EPSG:4326'); // 경위도(WGS84)

    var tmpPt = new Proj4js.Point(x + "," + y);
    var transPt = Proj4js.transform(katec, wgs84, tmpPt);

    returnPt.x = transPt.x;
    returnPt.y = transPt.y;

    return returnPt;
}

