let _MAP, _DRAW_GRAPHICS;

var pgjMap = function(map){
	_MAP = map;
	_DRAW_GRAPHICS = new FreeMapGraphics(_MAP);

	_MAP.divCon.oncontextmenu = function(){
		return false;
	}
}

pgjMap.getMap = function(){
	return _MAP;
}

pgjMap.getGraphics = function(){
	return _DRAW_GRAPHICS;
}

pgjMap.makeMarker = function(param){
	const x = param.x || '';
	const y = param.y || '';
	const title = param.title || '';
	const mkId = param.mkId || '';
	const imgSrc = param.imgSrc || '/pgj/cm/images/map/map_area_01.gif';
	const mkGrp = param.mkGrp || 999;
	const icon = new FreeMapIcon(imgSrc ,new FreeMapSize(0, 0));
	const marker = new FreeMapMarker(new FreeMapPoint(x, y), icon, mkId);

//	if(cbFunc !== ''){
//		FreeMapEvent.addListener(marker, 'mousedown', function(){
//			console.log('asdasd')
//		});
//	}

	_MAP.addLayer(marker, mkGrp);
	const label = new FreeMapInfoWin();
	marker.setLabel(label);
	// 지도 MarkUp 크기 설정
	marker.setContents("<table width=120px height=29px border=0 background='" + imgSrc+ "' style='table-layout:fixed;'><tr><td height=17 align=center nowrap><a href='#' id="+mkId+" style='text-decoration:none'><font class='marker' style='font-size:11px;color:white;'><b>"+title+"</b></font></a></td></tr><tr><td height=5></td></tr></table>");
	marker.setLabelOffset(new FreeMapPoint(-73,1));
	marker.showLabel();
}

pgjMap.removeAllMarker = function(){
	for(let i = _MAP.arrMkCtrl.length - 1; i >= 0; i--){
		_MAP.arrMkCtrl[i].unloadHandler();
	}
}

pgjMap.getMkByMkId = function(mkId){
	return _MAP.arrMkCtrl.find(e => e.getMkId() === mkId);
}

pgjMap.setHighLightMkByMkId = function(mkId){
	for(let i = 0; i < _MAP.arrMkCtrl.length; i++){
		let zIndex = 0
		if(_MAP.arrMkCtrl[i].getMkId() === mkId){
			zIndex = 100;
		}
		_MAP.arrMkCtrl[i].label.infoDiv.style.zIndex = zIndex;
	}
}

pgjMap.removeMarkerByGrp = function(grpId){
	_MAP.removeKeyLayers(grpId);
}

pgjMap.setMeasure = function(parma){
	const mod = parma.mod || '01'
	let _mod;
	console.log(_mod)
	switch(mod){
	case '01' :
		_mod = 'line'
		break;
	case '02' :
		_mod = 'area'
		break;
	case '03' :
		_mod = 'normal'
		break;
	case '04' :
		_mod = 'mypin'
		break;
	}
	_DRAW_GRAPHICS.setDrawMode(_mod);
}

pgjMap.deleteObj = function(idx){
	_DRAW_GRAPHICS.deleteObj(idx);
}

