******************************************************************/

/* base */
*{box-sizing:border-box}
html,body{margin:0;padding:0;font-family: 'Noto Sans KR', 'Roboto','Malgun Gothic', '맑은고딕', sans-serif!important;}
body{_min-width: 1800px; color:#000;font-style:normal;-webkit-text-size-adjust:none;}/* -webkit-text-size-adjust:none 웹표준 검사에 오류로 표시 */
