.inner_wrap::after {display: block;content: ''; clear: both;}
.ly_column {float: left;min-width: 15px;min-height: 15px;margin: 0;padding: 0 15px;box-sizing: border-box;}
.ly_column:first-child{padding-left:0 !important}
.ly_column:last-child{padding-right:0 !important}

.col_1{width:10%}
.col_2{width:20%}
.col_3{width:30%}
.col_4{width:40%}
.col_5{width:50%}
.col_6{width:60%}
.col_7{width:70%}
