.w2tb .tb_noti::before {position: absolute; top: 2px; left: 0; width: 13px; height: 14px; content: ''; background: url(/pgj/cm/images/contents/ico_noti_tb1.png) center no-repeat;}

.w2tb .tb_txt{margin-right:10px;}
.w2tb .inp + .tb_txt {margin:0 8px 0 0;}
.w2tb .noti.icon + .w2textbox {display:inline-block;margin-left:4px;}
.w2tb .chk + .noti.icon{margin-left:4px;}
.w2tb .tb_txt {color:#767676;}
.w2tb .tb_fr {float:right;margin:12px;}

/* tb_ty1 (입력테이블) */
.w2tb.tb_ty1{margin-bottom: 10px;}

/* tb_ty2 행방향 입력테이블 - 관련사건등록  */
.w2tb.tb_ty2{margin-bottom: 10px;}

/* tb_view(출력테이블) */
.w2tb.tb_view{margin-bottom: 10px;}
.w2tb.tb_view .w2tb_th,
.w2tb.tb_view .w2tb_td {height:28px;}

/* tb_list */
.w2tb.tb_list{margin-bottom: 10px;}
.w2tb.tb_list td {border-right: 1px solid #edeeef; text-align:center;}
.w2tb.tb_list td:last-child {border-right:none;}
.w2tb.tb_list .w2tb_th {text-align:center;}

.w2tb.tb_list .w2tb_th,
.w2tb.tb_list .w2tb_td {height:28px;}

.w2tb .w2tb_td span{margin-right:5px;}

/*tb_list > group*/
.w2tb.tb_list .tb_group{margin:8px 0;}
.w2tb.tb_list .tb_group .w2tb.tb_list{margin-top:5px;}

/* 테이블 내 테이블인 경우 그룹으로 분리 - 웹접근성문제 탭키 순서  */
.tb_div{display: table}
.tb_div > div {display: table-cell;}
.tb_div > div.b_style {border-top: 1px solid rgba(30,42,76,.8);border-bottom: 1px solid #e1e3e5;background: #f4f6f8;}

/* 테이블 타이틀 옆 추가 정보 - 사건조회 사건기본정보 타이틀 */
.title_info {position: absolute;top: 6px;left: 150px;margin:4px 0 0 20px;padding:0 0 0 3px;display: inline-block;background:url(/pgj/cm/images/contents/bg_df_menu_num_ico.png) no-repeat 0 6px;letter-spacing: -.5px;}
.title_info ul li {position:relative;display:inline-block;padding: 0 8px;line-height:16px;font-size:14px;color:#5a5a5a;font-weight:600;}
.title_info ul li:before {content: "";height:14px; width:1px;background-color:#cdcdcd;display: block;position: absolute;right: 0;top:1px;}
.title_info ul li:last-child:before {content: unset;}
.title_info ul li.big {font-size:15px;}

/* 테이블 타이틀 옆 추가 정보 - 사건조회 사건기본정보 타이틀 */
.b_info li:first-child {background:url(/pgj/cm/images/contents/bg_df_menu_num_ico.png) no-repeat 0 6px;letter-spacing: -.5px;}
.b_info li {position:relative;display:inline-block;padding: 0 8px;line-height:16px;font-size:14px;color:#5a5a5a;font-weight:600;vertical-align: middle;}
.b_info li:before {content: "";height:14px; width:1px;background-color:#cdcdcd;display: block;position: absolute;right: 0;top:1px;}
.b_info li:last-child:before {content: unset;}
.b_info li.big {font-size:15px;}

.b_info2 li:first-child {background:url(/pgj/cm/images/contents/bg_df_menu_num_ico.png) no-repeat 0 6px;letter-spacing: -.5px;}
.b_info2 li {position:relative;display:inline-block;padding: 0 8px;line-height:16px;font-size:14px;color:#5a5a5a;font-weight:600;vertical-align: middle;}
.b_info2 li:last-child:before {content: unset;}
.b_info2 li.big {font-size:15px;}
.b_info2 li.v_line:before {content: "";height:14px; width:1px;background-color:#cdcdcd;display: block;position: absolute;right: 0;top:1px;}

/* 테이블 table_type1 아닌 박스 안의 체크박스 */
.info_detail_group .w2checkbox .w2checkbox_item, .w2radio .w2radio_item{margin-right:19px;}
.info_detail_group .w2checkbox_label {font-size: 13px; color: #767676; letter-spacing: -.2px;}
.info_detail_group .w2checkbox .w2checkbox_item input[type="checkbox"]{margin-right:7px;}

/* detail list */
.info_detail_group {padding:2px 17px; margin:5px 0; border-radius:3px; background: #f5f5f5;}
.info_detail_item,
.info_detail_cate,
.info_detail_text {display: inline-block; vertical-align: top; font-size: 13px;}
.info_detail_item {margin: 6.5px 0;}
.info_detail_group.mult_line{margin:0;padding:0;}
.info_detail_group.mult_line .info_detail_item{display:block; }

/* 테이블 내 멀티데이터 */
.info_detail_group2 {padding:4px 0; margin:0;}
.info_detail_group2 .info_detail_item{padding:3px 0; margin:0 20px 0 0;}
.info_detail_group2 li:last-child.info_detail_item {margin-right:0;}
.info_detail_group2 .info_detail_item .info_detail_cate,
.info_detail_group2 .info_detail_item .info_detail_text {display: inline-block;font-size:13px;line-height:13px;}
.info_detail_group2 .info_detail_item .info_detail_cate{font-weight:normal;margin-right: 6px;color:#111;}
.info_detail_group2 .info_detail_item .info_detail_text{font-weight:normal;color:#767676;}

/* 투명테이블 - 민사(기본내역) 비고 - 추후 ul li로 변경 확인 필요 */
.tb_trans{margin:2px 0;padding:0;}
.tb_trans .w2tb_th {border:0;padding:0 5px 0 0; text-align: left; background:none; font-size: 13px; font-weight:600; color: #111;}
.tb_trans .w2tb_td {border:0;padding:0 4px 0 0;;font-size: 13px;color:#767676;}
.tb_trans tr:first-of-type .w2tb_th,
.tb_trans tr:first-of-type .w2tb_td,
.tb_trans tr:last-of-type .w2tb_th,
.tb_trans tr:last-of-type .w2tb_td,
.tb_trans tr .w2tb_th,
.tb_trans tr .w2tb_td{border: 0!important;}
.table_type1.tb_view .tb_trans .w2tb_th,
.table_type1.tb_view .tb_trans .w2tb_td{height:20px;}
.tb_trans td > span{line-height: 13px;}
.tb_trans .cate {color: #333; font-weight: 500;}
.tb_trans .txt {margin:0 10px 0 3px; color: #767676;padding:0;}
.tb_trans .txt.num {font-family: 'Roboto', 'NotoSansKR', sans-serif;}

/* 시건 조회 테이블 - 중요정보  텍스트 */
.impo_info{}
.impo_info_txt{display: inline-block;margin:0 14px 0 0;padding:0;height:12px;line-height:13px;font-size:13px;color: #c24557;}

/*------------------------------------------------------------------
[5. GridView ]
------------------------------------------------------------------*/

.grid {margin-top:5px;margin-bottom: 10px;}
.grid + .gvw_count_group{padding:0 0 15px 0;}

/* 그리드  */
.grid.ty1 thead th.gridHeaderTDDefault {border-right: 1px solid #7c8696;}
.grid.ty1 thead th[colspan]{border-bottom: 1px solid #7c8696;}

.w2tb.tb_ty1 .w2tb_th[rowspan]{border-right: 1px solid #edeeef;}

/* 그리드안 아이콘, 버튼  */
/* .grid td.ic_sms {_background:url(/pgj/cm/images/contents/ic_sms.png) 80% 50% no-repeat !important;} */
.grid td.ic_sms .w2grid_input {background:url(/pgj/cm/images/contents/ic_sms.png) 100% 50% no-repeat !important;padding-right: 20px;}
.grid td.ic_file .w2grid_input {background:url(/pgj/cm/images/contents/ic_sms.png) 100% 50% no-repeat !important;padding-right: 20px; cursor:pointer;}

/* 신규추가 */
.gvw_opt_group {border-bottom: 1px solid #e1e3e5; padding: 6px; text-align: center;}

/* 총 건수 */
.gvw_count_group {text-align: left; padding: 11px 0;}
.gvw_count_group span {vertical-align: middle; letter-spacing: -1px; font-size: 13px; color: #767676;}
.gvw_count_group span:not(:last-of-type) {margin-right: 3px;}
.gvw_count_group .count_selected {color: #466ddc;}
.gvw_count_group .split_next::after {position: relative; display: inline-block; vertical-align: top; content: ''; top: 3px; width: 1px; height: 12px; margin: 0 5px 0 7px; background: #d9d9d9;}

/* 사건관리 마우스 오른쪽버튼 팝업메뉴 -  w2grid_contextMenu - userMenu   */
.w2grid_contextMenu {color: #5a5a5a;font-size: 13px;border: 1px solid #cdcdcd;box-shadow: 0 1px 4px rgba(0,0,0,.11);}
.w2grid_contextMenu .userMenu.all.first{margin-top:4px;}
.w2grid_contextMenu .userMenu{position: relative; padding: 0 18px 0 9px;background:8px center no-repeat;}
.userMenu:hover{color: #466ddc;background-color:#f4f6f8;}
.userMenu.w2list_listRow {border: none;}
.userMenu .w2list_listColumn_text {line-height: 12px;padding: 4px 16px 4px 4px;font-size: 13px;}
.userMenu.go .w2list_listColumn_text {padding: 4px 16px 4px 12px;font-size: 13px;}
.userMenu.all .w2list_listColumn_text:before{content: '';    display: inline-block;padding-left:4px;width: 12px; height: 12px;background: url(/pgj/cm/images/contents/ico_ctmenu_all.png) no-repeat;}
.userMenu.go .w2list_listColumn_text:after{content: ''; position: absolute; margin-left: 8px;width: 12px; height: 12px;background: url(/pgj/cm/images/contents/ico_ctmenu_go.png) no-repeat;}
.userMenu.go .w2list_listColumn_text:before{content: ''; display: inline-block; width: 4px; height: 1px; margin-right: 5px;background: #111;vertical-align: middle;}
.userMenu.list .w2list_listColumn_text:before,
.userMenu.tit .w2list_listColumn_text:before{content:''; display:inline-block; width:4px; height:4px; margin-right:4px; background:#333; border-radius:50%; vertical-align:3px;}
.userMenu.tit{cursor:default;margin-top: -2px;margin-bottom: 2px;}
.userMenu.tit:hover{color: #5a5a5a;background-color:#fff;cursor:default}
.userMenu.tit .w2list_listColumn_text{cursor:default}
.userMenu.line {margin:0 12px;background: url(/pgj/cm/images/contents/bg_ct_dot.png) 50% 50% repeat-x;cursor:default}
.userMenu.line:hover{background: url(/pgj/cm/images/contents/bg_ct_dot.png) 50% 50% repeat-x;cursor:default}
.userMenu.line .w2list_listColumn_text {cursor:default}

/* customFormatter 그리드셀내 컴포넌트 추가 0 추후 개뱔 화면 확인 필요 */
.w2grid .cf_txt{margin:0 10px 0 0;border: 0;background:transparent;text-align:right;}
.w2grid .cf_inp{margin:0 10px 0 0;padding: 0 10px; background: #fff; border-radius: 3px;border: 1px solid #cdcdcd; font-size: 14px; color: #5a5a5a; box-sizing: border-box;height: 30px;}

/* 소계 합계  */
.w2grid.mg td.gridBodyDefault {border: 1px solid #e1e3e5;}
.w2grid.mg tbody tr {border-top: 0!important;border-bottom: 0!important;}
.w2grid.mg tbody tr:nth-of-type(even) { background: #fff!important;}

/* 공통그리드 colMerge="true" */
.w2grid.mg2 td.gridBodyDefault {border: 1px solid #e1e3e5;}
.w2grid.mg2 tbody tr {border-top: 0!important;border-bottom: 0!important;}
.w2grid.mg2 tbody tr.w2grid_lastRow {border-bottom: 1px solid #e1e3e5 !important;}

/*------------------------------------------------------------------
[6. SiteMap and Favorites ]
*/

/* 사이트맵  */
.sitemap_wrap {position:relative; width:1200px; margin:26px auto 0 auto;}
.sitemap_wrap .search_area {text-align:center;}
.sitemap_wrap .favorites{position:relative; display: table;width:100%;min-height:14px;padding:0;_margin:0 0 14px;margin-top: 32px;}
.sitemap_wrap .favorites .pgtchkfav {display: table-cell;float: left;_padding:0 0 0 17px; border:none;width:90px; }
.sitemap_wrap .favorites .pgt_fav_tit {font-size:16px; font-weight:bold;}
.sitemap_wrap .favorites .fav_list {display: table-cell; padding-left: 14px; border-left:1px solid #dbdbdb; vertical-align:middle;}
.sitemap_wrap .favorites .fav_list li {_display:inline-block;height:24px; padding-right:14px; line-height:24px;float:left;}
.sitemap_wrap .favorites .fav_list .txt {font-size:15px; color:#466ddc; text-decoration:underline;}
.sitemap_wrap .serchbox {margin-top:25px;}
.sitemap_wrap .serchbox .input_sch_t {width:460px; height:48px;margin:0; padding: 0 10px 0 25px; background:#f5f5f5; border:1px solid #dbdbdb; border-radius:25px; font-size:15px; color:#767676;}
.sitemap_wrap .serchbox .btn_sch_t {width:48px; height:48px;margin-left:10px; background: #1e2a4c url(/pgj/cm/images/contents/btn_search_size_m.png) no-repeat center; border-radius:50%;border: 1px solid #052077; color:#fff;text-indent:-9999px;}
.sitemap_wrap .table_type1 * {box-sizing:border-box; color:#111;}
.sitemap_wrap .table_type1 .w2tb_th {padding:20px 5px 15px 25px; text-align:left; font-size:15px; color:#111; vertical-align:top;}
.sitemap_wrap .table_type1 tr:first-of-type .w2tb_th, .sitemap_wrap .table_type1 tr:first-of-type .w2tb_td {border-top:1px solid #e1e3e5;}
.sitemap_wrap .table_type1 tr .w2tb_th, .sitemap_wrap .table_type1 tr .w2tb_td {border:none;border-top: 1px dotted #e1e3e5;}
.sitemap_wrap .table_type1 .w2tb_td {padding: 20px 6px 20px 25px;}
.sitemap_wrap .listbox {margin-bottom:-20px;}
.sitemap_wrap .listbox .list{padding:0 4px 20px 0;display:inline-block; vertical-align:top;width:240px;}
.sitemap_wrap .listbox .tit {height:18px; font-size:15px; font-weight:bold; color:#1e2a4c;}
.sitemap_wrap .listbox .tit:before{content:''; display:inline-block; width:4px; height:4px; margin-right:9px; background:#333; border-radius:50%; vertical-align:3px;}
.sitemap_wrap .listbox .item {padding:25px 4px 0 20px;}
.sitemap_wrap .listbox .item li {padding-bottom:15px; }
.sitemap_wrap .listbox .item li .txt{font-size:15px;}
.sitemap_wrap .listbox .item li:last-child {padding-bottom:0;}
.sitemap_wrap .listbox .item li:before {content:''; display:inline-block; width:4px; height:.5px; margin-right:2px; background:#111; vertical-align:middle;}
.sitemap_wrap .listbox .item li > a:hover {font-weight:bold; color:#466ddc !important; text-decoration:underline;}
.sitemap_wrap .listbox .item li {padding-left:0;text-indent:-10px;}
.sitemap_wrap .listbox .item li > a {padding-left:2px;text-indent:0;word-break: keep-all;font-size:15px;}
.sitemap_wrap .w2panels_fav .listbox .list {width:auto; padding-right:20px;}
.sitemap_wrap .w2panels_fav .listbox .item {padding:0 4px 0 20px;}
.sitemap_wrap .accordions {border-bottom: 1px solid #cdcdcd;}
.sitemap_wrap .accordions .w2panels_fav .w2panel_title_text:before{content:''; display:inline-block; width:22px; height:22px; margin-right:8px;border-radius: 50%;background:#1e2a4c url(/pgj/cm/images/contents/ico_fav_star1.png) center no-repeat;vertical-align: bottom;}

/* 내부 스크롤바 제거 */
.sitemap_wrap .accordions .w2panels_content_open {overflow: inherit;}

/*------------------------------------------------------------------
[7. ETC ]
*/

/* 컨텐츠 영역 아코디언1 - 제이쿼리기능  */
.accordion_area {position:relative;}
.accordion_area .frm_title_group {}
.accordion_area .frm_title {display:inline-block;}
.accordion_area .frm_title_group .title_info {}
.accordion_area .title_list_updown.active {background:url(/pgj/cm/images/contents/ic_info_down.png) 0 0 no-repeat;}
.accordion_area .tmp_cust_tabutil3 {position:absolute; right:0; display:inline-block;}
.accordion_area > .btn_g {float:right;margin-top:5px;}
.accordion, .accordion .w2panels{border:none;}
.accordion .w2panels_title {display: inline-block;margin-bottom:3px;background:none;vertical-align: top;}
.accordion .w2panels_title .frm_title {margin:0 10px 10px 0; padding:0 14px;}
.accordion .w2panels_title .w2panel_title_text {padding-top:0;}
.accordion .w2panels_title_image {position:absolute;right:0;top:4px;display: inline-block; width:16px;height:16px;cursor: pointer;background:url(/pgj/cm/images/contents/ic_info_down.png) 0 0 no-repeat;}
.accordion .w2panels_title_image_open  {background:url(/pgj/cm/images/contents/ic_info_up.png) 0 0 no-repeat;}
.accordion_area .acdCon{margin-top: 5px;}

/* 컨텐츠 영역 아코디언2 - 아코디언(웹스퀘어)  */
.accordions {max-height:550px; margin:40px 0 30px 0; padding-bottom:15px;border-top:2px solid #111 !important; border-bottom:none; border-left:none; border-right:none; overflow-y:auto;}
.accordions .w2panels {border:none;}
.accordions .w2panels:last-of-type {border-bottom:1px solid #e1e3e5;}
.accordions .w2panels_title {height:45px;background:#fff; border-top:1px solid #e1e3e5; overflow:hidden;}
.accordions .w2panel_title_text {float:left; padding:10px 15px 0 25px; font-size:16px; font-weight:bold; color:#111; vertical-align:middle;}
.accordions .w2panels_title_image {float: right;margin-right: 25px;height:45px; background: url(/pgj/cm/images/contents/ic_sitemap_acor_down.png) no-repeat center;}
.accordions .w2panels_title_image_open {background: url(/pgj/cm/images/contents/ic_sitemap_acor.png) no-repeat center;}

/* 아코디언 1 */
.acd01 {overflow:hidden;border:none; margin-top: -34px;}
.acd01 .w2panels {border:none;}
.acd01 > div > div > div.w2panels_title {padding: 8px 0 0;height:26px;background:transparent;overflow:hidden;float: left;}
.acd01 > div > div > div.w2panels_title .w2panel_title_text {float:right; padding:0 6px; font-size:13px; font-weight:normal; color:#5a5a5a; vertical-align:middle;}
.acd01 > div > div > div.w2panels_title .w2panels_title_image {float: right;height:20px; background: url(/pgj/cm/images/contents/ic_add.png) no-repeat center;}
.acd01 > div > div > div.w2panels_title .w2panels_title_image_open {background: url(/pgj/cm/images/contents/ic_add.png) no-repeat center;}
.acd01 > div > div > div.w2panels_content_open{float:left;}

/* 아코디언 2 */
.acdWrap{position: relative;}
.acd02 {overflow-y:auto;border:none;}
.acd02 .w2panels {border:none;}
.acd02 > div > div > div.w2panels_title {height:36px;background:transparent;overflow:hidden;}
.acd02 > div > div > div.w2panel_title_text {margin-right: 10px;padding:0 0 0 14px;float: left;vertical-align: top; font-size:14px;font-weight:normal;color:#111;height:30px;line-height:36px;background:url(/pgj/cm/images/contents/bg_df_tit_ico_small.png) no-repeat 0 16px;}
.acd02 > div > div > div.w2panels_title_image {height:36px; background: url(/pgj/cm/images/contents/ic_sitemap_acor_down.png) no-repeat center;}
.acd02 > div > div > div.w2panels_title_image_open {background: url(/pgj/cm/images/contents/ic_sitemap_acor.png) no-repeat center;}
.acd02_comp{position: absolute;right: 0;z-index: 2;}

/* 아코디언 3 - 조회조건 영역 아코디언 */
.acd03 {overflow-y:auto;border:none;}
.acd03 .w2panels {border:none;}
.acd03 > div > div > div.w2panels_title {_float: right;height:20px;background:transparent;overflow:hidden;width: 100%;text-align: right;}
.acd03 > div > div > div.w2panels_title .w2panel_title_text {padding:0; font-size:0;}
.acd03 > div > div > div.w2panels_title .w2panels_title_image {float: right;height:20px; background: url(/pgj/cm/images/contents/ic_sitemap_acor_down.png) no-repeat center;}
.acd03 > div > div > div.w2panels_title .w2panels_title_image_open {background: url(/pgj/cm/images/contents/ic_sitemap_acor.png) no-repeat center;}

/* 아코디언 4 */
.acd04 {overflow-y:auto;border:none;border-bottom:1px solid #e1e3e5;}
.acd04 .acdCon{margin:10px 0 15px 0;}
.acd04 .w2panels {border:0;}
.acd04 > div > div > div.w2panels_title {height:42px;background:transparent;overflow:hidden;border-top:1px solid #e1e3e5;padding: 0 14px;}
.acd04 > div > div > div.w2panels_title > .w2panel_title_text {padding:0 0 0 32px;float: left;vertical-align: top; font-size:15px;font-weight:normal;color:#111;height:42px;line-height:42px;background:url(/pgj/cm/images/contents/bg_df_tit_ico.png) no-repeat 0 50%;}
.acd04 > div > div > div.w2panels_title > .w2panels_title_image {position:absolute;right:14px;top:0;height:42px; background: url(/pgj/cm/images/contents/ic_sitemap_acor_down.png) no-repeat center;}
.acd04 > div > div > div.w2panels_title > .w2panels_title_image_open {background: url(/pgj/cm/images/contents/ic_sitemap_acor.png) no-repeat center;}
.acd04 > div > div > div.w2panels_content_open{border-top:1px solid #e1e3e5;}

/* 타이틀 버튼있는경우 */
.acd04_comp{position: absolute;right: 0;top: 6px;z-index: 2;}

/* 아코디언 5 */
.acd05 {overflow-y:auto;border:none;border-bottom:1px solid #e1e3e5;}
