#mf_map {
    position: absolute;
    z-index: 0;
    width: 100%;
    height: calc(100% - 45px);
    border: none;
    border-width: 0;
    margin-top: 45px;
}

.marker {
    font-family: "Dotum", "Arial";
    line-height: 15px;
}

#mf_mapControll{
    width: calc(100% - 454px);
