				var searchEvent = com.dataListFilter(gcm.shortcutComp.getID(), "programCd == '" + activeWindowInfo["programCd"]
						+ "' && COMPLEX_KEY == '" + complex + "' && LAST_KEY == '" + eventKey + "'", false);
				if (typeof searchEvent == "undefined" || searchEvent.length == 0) {
					searchEvent = com.dataListFilter(gcm.shortcutComp.getID(), "programCd == 'TOP' && COMPLEX_KEY == '" + complex
							+ "' && LAST_KEY == '" + eventKey + "'", false);
