        landScape : options.landScape || "false", // String, [defalut: false]
                                                    // 엑셀 프린터 출력시 가로 방향 출력 유무
        fitWidth : options.fitWidth || "1", // String, [defalut: 1] 엑셀 프린터 출력시
                                            // 용지너비
        fitHeight : options.fitHeight || "1", // String, [defalut: 1] 엑셀 프린터
                                                // 출력시 용지높이
        scale : options.scale || "100", // String, [defalut: 100] 엑셀 프린터 출력시
                                        // 확대/축소 배율, scale을 사용할 경우 fitToPage는
                                        // false로 설정 해야 한다.
        pageSize : options.pageSize || "A4" // String, [defalut: A4] 엑셀 프린터 출력시
                                            // 인쇄용지 설정 ( ex) "A3", "A4", "A5",
                                            // "B4" )
    };

    var infoArr = {
        rowIndex : infoArr.rowIndex || 0, // Number, 내용을 표시할 행번호
        colIndex : infoArr.colIndex || 0, // Number, 내용을 표시할 열번호
        rowSpan : infoArr.rowSpan || 0, // Number, 병합할 행의 수
        colSpan : infoArr.colSpan || 0, // Number, 병합할 열의 수
        text : infoArr.text || "", // String, 표시할 내용
        textAlign : infoArr.textAlign || "right", // String, 표시할 내용의 정렬 방법
                                                    // left, center, right
        fontSize : infoArr.fontSize || "10px", // String, font size 설정 20px,
                                                // 10px, 5px
        fontName : infoArr.fontName || "", // String, font name 설정
        color : infoArr.color || "", // String, font color 설정 red, blue,
                                        // green
        fontWeight : infoArr.fontWeight || "", // String, font weight 설정 bold
        drawBorder : infoArr.drawBorder || "true", // String, cell의 border지정
                                                    // true, false
        wordWrap : infoArr.wordWrap || "", // String, cell의 줄 바꿈 기능 true, false
        bgColor : infoArr.bgColor || "" // String, cell의 배경 color 설정 red, blue,
                                        // green
    };

    grdObj.advancedExcelDownload(options, infoArr);
};

/**
 * 설정된 옵션으로 CSV파일을 다운로드 한다.
 *
 * @date 2017.11.30
 * @param {Object}
 *            grdObj GridView Object
 * @param {Object[]}
 *            options JSON형태로 저장된 그리드의 엑셀 다운로드 옵션
 * @param {String}
 *            options.fileName [default: excel.csv] 저장 될 파일 이름
 * @param {String}
 *            [options.type] [default: 1] Grid 저장 형태 (0이면 데이터 형태,1이면 표시 방식)
 * @param {String}
 *            [options.delim] [default: ,] CSV 파일에서 데이터를 구분할 구분자
 * @param {String}
 *            [options.removeColumns] [default: 없음] 저장 하지 않을 columns index,
 *            여러컬럼인 경우 콤마(,)로 구분해서 정의 한다.
 * @param {String}
 *            [options.header] [default: 1] Grid의 숨겨진 Column에 대한 저장 여부(0이면 저장 하지
 *            않음,1이면 저장)
 * @param {String}
 *            [options.hidden] [defalut: 0] Grid의 숨겨진 Column에 대한 저장 여부(0이면 저장 하지
 *            않음,1이면 저장)
 * @param {String}
 *            [options.checkButton] [default: 1] Grid의 Control(Check, Radio,
 *            Button) Column에 대해 히든 여부 (0이면 control Column히든,1이면 보여줌)
 * @param {String}
 *            [options.saveList] [default: 없음] hidden에 관계없이 저장할 column id들의
 *            array
 * @memberOf com
 * @return {file} CSV file
 * @author InswaveSystems var gridId = "grd_AdvancedExcel"; var options = {
 *         fileName : "downLoadCSV.csv" //[default : excel.csv] options.fileName
 *         값이 없을 경우 default값 세팅 }; com.downLoadCSV(grdObj, options); //return
 *         예시) 엑셀 파일 다운로드
 */
com.downLoadCSV = function(grdObj, options) {
    var options = {
        fileName : options.fileName || "excel.csv", // [default: excel.csv] 저장 될
                                                    // 파일 이름
        type : options.type || "1", // [default: 1] Grid 저장 형태 (0이면 데이터 형태,1이면
                                    // 표시 방식)
        delim : options.delim || ",", // [default: ,] CSV 파일에서 데이터를 구분할 구분자
        removeColumns : options.removeColumns || "", // [default: 없음] 저장 하지
                                                        // 않을 columns index,
                                                        // 여러컬럼인 경우 콤마(,)로 구분해서
                                                        // 정의 한다.
        header : options.header || "1", // [default: 1] Grid의 숨겨진 Column에 대한 저장
                                        // 여부(0이면 저장 하지 않음,1이면 저장)
        hidden : options.hidden || 0, // [defalut: 0] Grid의 숨겨진 Column에 대한 저장
                                        // 여부(0이면 저장 하지 않음,1이면 저장)
        checkButton : options.checkButton || "1", // [default: 1] Grid의
                                                    // Control(Check, Radio,
                                                    // Button) Column에 대해 히든 여부
                                                    // (0이면 control
        // Column히든,1이면 보여줌)
        saveList : options.saveList || "" // [default: 없음] hidden에 관계없이 저장할
                                            // column id들의 array
    }
    grdObj.saveCSV(options);
};

/**
 * 엑셀 업로드 옵션을 설정하고 확장자 별로 다른 함수(uploadCSV || uploadExcel)를 호출한다.
 *
 * @date 2017.11.30
 * @param {Object}
 *            grdObj 그리드뷰 아이디
 * @param {Array}
 *            options JSON형태로 저장된 그리드의 엑셀 업로드 옵션
 * @param {String}
 *            type 타입(xls, xlsx, csv)을 구분 후, 적합한 API를 사용하여 업로드 한다.
 * @memberOf com
 * @author InswaveSystems
 * @example var gridId = "grd_AdvancedExcel"; var type = "xlsx"; var options = {
 *          fileName : "gridDataUpload.xlsx" // default값이 존재하지 않으므로 꼭 fileName
 *          값을 넣어야 한다. }; com.gridDataUpload(grdObj, type, options); //return
 *          예시) com.js의 다른 함수(uploadCSV, uploadExcel)로 이동하거나 alert 발생
 */
com.gridDataUpload = function(grdObj, type, options) {
    type = type.toLowerCase();

    if (type == "csv") {
        com.uploadCSV(grdObj, options);
    } else if (type == "xls" || type == "xlsx") {
        com.uploadExcel(grdObj, options);
    } else {
        com.win.alert("지원하지 않는 파일 형식입니다.");
    }
};

/**
 * 엑셀 xls, xlsx 업로드
 *
 * @date 2017.11.30
