/**
 *
 * form을 동적으로 생성하여 입력한 파라미터를 변수화하여 post방식으로 submit한다.
 * @date 2016.08.05
 * @ex : com.sendPostForm("/", {param1: "1" , param2:"2" });
 * @memberOf com
 * @author InswaveSystems
 */

com.sendPostForm = function (submitPath, params) {

    var method = "post";
    var form = document.createElement("form");
    form.setAttribute("method", method);
    form.setAttribute("action", submitPath);

    for(var key in params){
        if(params.hasOwnProperty(key)){
            var hiddenField = document.createElement("input");
            hiddenField.setAttribute("type", "hidden");
            hiddenField.setAttribute("name", key);
            hiddenField.setAttribute("value", params[key]);

            form.appendChild(hiddenField);
        }
    }

    document.body.appendChild(form);
    form.submit();
};

/**
 * 문자열 왼쪽에 일정길이(maxLen) 만큼 '0'으로 채우기
 *
 * @date 2014.12.10
 * @param {String}
 *            str 포멧터를 적용할 문자열
 * @param {Number}
 *            maxLen 0 으로 채울 길이
 * @memberOf com
 * @author InswaveSystems
 * @return {String} 일정길이 만큼 0 으로 채워진 문자열
 * @example com.fillZero("24", 4); // return 예시) "0024"
 *
 * com.fillZero("11321", 8); // return 예시) "00011321"
 */
com.fillZero = function(str, maxLen) {
    var len = str;
    var zero = "";

    if (typeof str == 'number')
        len = '' + str;

    if (len.length < maxLen) {
        for (var i = len.length; i < maxLen; i++) {
            zero += "0";
        }
    }
    return (zero + '' + str);
}

