        skipSpace: options.skipSpace || "0",        // String, [defalut: 0, 1]공백무시 여부(1이면 무시 0이면 포함)
        expression: options.expression || "1",      // String, [defalut: 1, 0]expression 컬럼 데이터를 포함하고 있는지 여부, 기본값은 미포함(1이면 미포함, 0이면 포함)
