/**
 * 5.0_4.5245B.20240927.114732_1.5 버전에서 생긴 문제로 이후 버전업 되어을 때 체크 후 삭제 필요
 * autoComplete accessibility설정시 최초 선택 상태 정보 aria-selected 제공 WESD-1782
 */
WebSquare.uiplugin.itemTable.prototype.setSelectedIndex = function(idx, options) {
 if (!this.dom.tds || this.dom.tds.length === 0) return;
 var options = options || {};
 idx = (idx < 0) ? 0 : (idx >= this.dom.tds.length) ? this.dom.tds.length - 1 : idx;
 this.removeClass(this.selectedCell, this.options.w2table_col_over);
 if (this.options.parentPluginName === "autoComplete_input" && this.selectedCell) {
     this.selectedCell.setAttribute("aria-selected","false");
 }
 this.selectedCell = this.dom.tds[idx];
 this.addClass(this.selectedCell, this.options.w2table_col_over);
 if (this.options.parentPluginName === "autoComplete_input") {
     this.selectedCell.setAttribute("aria-selected","true");
 }
 if (this.options.tableRender == "ul" && (this.options.parentPluginName !== "checkcombobox" && this.options.parentPluginName !== "autoComplete_input")) {
     if (this.selectedCell.childNodes[0]) {
         this.selectedCell.childNodes[0].focus();
     }
 }
 if (this.selectedCell.offsetTop > this.render.offsetHeight / 2) {
     var rowCount = Math.min(this.getItemCount(), this.rowCount);
     var topPositionedCell = this.dom.tds[idx - parseInt(rowCount / 2)];
     this.render.scrollTop = topPositionedCell.offsetTop;
 } else {
     this.render.scrollTop = 0;
 }
 if (this.onchangeFunc && options.noChangeFunc !== true) {
     this.onchangeFunc(idx);
 }
};

/**
 * 5.0_4.5245B.20240927.114732_1.5 버전에서 생긴 문제로 이후 버전업 되어을 때 체크 후 삭제 필요
 * autoComplete talkback 에서 읽기 WESD-1783
 */
WebSquare.uiplugin.itemTable.prototype.toHTML = function() {
    var htmlStr = [];
    var styleStr = (this.options.style == "") ? "" : "style='" + this.options.style + "'"; //style
    var depthStr = "";
    if (this.options.depthColumn) {
        depthStr = this.options.w2table_main_depth + " ";
    }
    var tabIndexStr = (this.options.parentPluginName === "autoComplete_input" && WebSquare.util.isMobile()) ? "" : " tabIndex='0'";
    htmlStr.push("<div id='" + this.id + "' " + styleStr + " class='" + this.options.w2table + " " + depthStr + this.options.className + "' " + tabIndexStr + ">");
    if (this.options.checkbox == true && this.options.navBtn == true) {
        htmlStr.push("<div id='" + this.id + "_wrapper' aria-expanded='true' " + styleStr + " class='" + this.options.w2table + " " + this.options.className + "' tabIndex='0'></div>");
        htmlStr.push("<div id='" + this.id + "_btn_div' class='w2checkcombobox_btn_div'></div>");
    }
    htmlStr.push("</div>");
    return htmlStr.join("");

};


/**
 * WESD_1791
 * gridVew 정렬시 가로스크롤를 이동하는 현상 수정 (2024.11.15)
 */
WebSquare.uiplugin.gridView.prototype.headerClick = function(e, srcElem, options) {
    this.focusedByApi = false;
    if (this.options.tooltipHeader) {
        this.hideTooltip();
    }
    var dataHeader_id = WebSquare.util.getDataPrefix("header_id");
    var dataSortable = WebSquare.util.getDataPrefix("sortable");
    var headerId = srcElem.getAttribute(dataHeader_id);
    var isCheckbox = ((this.options.preventMultipleClick || this.options.senseReader) && this.headerInfoHash[headerId]
        && this.headerInfoHash[headerId].options && this.headerInfoHash[headerId].options.inputType === "checkbox");
    if (!isCheckbox) {
        if(this._getHeaderDisabled(headerId) != true) {
            WebSquare.event.fireEvent(this, "onheaderclick", headerId);
        }
    }

    if (this.editedCell != null) {
        this.editedCell.handleEndEdit(e, undefined, options);
    }
    if (this.noevent == true) {
    } else if (this.getDataLength() > 0 && this.options.sortEvent == "onclick" && (this.options.sortable || srcElem.getAttribute(dataSortable) == "true") && !this.groupbyStatus.grouped) {
        this.fireSortEvent(e, srcElem);
        if (this.options.sortHeaderDiv) {
            var targetArr = srcElem.getElementsByTagName("button");
            if (targetArr.length > 0) {
                var targetBtn = targetArr[targetArr.length - 1];
                if (this.options.accessibility !== true) {
                    var scrollXDiv = this.getElementById(this.id + "_scrollX_div");
                    var scrollLeft = this.getElementById(this.id + "_scrollX_right").scrollLeft;;
                    if (scrollXDiv.offsetHeight) {
                        var scrollLeft = this.getElementById(this.id + "_scrollX_right").scrollLeft;;
                        var colSpan = parseInt(srcElem.getAttribute("colSpan")) || 1;
                        var bodyColumnID = this.headerToBodyRelation[headerId];
                        var bodyColumnIndex = this.getColumnIndex(bodyColumnID)
                        var headerWidth = srcElem.offsetWidth;
                        var headerOrgWidth = this.colWidthList[bodyColumnIndex];
                        for (var i = 1; i < colSpan; i++) {
                            headerOrgWidth += this.colWidthList[bodyColumnIndex + i];
                        }
                        var lastBodyColIdx = this.getColumnIndex(bodyColumnID) + colSpan - 1;
                        var colWidthSum = 0;
                        for (var i = 0; i <= lastBodyColIdx; i++) {
                            if (this.hiddenList[i] !== true) {
                                colWidthSum += this.colWidthList[i];
                            }
                        }
                        var gap = colWidthSum - (scrollLeft + scrollXDiv.offsetWidth);
                        if (gap > 0) {
                            this.setScrollLeft(scrollLeft + gap);
                        } else {
                            if (headerWidth < headerOrgWidth) {
                                this.setScrollLeft(scrollLeft - (headerOrgWidth - headerWidth));
                            }
                        }
                    }
                }
                WebSquare.util.requestAnimationFrame(function() {
                    targetBtn.focus();
                });
                if (this.options.senseReader == true) {
                    this.addGridScroll(0 - this.rowIndex);
                }
            }
        }
    }
    this.noevent = false;
};

