WebSquare.uiplugin.autoComplete.prototype._setItemTableCommon = function(direction, left, top, tdHeight) {
    try {
        var documentWidth = document.documentElement.clientWidth || document.body.clientWidth || 0;
        var leftAb = WebSquare.style.getAbsoluteLeft(this.render);
        if (documentWidth < (leftAb + this.itemTable.render.offsetWidth)) {
            var leftAbOver = leftAb + this.render.offsetWidth - this.itemTable.render.offsetWidth;
            if (this._itemTableRenderPosition == "body") {
                left = left + this.render.offsetWidth - this.itemTable.render.offsetWidth;
            }
            if (leftAbOver < 0) {
                if (this._itemTableRenderPosition == "body") {
                    left = WebSquare.style.getAbsoluteLeft(this.render);
                }
                var tableWidth = document.body.offsetWidth - 17 - WebSquare.style.getAbsoluteLeft(this.render);
                this.itemTable.setStyle("width", tableWidth + "px");
                if (this.itemTable.getStyle("overflow-x") != "auto") {
                    tdHeight += 20;
                }
                this.itemTable.setStyle("height", tdHeight + "px");
                this.itemTable.setStyle("overflow-x", "auto");
            } else {
                this.itemTable.setStyle("overflow-x", "hidden");
            }
        } else {
            var tableWidth = this.itemTable.render.firstChild.offsetWidth;
            var itemWidth = this.itemTable.render.clientWidth;
            if ((leftAb + tableWidth) < documentWidth && this.itemTable.getStyle("overflow-x") == "auto") {
                var width = (tableWidth > itemWidth) ? tableWidth : itemWidth;
                tdHeight -= 20;
                this.itemTable.setStyle("height", tdHeight + "px");
                this.itemTable.setStyle("width", width + "px");
                this.itemTable.setStyle("overflow-x", "hidden");
            }
        }

        this.itemTableDirection = direction;
        this.itemTable.render.style.left = left + "px";
        this.itemTable.render.style.top = top + "px";
        WebSquare.style.adjustZIndex(this.uuid, this.itemTable.uuid, "itemTable");
    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};
WebSquare.uiplugin.autoComplete.prototype._setItemTableBody = function(direction, tdHeight) {
    try {
        var top = 0;
        if (direction == "up") {
            top = WebSquare.style.getAbsoluteTop(this.render) - this.itemTable.render.offsetHeight;
        } else {
            top = WebSquare.style.getAbsoluteTop(this.render) + this.render.offsetHeight;
        }
        var left = WebSquare.style.getAbsoluteLeft(this.render);

        this._setItemTableCommon(direction, left, top, tdHeight);
    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};

WebSquare.uiplugin.autoComplete.prototype._setItemTableComponent = function(direction, tdHeight) {
    try {
        var top = 0;
        var btop = 0;
        var ptop = 0;
        var bbottom = 0;
        var pbottom = 0;
        if (WebSquare.style.getComputedStyle(this.render, 'border-top-width')) {
            btop = (WebSquare.style.getComputedStyle(this.render, 'border-top-width')).replace('px','')*1;
        }
        if (WebSquare.style.getComputedStyle(this.render, 'padding-top')) {
            ptop = (WebSquare.style.getComputedStyle(this.render, 'padding-top')).replace('px','')*1;
        }
        if (WebSquare.style.getComputedStyle(this.render, 'border-bottom-width')) {
            bbottom = (WebSquare.style.getComputedStyle(this.render, 'border-bottom-width')).replace('px','')*1;
        }
        if (WebSquare.style.getComputedStyle(this.render, 'padding-bottom')) {
            pbottom = (WebSquare.style.getComputedStyle(this.render, 'padding-bottom')).replace('px','')*1;
        }
        if (direction == "up") {
            top = - this.itemTable.render.offsetHeight - (btop + ptop);
        } else {
            top = this.render.offsetHeight - (bbottom + pbottom);
        }

        var left = this.render.offsetWidth - this.itemTable.render.offsetWidth;
        var bleft = 0;
        var pleft = 0;
        if (WebSquare.style.getComputedStyle(this.render, 'border-left-width')) {
            bleft = (WebSquare.style.getComputedStyle(this.render, 'border-left-width')).replace('px','')*1;
