// 1817 gridView accessibility 설정시 setColumnOrder 에러 발생 수정
WebSquare.uiplugin.gridView.prototype._moveColumnByOrder = function(targetElemId, rowArr) {
    try {
        var targetElem = document.getElementById(targetElemId);
        var targetColumnOrder = [];
        var targetRowSpanObj = {};
        var rowCnt = rowArr.length;
        if (isNaN(rowCnt) || rowCnt <= 0) {
            rowCnt = 1;
        }

        for (var i = 0; i < rowCnt; i++) {
            var trElem = targetElem.rows[i];
            if (!trElem) {
                break;
            }
            var stIdx = 0;
            if (i === 0) {
                stIdx = this.defaultColCnt;
            }
            var realIndexMap = {};
            var ep = 0;
            var rp = 0;
            for (var j = stIdx; j < trElem.childNodes.length; j++) {
                while (targetRowSpanObj[i] != undefined && targetRowSpanObj[i][j + ep + rp] != undefined) {
                    rp += targetRowSpanObj[i][j + ep + rp];
                }
                realIndexMap[j + ep - stIdx + rp] = j;
                var colSpan = parseInt(trElem.childNodes[j].getAttribute("colSpan"), 10) || 1;
                if (this.options.lazyDrawHiddenColumn) {
                    if (trElem.childNodes[j].getAttribute("data-lazydrawtd") == "true") {
                        colSpan = 1;
                    }
                }
                var rowSpan = parseInt(trElem.childNodes[j].getAttribute("rowSpan"), 10) || 1;
                if (rowSpan > 1) {
                    for (var t = i; t < i + rowSpan - 1; t++) {
                        if (targetRowSpanObj[t + 1] == undefined) {
                            targetRowSpanObj[t + 1] = {};
                        }
                        if (targetRowSpanObj[t + 1][j - stIdx + ep + rp] == undefined) {
                            targetRowSpanObj[t + 1][j - stIdx + ep + rp] = colSpan;
                        } else {
                            targetRowSpanObj[t + 1][j - stIdx + ep + rp] += colSpan;
                        }
                    }
                }
                if (colSpan > 1) {
                    ep += colSpan - 1;
                }
            }
            var ep2 = 0;
            var rp2 = 0;
            targetColumnOrder[i] = [];
            for (var j = stIdx; j < trElem.childNodes.length; j++) {
                while (targetRowSpanObj[i] != undefined && targetRowSpanObj[i][this.columnOrder[j + rp2 + ep2]] != undefined) {
                    rp2 += targetRowSpanObj[i][this.columnOrder[j + rp2 + ep2]];
                }
                var rIndex = realIndexMap[[this.columnOrder[j - stIdx + ep2 + rp2]]];
                if (rIndex == undefined) {
                    rIndex = 0;
                }
                targetColumnOrder[i].push(rIndex - stIdx);
                var targetObj = trElem.childNodes[rIndex];
                var colSpan = parseInt(targetObj.getAttribute("colSpan"), 10);
                if (this.options.lazyDrawHiddenColumn) {
                    if (targetObj.getAttribute("data-lazydrawtd") == "true") {
                        colSpan = 1;
                    }
                }
                if (colSpan > 1) {
                    ep2 += colSpan - 1;
                }
            }
        }

        for (var i = 0; i < targetElem.rows.length; i++) {
            var stIdx = 0;
            var multiRowIndex = i % rowCnt;
            if (multiRowIndex === 0) {
                stIdx = this.defaultColCnt;
            }
            var trElem = targetElem.rows[i];
            if (WebSquare.util.isIEAllVersion() && WebSquare.util.browserVersion() == "11" && i >= (this.lastIndex + 1) * this.oneRowLength) {
                trElem.style.backgroundColor = "";
            }
            var targetElemArr = [];
            for (var j = 0; j < targetColumnOrder[multiRowIndex].length; j++) {
                targetElemArr.push(trElem.childNodes[targetColumnOrder[multiRowIndex][j] + stIdx]);
            }
            for (var j = 0; j < targetElemArr.length; j++) {
                trElem.appendChild(targetElemArr[j]);
            }
        }
        var diff = rowCnt - targetColumnOrder.length;
        var tempColumnOrder;
        while (diff > 0) {
            if (!tempColumnOrder) {
                tempColumnOrder = this.columnOrder.slice(0);
            }
            targetColumnOrder.push(tempColumnOrder);
            diff--;
        }
        for (var i = 0; i < rowCnt; i++) {
            this._swapItem(rowArr[i], targetColumnOrder[i], 0);
        }
        this.updateStruct(rowArr);
    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};

// 1820  accessibility 속성과 상관없이 input 내부에서 키입력(edit)을 하지 않고 엔터키만 입력시에는 oneditenter 이벤트가 발생
// 엔터키로 포커스 이동은 접근성에 위배 됩니다!  내년에 접근성 마크 갱신 심사 받을때 문제가 될 수 있습니다.
WebSquare.uiplugin.autoComplete.prototype.handleKeydownAccessibilityEvent = function(e) {
    try {
        var keyCode = (e.charCode) ? e.charCode : e.keyCode;

        var ret = true;
        if (this._preventKeyObj[keyCode] === true || this._preventKeyObj["all"] === true) {
            return;
        }
        if (keyCode == 13 && (this.options.disableEdit || !this.editable)) {
            this.handleClickEvent(e);
            return;
        }
        if (this.event.isMe(e, this.dom.input)) {
            this.editmode = true;
            this.inputKeyDown(e, false);
            if (WebSquare.core.browserCheck.moz || WebSquare.core.browserCheck.opera) {
                this.mozTrickCompare();
                util.setInterval(this.mozTrickCompare, {
                    key: this.id + "_mozTrickCompare",
                    caller: this,
                    delay: 10
                });
            }
            var keyCode = (e.charCode) ? e.charCode : e.keyCode;
            var checkFunctionKey = false;
            checkFunctionKey = (keyCode == 40 || keyCode == 38 || (keyCode == 120 && e.ctrlKey) || (keyCode == 121 && e.ctrlKey) || (keyCode == 120) || (keyCode == 121));
            if (checkFunctionKey) {
                if (this.isOpen) {
                    var selectedIndex = this.itemTable.getSelectedIndex();
                    selectedIndex = parseInt(selectedIndex);
                    var newIndex = selectedIndex;
                    if ((keyCode == 120 && e.ctrlKey) || keyCode == 38 || keyCode == 120) {
                        if (this.itemTable.options.noUseUpDownKey !== true) {
                            var bEnd = false;
                            if (newIndex > 0) {
                                newIndex--;
                                if (newIndex == 0 && this.itemTable._getCellHidden(newIndex)) {
                                    newIndex--;
                                    bEnd = true;
                                }
                            } else {
                                bEnd = true;
                            }
                            while (newIndex >= 0 && (this.itemTable._getCellDisabled(newIndex) || this.itemTable._getCellHidden(newIndex))) {
                                newIndex--;
                            }
                            if (newIndex >= 0) {
                                this.itemTable.setSelectedIndex(newIndex);
                            }
                            if (bEnd) {
                                this.itemTable._keyIndex = -1;
                            } else {
                                this.itemTable._keyIndex = newIndex;
                            }
                            this.itemTable._directionKeyPressed = true;
                        }
                    } else if ((keyCode == 121 && e.ctrlKey) || keyCode == 40 || keyCode == 121) {
                        if (this.itemTable.options.noUseUpDownKey !== true) {
                            var cnt = this.itemTable.getItemCount();
                            var bEnd = false;
                            if (newIndex + 1 < cnt) {
                                newIndex++;
                                if (newIndex + 1 == cnt && this.itemTable._getCellHidden(newIndex)) {
                                    newIndex++;
                                    bEnd = true;
                                }
                            } else {
                                bEnd = true;
                            }
                            while (newIndex + 1 <= cnt && (this.itemTable._getCellDisabled(newIndex) || this.itemTable._getCellHidden(newIndex))) {
                                newIndex++;
                            }
                            if (newIndex < cnt) {
                                this.itemTable.setSelectedIndex(newIndex);
                            }
                            if (bEnd) {
                                this.itemTable._keyIndex = cnt;
                            } else {
                                this.itemTable._keyIndex = newIndex;
                            }
                            this.itemTable._directionKeyPressed = true;
                        }
                    }
                } else {
                    if ((keyCode == 121 && e.ctrlKey) || keyCode == 40  || keyCode == 121) {
                        this.mozTrickBuffer = "";
                        this.viewArr = [];
                        for (var i = 0; i < this.itemArr.length; i++) {
                            this.viewArr.push({
                                label: this.itemArr[i].label,
                                value: this.itemArr[i].value,
                                orgLabel: this.itemArr[i].orgLabel,
                                index: i,
                                _hidden: this.itemArr[i]._hidden,
                                _disabled: this.itemArr[i]._disabled
                            });
                        }

                        this.openSubLayer();
                    }
                }
                if (this.itemTable && this.itemTable.selectedCell) {
                    this.dom.input.setAttribute("aria-activedescendant",this.itemTable.selectedCell.id);
                }
                return;
            }

            if (keyCode == 13) {
                if (this.editable) {
                    if (this.options.renderType == "input") {
                        ret = WebSquare.event.fireEvent(this, "oneditenter", e);
                    }
                    this.itemTable.handleKeydownEvent(e);
                    return;
                }
            }
            if (this.options.renderType == "input" && (keyCode == 9 && !e.shiftKey)) {
                return;
            }
            if (keyCode == 9 || keyCode == 13) {
                ret = WebSquare.event.fireEvent(this, "oneditenter", e);
            }
            if (keyCode == 9 || (keyCode == 13 && this.options.nextTabByEnter === true)) {
                this.tabOrderMoveStart = false;
                if (ret !== false) {
                    if (e.shiftKey) {
                        if (this.options.renderType == "input") {
                            this.render.removeAttribute("tabIndex");
                        }
                        if (WebSquare.tabOrder[this.id] != null && WebSquare.tabOrder[this.id]["preTabID"] != null) {
                            this.tabOrderMoveStart = true;
                            WebSquare.event.preventDefault(e);
                        }
                    } else {
                        if (WebSquare.tabOrder[this.id] != null && WebSquare.tabOrder[this.id]["nextTabID"] != null) {
                            this.tabOrderMoveStart = true;
                            WebSquare.event.preventDefault(e);
                        }
                    }
                }
            }
            return;
        } else {
            var keyCode = (e.charCode) ? e.charCode : e.keyCode;
            if (this.options.customToggleKey == keyCode) {
                this.toggle();
                return;
            }
            if (core.browserCheck.opera) {
                if ((keyCode == 18) && !this.isOpen) {
                    this.handleClickEvent(e);
                    return;
                } else if (keyCode == 13 && !this.isOpen) {
                    if (this.options.renderType == "input") {
                        if (!e.target.matches(".w2autoComplete_col_button")) {
                            this.changeMode();
                        }
                    } else {
                        this.changeMode();
                    }
                    return;
                }
            } else {
                if ((keyCode == 40 || keyCode == 38) && !this.isOpen) {
                    this.handleClickEvent(e);
                    WebSquare.event.preventDefault(e);
                    return;
                } else if (keyCode == 13 && !this.isOpen) {
                    if (this.options.renderType == "input") {
                        if (!e.target.matches(".w2autoComplete_col_button")) {
                            this.changeMode();
                        }
                    } else {
                        this.changeMode();
                    }
                    return;
                }
            }
            if (keyCode == 9 || keyCode == 13) {
                ret = WebSquare.event.fireEvent(this, "oneditenter", e);
            }
            if (keyCode == 9 || (keyCode == 13 && this.options.nextTabByEnter === true)) {
                this.tabOrderMoveStart = false;
                if (ret !== false) {
                    if (e.shiftKey) {
                        if (WebSquare.tabOrder[this.id] != null && WebSquare.tabOrder[this.id]["preTabID"] != null) {
                            this.tabOrderMoveStart = true;
                            WebSquare.event.preventDefault(e);
                        }
                    } else {
                        if (WebSquare.tabOrder[this.id] != null && WebSquare.tabOrder[this.id]["nextTabID"] != null) {
                            this.tabOrderMoveStart = true;
                            WebSquare.event.preventDefault(e);
                        }
                    }
                }
            }
            this.findItemStartedWithKeyChar(e, keyCode);
            if (this.itemTable != null && this.viewArr.length > 0) {
                if (this.isOpen == true /*&& this.itemTableMode != "grid" && this.itemTableMode != "gridView"*/ ) {
                    if (keyCode == 27) {
                        this._closeSubLayer();
                        this.showEditMode(false);
                        this.focus();
                    } else {
                        this.itemTable.handleKeydownEvent(e);
                    }
                }
                this.editmode = false;
            } else {
                if (this.itemTable != null) {
                    if (this.itemTable.render.style.display == "") {
                        return;
                    }
                }
            }
        }
        if (this.itemTable != null) {
            if (this.itemTable.render.style.display == "") {
                return;
            }
        }
        return;
    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};

