                newLst = intgGrpLst.filter(function(_do, _di) {
                    return _self.$_h._isIncludesIntgInscrtCd(_do.intgInscrtMtjrCdLstCtt, intgInscrtMtjrCdLstCtt)
                    && _do[keyNm] === mtchVal;
