            var intgGrpCd = 'JDCPC_OFCWK_TASK_TYP_CD';

            _self.loadIntgCdLst(systmCd + scglblo.DELIMITER.HYPHEN + intgGrpCd);

            var allLst = _self.$_h._getAllLst();

            var findIdx = _self.$_h._getAllLst().findIndex(function(_o) {
                return _o.systmCd === systmCd && _o.intgCdOnrIdntId === intgCdOnrIdntId && _o.intgGrpCd === intgGrpCd;
