            var systmCd = scglblo.SYSTM.STG;
            var intgCdOnrIdntId = scglblo.SYSTM.STG;
            var intgGrpCd = 'SYSTM_CD';

            _self.loadIntgCdLst(systmCd + scglblo.DELIMITER.HYPHEN + intgGrpCd);

