     * 코드작업을 진행할 시스템코드를 설정하고, 통합코드주체식별ID도 시스템코드로 설정한다.
     * 
     * @memberOf sccdo
     * 
     * @example ex)
     * sccdo.setSystm(scglblo.SYSTM.STG);
     * 
     * @param {String} systmCd - 시스템코드
     * 
     * @return {boolean} - 성공 여부
     * </pre>
     */
    var setSystm = function(systmCd) {
        var _self = this;
        var hasSystmCd = _self.$_h._getSystmCdLst().findIndex(function(_o) {
            return _o.intgCd === systmCd;
        }) > -1;

        if (hasSystmCd) {
            scscrno.$_h._setSystmCdOfCd(systmCd);
            scscrno.$_h._setIntgCdOnrIdntIdOfCd(systmCd);
            return true;
        } else {
            return false;
        }
    };

    /*
     * ============= ============ ==========================
