    /**
     * <pre>
     * 서버로부터 설정된 시스템, 통합코드주체식별ID 별로 지정한 통합그룹코드 목록을 조회한다.
     * 
     * @memberOf sccdo
     * 
     * @example ex)
     * sccdo.loadIntgCdLst(scglblo.SYSTM.STG + scglblo.DELIMITER.HYPHEN + 'JDCPC_OFCWK_TASK_TYP_CD');
     * sccdo.loadIntgCdLst(scglblo.SYSTM.LBA + scglblo.DELIMITER.HYPHEN + scglblo.TASK.CV + scglblo.DELIMITER.HYPHEN + 'RELT_CS_DVS_CD');
     * sccdo.loadIntgCdLst(scglblo.SYSTM.STG + scglblo.DELIMITER.HYPHEN + 'JDCPC_OFCWK_TASK_TYP_CD' + scglblo.DELIMITER.COMMA + scglblo.SYSTM.LBA + scglblo.DELIMITER.HYPHEN + scglblo.TASK.CV + scglblo.DELIMITER.HYPHEN + 'RELT_CS_DVS_CD&BTPRT_DVS_CD' + scglblo.DELIMITER.COMMA + scglblo.SYSTM.CSD + scglblo.DELIMITER.HYPHEN + 'CS_DVS_CD&DXDY_KND_CD');
     * 
     * @param {String} intgGrpCdLst - 통합그룹코드목록 : "시스템코드-통합그룹코드", "시스템코드-통합코드주체식별ID-통합그룹코드"을 쉼표(,)로 열거한 코드섹션 목록
     * 
     * @return {boolean} - 성공여부
     * </pre>
     */
    var loadIntgCdLst = function(intgGrpCdLst) {
        var _self = this;
        // sccd용 데이터리스트 존재여부
        var isExistsMain = scglblo.$_h._isExistsMainDataClct(scglblo.$_h._getIntgCdDataId());
        var aOptions = intgGrpCdLst.split(scglblo.DELIMITER.COMMA);
        var oFindOptions = [];
        var cdLst = isExistsMain ? _self.$_h._getAllLst() : [];
        aOptions.forEach(function(_optn) {
            _optn = scutilo.getAllTrim(_optn);
            var aOption = _optn.split(scglblo.DELIMITER.HYPHEN);
            var systmCd = aOption[0];
            var intgCdOnrIdntId = aOption.length > 2 ? aOption[1] : aOption[0];
            var intgGrpCds = aOption.length > 2 ? aOption[2] : aOption[1];
            var aIntgGrpCds = intgGrpCds.split("&");
            aIntgGrpCds.forEach(function(intgGrpCd) {
                var findIdx = cdLst.findIndex(function(_o) {
                    return _o.systmCd === systmCd && _o.intgCdOnrIdntId === intgCdOnrIdntId  && _o.intgGrpCd === intgGrpCd;
                });
                if(findIdx === -1) {
                    var optnIdx = oFindOptions.findIndex(function(_o) {
                        return _o.systmCd === systmCd && _o.intgCdOnrIdntId === intgCdOnrIdntId;
                    });
                    if(optnIdx === -1) {
                        oFindOptions.push({
                            systmCd: systmCd,
                            intgCdOnrIdntId: intgCdOnrIdntId,
                            intgGrpCd: [intgGrpCd],
                        });
                    } else {
                        oFindOptions[optnIdx].intgGrpCd.push(intgGrpCd)
                    }
                }
            });
        });
        if (oFindOptions.length > 0) {
            var url = scscrno.$_h._getSystmCtxtPathUrl("/scframe/lib/sccd/list.on");
            // 만일 응용에서 지정한 URL이 존재하면 경로 적용 
            if (scutilo.isNotEmpty(sccdo.$_h._const.SELECT_URL)) url = sccdo.$_h._const.SELECT_URL;
            var params = {
                'intgGrpCdLst': function() {
                    var aParams = [];
                    oFindOptions.forEach(function(_p) {
                        var isSystm = _p.systmCd === _p.intgCdOnrIdntId;
                        var aSubParams = [];
                        aSubParams.push(_p.systmCd);
                        if(!isSystm) {
                            aSubParams.push(_p.intgCdOnrIdntId);
                        }
                        aSubParams.push(_p.intgGrpCd.join('&'));
                        aParams.push(aSubParams.join(scglblo.DELIMITER.HYPHEN));
                    });
                    return aParams.join(scglblo.DELIMITER.COMMA);
                } (),
            };
            com.executeAjax({
                action: url,
                mode: "synchronous",
                mediatype: gcm.DEFAULT_OPTIONS_MEDIATYPE,
                requestData: JSON.stringify(params),
                success: function(_data) {
                    var list = _data.responseJSON.data.sccdLst;
                    // sccd용 데이터리스트가 없으면 먼저 생성한다.
                    if(! isExistsMain) {
                        var dataLstFieldInf = [];
                        if(list.length > 0) {
                            dataLstFieldInf = Object.keys(list[0]);
                        }
                        var scopeId = scutilo.getSCMain().$p.top().$p.getFrameId();
                        var scopeObj = scutilo.getSCMain().$p.getComponentById(scopeId);
                        var dataLstId = scglblo.$_h._createDataLst.call(_self, {
                            scopeId: scopeId,
                            dataId: scglblo.$_h._getIntgCdDataId(),
                            dataLstFieldInf: dataLstFieldInf,
                            getDataFunc: function() {
                                return list;
                            },
                        });
                    } else {
                        // 기존데이터와 조회데이터 취합
                        var newLst = _self.$_h._getAllLst().concat(list);
                        // 정렬
                        newLst.sort(function(a, b) {
                            if(a.systmCd > b.systmCd) return 1;
                            if(a.systmCd < b.systmCd) return -1;
                            if(a.intgCdOnrIdntId > b.intgCdOnrIdntId) return 1;
                            if(a.intgCdOnrIdntId < b.intgCdOnrIdntId) return -1;
                            return 0;
                        });
                    }

                    // 정렬된 데이터로 갱신
                    _self.$_h._getDataLst().setJSON(newLst);
                },
            });
        }
        return true;
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
