     * </pre>
     */
    var getIntgCdLst = function(intgGrpCd) {
        var _self = this;

        var allLst = _self.$_h._getAllLst();
        var systmCd = _self.getSystmCd();
        var intgCdOnrIdntId = _self.getIntgCdOnrIdntId();

        var findIdx = allLst.findIndex(function(_o) {
            return _o.systmCd === systmCd && _o.intgCdOnrIdntId === intgCdOnrIdntId && _o.intgGrpCd === intgGrpCd;
        });

        var newLst = [];
        if(findIdx > -1) {
            for (var idx = findIdx; idx < allLst.length
            && allLst[idx].systmCd === systmCd
            && allLst[idx].intgCdOnrIdntId === intgCdOnrIdntId
            && allLst[idx].intgGrpCd === intgGrpCd; idx++) {
                newLst.push(allLst[idx]);
            }
        }
        return newLst;

    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 해당 통합그룹코드의 코드정보 목록을 웹스퀘어 컴포넌트에 바인딩한다.
     * 
     * 컴포넌트에 바인딩된 dataList 객체를 반환한다.
     * 반환된 dataList의 컬럼명 사용 시 반드시 컴포넌트 ITEMSET 상수를 사용해야한다.
     * (컴포넌트 ITEMSET 상수 : scglblo.CMPNT_ITEMSET.SCCD.label, scglblo.CMPNT_ITEMSET.SCCD.value)
     * 
     * @memberOf sccdo
     * 
     * @example ex)
     * sccdo.bindIntgCdLst('acp_dlvrplDvs', 'DLVRPL_DVS_CD');
     * sccdo.bindIntgCdLst('acp_btprtDvs', 'BTPRT_DVS_CD');
     * sccdo.bindIntgCdLst('acp_btprtDvs', 'BTPRT_DVS_CD').setColumnFilter({
		type:'func', colIndex:scglblo.CMPNT_ITEMSET.SCCD.label, condition:'and',
		key:function(cellData, tmpParam, rowIdx) {
			if(cellData.indexOf("재판") > -1){
				return true;
			}else if(cellData.indexOf("소송") > -1){
				return true;
			}
			return false;   //return이 true인 경우 적용하고 false인 경우 skip한다.
		}}); // 컬럼명은 반드시 컴포넌트 ITEMSET 상수 사용
