     * @example ex)
     * sccorto.getCortNmExtnlJdbn(false, cortCd);
     * sccorto.getCortNmExtnlJdbn(true, cortCd);
     * 
     * @param {String} isInclude - 법원명에 원외재판부명 포함여부(true/false)
     * @param {String} cortCd - 조회하고자 하는 법원코드
     * 
     * @return {String} - 법원명
     * </pre>
     */
    var getCortNmExtnlJdbn = function(isInclude, cortCd) {
        var _self = this;
        if(scutilo.isEmpty(cortCd)) {
            return '';
        } else {
            if(isInclude || ! _self.isExtnlJdbn(cortCd)){ 
                return _self.getFullNm(cortCd);
            }

            return _self.getDscrtNm(cortCd);
        }
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 파라미터 법원의 고법 원외재판부 대상여부를 (true/false) 반환한다.
     * 
     * @memberOf sccorto
     * 
     * @example ex)
     * sccorto.isExtnlJdbn(cortCd);
     * sccorto.isExtnlJdbn("000501"); // true
     * sccorto.isExtnlJdbn("000210"); // false
     * 
     * @param {String} cortCd - 조회하고자 하는 법원코드
     * 
     * @return {Boolean} - 고법 원외재판부 대상여부
     * </pre>
     */
    var isExtnlJdbn = function(cortCd) {
        var _self = this;
        if(scutilo.isEmpty(cortCd)) {
            return false;
        } else {
            var oCort = _self.$_h._getCortInf(cortCd);
            if (!oCort) return false;
            var extnlJdbn = String(scglblo.$_h._getExtnlJdbn()).split(',');
            return extnlJdbn.includes(cortCd);
        }
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
