     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 통계상급법원코드 정보를 기준으로 산하 법원 목록을 반환
     * 
     * @memberOf sccorto
     * 
     * @example ex)
     * sccorto.getLowCortLstByStats('000510', true); --> 통계상급법원코드(stats) 기준 모든 산하 법원목록을 반환
     * sccorto.getLowCortLstByStats('000510', false); --> 통계상급법원코드(stats) 기준 바로 아래 산하 법원목록만 반환
     * 
     * @param {String} cortCd - 법원코드
     * @param {Boolean} isAllLow - 전체 하위법원 조회 여부 - true(하위의 하위 등 모든 하위까지 조회) / false(바로 아래 하위만 조회)
     * 
     * @return {Array} - 산하 법원 목록
     * </pre>
     */
    var getLowCortLstByStats = function(cortCd, isAllLow) {
        var _self = this;
        var result = null;
        com.executeAjax({
            action: scscrno.$_h._getSystmCtxtPathUrl('/scframe/lib/lowCorts/byStats.on'),
            requestData: JSON.stringify({
                cortCd: cortCd,
                isAllLow: isAllLow,
            }),
            mode: "synchronous",
            mediatype: gcm.DEFAULT_OPTIONS_MEDIATYPE,
            //target : 'data:json,[{"id":"dtl_cort","key":"data"}]',
            success: function(_data) {
                result = _data.responseJSON.data.list;
            },
        });
        return result;
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 법원유형코드(cortTypCd)에 해당하는 법원 리스트를 웹스퀘어 컴포넌트에 바인딩한다.
     * 법원유형코드는 구분자없이 여러개 지정 가능하다.
     * 
     * @memberOf sccorto
     * 
     * @example ex)
     * sccorto.bindCortLstByTyp("sbx_cort20", "20");
     * sccorto.bindCortLstByTyp("sbx_cort50", "50");
     * sccorto.bindCortLstByTyp("sbx_cort50", "2050");   //20과 50
     * 
     * @param {String} compId - 웹스퀘어 컴포넌트ID
     * @param {String} cortTypCd - 검색할 법원유형코드
     * </pre>
     */
    var bindCortLstByTyp = function(compId, cortTypCd) {
        var aCortTypCds = [];
        for(var i=0; i<cortTypCd.length; i+=2) {
            aCortTypCds.push(cortTypCd.substr(i, 2));
        }
        var _self = this;
        var scopeId = $p.getFrameId();
        var dataLstId = scglblo.$_h._createDataLst.call(_self, {
            scopeId: scopeId,
            dataId: scglblo.$_h._getCortDataId() + "_" + compId,
            dataLstFieldInf: sccorto.$_h._getDataLst().cellIdList,
            getDataFunc: function() {
                return _self.getCortLst().filter(function(_o) {
                    return aCortTypCds.includes(_o.cortTypCd);
                });
            },
        });
        scglblo.$_h._bindComponentData({
            scopeId: scopeId,
            compId: compId,
            dataLstId: dataLstId,
            label: 'cortFullNm',
            value: 'cortCd',
        });
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 법원 리스트를 웹스퀘어 컴포넌트에 바인딩한다.
     * 
     * @memberOf sccorto
     * 
     * @example ex)
     * sccorto.bindCortLst("sbx_cort");
     * sccorto.bindCortLst("sbx_cort", "Y");
     * 
     * @param {String} compId - 웹스퀘어 컴포넌트ID
     * @param {String} cortAbrvtdNmYN - 법원약칭명 사용여부
     * @param {Boolean} isTest(Options) - 테스트 법원 포함여부
     * </pre>
     */
    var bindCortLst = function(compId, cortAbrvtdNmYN, isTest) {
        var _self = this;
        var scopeId = $p.getFrameId();
        var dataLstId = scglblo.$_h._createDataLst.call(_self, {
            scopeId: scopeId,
            dataId: scglblo.$_h._getCortDataId() + "_" + compId,
            dataLstFieldInf: sccorto.$_h._getDataLst().cellIdList,
            getDataFunc: _self.getCortLst.bind(_self, isTest),
        });
        var cortAbrvtdNmYN = scutilo.isNotEmpty(cortAbrvtdNmYN) ? cortAbrvtdNmYN : 'N';
        scglblo.$_h._bindComponentData({
            scopeId: scopeId,
            compId: compId,
            dataLstId: dataLstId,
            label: cortAbrvtdNmYN === 'Y' ? 'cortAbrvtdNm' : 'cortFullNm',
            value: 'cortCd',
        });
    };

    return {
        $_h: $_h,
        bindCortLst: bindCortLst,
        bindCortLstByTyp: bindCortLstByTyp,
        getBdcrtNm: getBdcrtNm,
        getCortAbrvtdNm: getCortAbrvtdNm,
        getCortLst: getCortLst,
        getCortNmExtnlJdbn: getCortNmExtnlJdbn,
        getCortTypCd: getCortTypCd,
        getDscrtNm: getDscrtNm,
        getFullNm: getFullNm,
        getLowCortLstByStats: getLowCortLstByStats,
        getMccrtNm: getMccrtNm,
        isExtnlJdbn: isExtnlJdbn,
    };
} ();

