    /**
     * <pre>
     * 입력된 사건연도, 사건구분, 사건연번을 하나의 코드화된 DB사건번호로 변환한다.
     * 
     * @memberOf sclibo
     * 
     * @example ex)
     * sclibo.getDbCsNo('2022', '001', '1234567');
     * 
     * @param {String} yr - 사건연도 : 사건접수 연도 
     * @param {String} csDvs - 사건구분 : 사건구분코드
     * @param {String} serl - 사건연번 : 사건접수 일련번호 
     * @return {String} - DB사건번호
     * </pre>
     */
    var getDbCsNo = function(yr, csDvs, serl) {
        var _self = this;
        
        var newYr = scdateo.getYear(yr);
        if (scutilo.isEmpty(newYr)) {
            return "";
        }
        if (scutilo.isEmpty(csDvs)) {
            return "";
        }
        var newSerl = _self.getCsSrno(serl);
        if (newSerl == "")
            return "";

        return newYr + csDvs + newSerl;
    };
    
    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   황훈	       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 입력된 DB사건번호를 사용자용 사건번호로 변환한다.
     * 
     * 반드시 사전에 해당 시스템에 대한 사건구분코드(CS_DVS_CD) 통합코드가 로딩되어 있어야 한다. 
     * 
     * @memberOf sclibo
     * 
     * @example ex)
     * 
     * sccdo.loadIntgCdLst(scglblo.SYSTM.STG + scglblo.DELIMITER.HYPHEN + 'CS_DVS_CD');
     * 
     * sclibo.getUserCsNo('20220721234567', scglblo.SYSTM.STG); // '2022카단1234567'
     * sclibo.getUserCsNo('20220720000123', scglblo.SYSTM.STG); // '2022카단123'
     * 
     * @param {String} csNo - 사건번호 : 변환할 DB사건번호
     * @param {String} systmCd - CS_DVS_CD 사용할 시스템코드
     * 
     * @return {String} - 사용자용 사건번호
     * </pre>
     */
    var getUserCsNo = function(csNo, systmCd) {
        var _self = this;
        if (arguments.length < 2) return "";
        
        var yr = "";
        var csDvsNm = "";
        var serl = "";

        if (parseInt(csNo.substr(0, 2), 10) < 20) {
            yr = csNo.substr(2, 2);
        } else {
            yr = csNo.substr(0, 4);
        }
        serl = String(parseInt(csNo.substr(7, 7), 10));
        
        // 해당 시스템 코드정보에서 사건구분코드로 코드정보 조회  
        var csDvsCd = csNo.substr(4, 3);
        var intgInf = _self.$_h._getSystmIntgInfByCd(systmCd, _self.$_h.INTG_GRP_CD.CS_DVS_CD, csDvsCd);
        csDvsNm = intgInf ? intgInf.intgCdNm : '';
        if(scutilo.isEmpty(csDvsNm)) return ''; // 공통코드 미로딩시 빈값 리턴 
        
        return yr + csDvsNm + serl;
    };
    
    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 입력된 사용자용 사건번호를 분리하여 사건연도, 사건구분, 사건연번 순서대로 반환한다.
     * 
     * @memberOf sclibo
     * 
     * @example ex)
     * sclibo.getUserCsNoToArr('2022카단1234567');
     * 
     * @param {String} csNo - 사건번호 : 분리할 사용자용 사건번호 예) 2022카단1234567
     * 
     * @return {Array} - [사건연도, 사건구분, 사건연번] 배열
     * </pre>
     */
    var getUserCsNoToArr = function(csNo) {
        var _self = this;
        
        var pos = 0;
        var yr = "";
        var csDvsNm = "";
        var csSerl = "";
        var tmp = ""
        csNo = scutilo.skipSpaces(csNo);

        for (var i = 0; i < csNo.length; i++) {
            if (csNo.charAt(i) < "0" || csNo.charAt(i) > "9") {
                pos = i;
                break;
            }
        }
        if (pos == 0) {
            return ['', '', ''];
        }
        
        yr = csNo.substr(0, pos);
        if (yr.length != 2 && yr.length != 4) {
            yr = "";
        } else if (yr.length == 2) {
            yr = scdateo.getYear(yr);
        } else if (scutilo.isEmpty(yr)) {
            yr = "";
        }

        tmp = csNo.substr(pos, csNo.length);
        for (var i = 0; i < tmp.length; i++) {
            if (tmp.charAt(i) >= "0" && tmp.charAt(i) <= "9") {
                pos = i;
                break;
            }
        }
        csDvsNm = tmp.substr(0, pos);
        csSerl = tmp.substr(pos, tmp.length);
        csSerl = _self.getCsSrno(csSerl);
        
        return [yr, csDvsNm, csSerl];
    };
    
