     * 
     * @memberOf sclibo
     * 
     * @example ex)
     * sclibo.getDbCsNoSprt('20220721234567');
     * 
     * @param {String} csNo - 사건번호 : 분리할 DB용 사건번호 예) 20220721234567
     * 
     * @return {Array} - [사건연도, 사건구분, 사건연번] 배열
     * </pre>
     */
    var getDbCsNoSprt = function(csNo) {
        var _self = this;
        
        return [csNo.substr(0, 4), csNo.substr(4, 3), String(parseInt(csNo.substr(7, 7), 10))];
