			if (chkTemp.search(/^[0-9|a-z|A-Z|ㄱ-ㅎ|ㅏ-ㅣ|가-힝|\n]$/) == -1) {
				return true;
	    	}else if(chkTemp == "|") {
	    		return true;
	    	}
	    }
		return false;
	},

