	/**
	 * 쿠키를 set 처리해주는 함수
	 *
	 * param : cookieName(set할 쿠키 Key값),value(해당 key값에 저장할 쿠키값)
	 * param : days(쿠키를 저장해둘 기간 기준: 1을 입력시 10초로 설정됨.)
	 * 		   단,아무것도 기재하지 않을시 계속 저장
	 *
	 *
	 * ============= ============ ==========================
	 *  Date          Author       Description
	 * ============= ============ ==========================
	 *  2022.12.01.   나해준       	[NELS]최초 생성
	 * ============= ============ ==========================
	 */
	setCookie : function(cookieName, value, days) {
	  var exdate = new Date();
	  /* days의 1이 들어가면 10초 설정 */
	  exdate.setTime(exdate.getTime() + days * 10 * 1000); //10초설정
	  // 설정 일수만큼 현재시간에 만료값으로 지정 시간이 없을경우 계속
	  var cookieValue = encodeURIComponent(value) + ((days == null) ? '' : '; expires=' + exdate.toUTCString());
	  document.cookie = encodeURIComponent(cookieName) + '=' + cookieValue;
	},


	/**
	 * 쿠키를 get 처리해주는 함수
	 *
	 * @param : 쿠키를 저장한 key값(쿠키이름), Json디코딩여부 (default = false)
	 *
	 * @return : 해당 key값의 해당하는 value값
	 * 			쿠키에 해당 key값이 없을경우 null 반환
	 *
	 * ============= ============ ==========================
	 *  Date          Author       Description
	 * ============= ============ ==========================
	 *  2022.12.01.   나해준       	[NELS]최초 생성
	 * ============= ============ ==========================
	 */
	getCookie : function(cookieName, jsonflag = false) {
	  var x, y;
	  var cookiArray = document.cookie.split(';');
	  for (var i = 0; i < cookiArray.length; i++) {
	    x = cookiArray[i].substr(0, cookiArray[i].indexOf('='));
	    y = cookiArray[i].substr(cookiArray[i].indexOf	('=') + 1);
	    x = x.replace(/^\s+|\s+$/g, ''); // 앞과 뒤의 공백 제거하기
	    if (x == cookieName) {
	      if (!jsonflag) {
	    	  return unescape(y); // unescape로 디코딩 후 값 리턴
	      } else {
	    	  return JSON.parse(decodeURIComponent(y));
	      }
	    }
	  }
	},


