		, 'ㅍ':   ['45795', '54615']
		, 'ㅎ':   ['54615', '55203']
		, '기타':   ['11111', '35207'] }
	, getLgnMbr: function(){

		return this.getCookie('cortAuctnLgnMbr') === '' || this.getCookie('cortAuctnLgnMbr') === null ? '정보없음' : this.getCookie('cortAuctnLgnMbr');
	}
	, getCookie : function(name){
		const ckArr = document.cookie.match('(^|;) ?' + name + '=([^;]*)(;|$)');
		return ckArr != null && ckArr.length > 2 ? ckArr[2] : '정보없음';
//		return document.cookie.match('(^|;) ?' + name + '=([^;]*)(;|$)')[2] || '정보없음';
	}
};

