        for (i = this.NITER; i--; phi_l = lat) { //check this
                sinphi = this.e * Math.sin(phi_l);
                lat = 2. * Math.atan(tp * Math.pow((1.+sinphi)/(1.-sinphi), halfe)) - pi2;
