function mulMapSrch(data, mx, my)
{
	deleteAllMarker();
	var maxX=0;
	var maxY=0;
	var minX=1000000;
	var minY=1000000;
	var mkChk = 0;

	if(data.length == 0)
	{
		//alert('占쏙옙호占쏙옙占쏙옙占싶곤옙 占쏙옙占쏙옙占싹댐옙.');
