		moveCenter(312760, 544317, 10);
		return;
	}
	for (var j = 0; j < data.length; j++) {
		if(data[j][0].lvl != '3'){
			mkChk = 1;
			break;
		}
	}
	for(var i = 0 ; i < data.length ; i++)
	{
		if ((data[i][0].ptX != 'null') && (data[i][0].ptX != 0)) {
			if (data[i][0].lvl != '3') {
				drawMulMarker(data[i][0],0);

				maxX = Math.max(maxX, data[i][0].ptX);
				maxY = Math.max(maxY, data[i][0].ptY);
				minX = Math.min(minX, data[i][0].ptX);
				minY = Math.min(minY, data[i][0].ptY);
			}
			else if(data[i][0].lvl == '3'){
				//alert(1);
				if (mkChk == 0) {
					maxX = Math.max(maxX, data[i][0].ptX);
					maxY = Math.max(maxY, data[i][0].ptY);
					minX = Math.min(minX, data[i][0].ptX);
					minY = Math.min(minY, data[i][0].ptY);
				}
			}
		}
	}
	if(mx != null)
	{
		maxX = Math.max(maxX, mx);
		maxY = Math.max(maxY, my);
		minX = Math.min(minX, mx);
		minY = Math.min(minY, my);
	}
	mapObj.setBound(parseInt(minX), parseInt(minY), parseInt(maxX), parseInt(maxY));
	if(getLevel() == 13){
		zoomout();
	}
	Map_SetLevelIcon(getLevel());
}

