function drawRePrevMarker(dataObj, mulIdx){
	for (var i = 0; i < dataObj.length; i++) {
		if(i != mulIdx){
			if (dataObj[i].length != 0) {
				for (var j = 0; j < dataObj[i].length; j++) {
					if (dataObj[i][j].lvl != '3') {
						drawMulMarker(dataObj[i][j], 0);
					}
				}
			}else{
				drawMulMarker(dataObj[i][0], 0);
			}
		}
	}
}
