var Global_MapOpener = "D";
var Global_MaxLevel = 12;  //--YCK 12
var Global_MinLevel = 1;
var Global_MapTileSize = 400;

function FreeMapOption(mapID) {
	//-73833.677575, -36737.229000, 577397.437500, 566451.331300
	//this.tileSize = 256;
	this.tileSize = Global_MapTileSize;
/*	this.minX = -73833.677575;
	this.minY = -36737.229000;
	this.maxX = 577397.437500;
	this.maxY = 566451.331300;

	this.minX = -185703;
	this.minY = -195041;
	this.maxX = 749767;
	this.maxY = 1064629;
*/
	this.OptionMapOpener = MapOpener;

	this.minX = GminX;
	this.minY = GminY;
	this.maxX = GmaxX;
	this.maxY = GmaxY;

	this.dispersionX = GdispersionX;  //분산
	this.dispersionY = GdispersionY;  //분산

	this.minLevel = Global_MinLevel;
	this.maxLevel = Global_MaxLevel;
	if(this.OptionMapOpener == "Paran")	this.maxLevel = 11;
	else if(this.OptionMapOpener == "Freemap") this.maxLevel = 13;
	else this.maxLevel = Global_MaxLevel;

	if(this.OptionMapOpener == "iris")	this.minLevel = 0;
	else if(this.OptionMapOpener == "Freemap") this.minLevel = 1;
	else this.minLevel = Global_MinLevel;

	this.emptyTileUrl = FreeMapImageServer+"/empty.jpg";
	this.preTileUrl = FreeMapImageServer+"/mapbg.png";

	this.OptionMapOpener = Global_MapOpener;

	if (this.OptionMapOpener == "D") {
	  this.baseMapUrl = FreeMapMapServer + '/';
	  this.baseMapUrl_S1 = FreeMapMapServer_S1 + '/';
	  this.baseIndexMapUrl = FreeMapIMapServer + '/';
	}
	else
	{
  	this.baseMapUrl = FreeMapMapServer + '/L';
  	this.baseMapUrl_S1 = FreeMapMapServer_S1 + '/L';
  	this.baseIndexMapUrl = FreeMapIMapServer + '/L';
	}
	this.tmmid2geo = new FreeMapCoorder(0, 2, 0, 0);
	this.geo2tmmid = new FreeMapCoorder(0, 0, 0, 2);
	if (!mapID) this.mapID = "ID_MAP";
	this.mapID = mapID;
	this.diffMinimapLevel = 3;
}

FreeMapOption.prototype.getRowCount = function (mLevel) {
	return Math.floor((this.maxY-this.minY) / (this.distancePerPixel(mLevel)*this.tileSize));
};

FreeMapOption.prototype.getColCount=function (mLevel) {
	return Math.floor((this.maxX-this.minX) / (this.distancePerPixel(mLevel)*this.tileSize));
};

FreeMapOption.prototype.indexPerpoint = function (mLevel, colIdx, rowIdx) {
  var pos = new FreeMapPoint(0, 0);

  pos.x = (colIdx * (this.distancePerPixel(mLevel) * this.tileSize)) + this.minX;
  pos.y = (rowIdx * (this.distancePerPixel(mLevel) * this.tileSize)) + this.minY;

  return pos;
};

FreeMapOption.prototype.getTileUrl=function (colIdx, rowIdx, mLevel) {

	var rowImgCnt = this.getRowCount( mLevel );
	var colImgCnt = this.getColCount( mLevel );
	if ( rowIdx < 0 || colIdx < 0 || rowIdx > rowImgCnt || colIdx > colImgCnt ) {
		return this.emptyTileUrl;
	}
	var strZero = "";
	var MapUrl = "";
	var rowDir = null;
	var colDir = null;
	if(this.OptionMapOpener == "Paran")
	{
	  strZero = "0000";
	  rowDir = Math.floor(rowIdx/100).toString();
  	rowDir = strZero.substr(0,2-rowDir.length) + rowDir;
  	rowIdx = rowIdx.toString();
  	rowIdx = strZero.substr(0,4-rowIdx.length) + rowIdx;
  	colDir = Math.floor(colIdx/100).toString();
  	colDir = strZero.substr(0,2-colDir.length) + colDir;
  	colIdx = colIdx.toString();
  	colIdx = strZero.substr(0,4-colIdx.length) + colIdx;

  	//MapUrl = this.baseMapUrl + mLevel + '/' + colDir + '_' + rowDir + '/P_' + colIdx + '_' + rowIdx + '.png';
  	var PointChk = new FreeMapPoint(0,0);
    PointChk = this.indexPerpoint(mLevel, colIdx, rowIdx);
    //alert(PointChk.x);
    if(PointChk.x > this.dispersionX) MapUrl = this.baseMapUrl_S1 + mLevel + '/' + colDir + '_' + rowDir + '/P_' + colIdx + '_' + rowIdx + '.png';
    else MapUrl = this.baseMapUrl + mLevel + '/' + colDir + '_' + rowDir + '/P_' + colIdx + '_' + rowIdx + '.png';
    //alert(MapUrl);
	}
	else if(this.OptionMapOpener == "Freemap")
	{
	  strZero = "00000";
	  rowDir = Math.floor(rowIdx/100).toString();
  	rowDir = strZero.substr(0,3-rowDir.length) + rowDir;
  	rowIdx = rowIdx.toString();
