FreeMapOption.prototype.distancePerPixel = function (mLevel) {
	var diffMinimapLevel = 0;
	return Math.pow(2, 11 - mLevel + diffMinimapLevel);
};

FreeMapOption.prototype.pixel2tmmidPoint=function (pxPoint, mLevel, tmmidPoint) {
	if (!tmmidPoint) tmmidPoint = new FreeMapPoint(0,0);
	var dstPerPx = this.distancePerPixel(mLevel);
	tmmidPoint.set( Math.round(pxPoint.x * dstPerPx) + this.minX, Math.round(pxPoint.y * dstPerPx) + this.minY );
	return tmmidPoint;
};

FreeMapOption.prototype.tmmidPoint2pixel=function (tmmidPoint, mLevel, pxPoint) {
	if (!pxPoint) pxPoint = new FreeMapPoint(0,0);
	var dstPerPx = this.distancePerPixel(mLevel);
	pxPoint.set( Math.round( ( tmmidPoint.x - this.minX )/dstPerPx ), Math.round( ( tmmidPoint.y - this.minY )/dstPerPx ) );
	return pxPoint;
};

FreeMapOption.prototype.pixel2geoPoint=function (pxPoint, mLevel, geoPoint) {
	if (!geoPoint) geoPoint = new FreeMapPoint(0,0);

	var dstPerPx = this.distancePerPixel(mLevel);
	var tmmidPoint = new FreeMapPoint(0,0);

	tmmidPoint.set( Math.round(pxPoint.x * dstPerPx) + this.minX, Math.round(pxPoint.y * dstPerPx) + this.minY );
	geoPoint = this.tmmid2geo.convert(tmmidPoint.x, tmmidPoint.y);

	return geoPoint;
};

FreeMapOption.prototype.geoPoint2pixel=function (geoPoint, mLevel, pxPoint) {
	if (!pxPoint) pxPoint = new FreeMapPoint(0,0);

	var dstPerPx = this.distancePerPixel(mLevel);
	var tmmidPoint = new FreeMapPoint(0,0);

	tmmidPoint = this.geo2tmmid.convert(geoPoint.x, geoPoint.y);
	pxPoint.set( Math.round( ( tmmidPoint.x - this.minX )/dstPerPx ), Math.round( ( tmmidPoint.y - this.minY )/dstPerPx ) );

	return pxPoint;
};

