FreeMapLayer.prototype.getPosition = function () {
	var left, top;
	var boundOffset = this.parentObj.getOffsetContainer();

	switch (this.align) {
	case "left":
		left = this.pos.x + boundOffset[0];
		break;
	case "center":
		left = Math.round((this.pos.x + (this.parentObj.scrSize.width - boundOffset[0] - boundOffset[2]) - this.lSize.width) / 2) + boundOffset[0];
	case "right":
		left = this.parentObj.scrSize.width - this.lSize.width - this.pos.x - boundOffset[2];
		break;
	}
	switch (this.valign) {
	case "top":
		top = this.pos.y + boundOffset[1];
		break;
	case "center":
		top = Math.round((this.pos.y + (this.parentObj.scrSize.height - boundOffset[1] - boundOffset[3]) - this.lSize.height) / 2) + boundOffset[1];
		break;
	case "bottom":
		top = this.parentObj.scrSize.height - this.lSize.height - this.pos.y - boundOffset[3];
		break;
	}
	return new FreeMapPoint(left, top);
};

FreeMapLayer.prototype.setSize = function (lSize) {
	this.lSize = lSize;
	if (null!=this.layerCon) {
		this.layerCon.style.width = lSize.width + "px";
