FreeMapLayer.prototype.redrawHandler = function () {
	if (null==this.parentObj) {
		return;
	}
	var pos = this.getPosition();
	if (!this.bMinimap) {
		this.layerCon.style.opacity	= this.opacity;
		this.layerCon.style.filter	= 'alpha(opacity = ' + (this.opacity*100) + ')';
	}
	this.layerCon.style.left	= pos.x + "px";
	this.layerCon.style.top		= pos.y + "px";
	this.layerCon.style.width	= this.lSize.width + "px";
	this.layerCon.style.height	= this.lSize.height + "px";
	this.layerCon.style.zIndex	= this.zIndex;
};
