FreeMapMap.prototype.getTileCountAndMargin = function () {
	var tileSize = this.options.tileSize;
	var scrWidth = this.scrSize.width;
	var scrHeight = this.scrSize.height;
	// 이미지 타일의 수량 구하기.
	this.imgTileSize = new FreeMapSize(Math.ceil(scrWidth/tileSize) + 2, Math.ceil(scrHeight/tileSize) + 2);
	// 전체 이미지의 중심과 화면의 중심이 같을 경우 화면에 표시되지 않은 영역의 Left, top 에서 Right, Bottom 크기
	this.marginSize = new FreeMapSize(Math.floor((this.imgTileSize.width*tileSize-scrWidth)/2), Math.floor((this.imgTileSize.height*tileSize-scrHeight)/2));
};

