FreeMapMap.prototype.zoomOut = function () {
  if(this.mapMode == "circle" && this.mLevel == 11)
  {
    return;
  }
	if (this.mLevel > this.mapMinLevel) {
		this.setZoomLevel(this.mLevel - 1);
	}
	else{
	  alert("더 이상 축소할 수 없습니다.");
	}
