FreeMapMap.prototype.setZoomLevel = function (lv) {
	if(this.mapMinLevel > lv){
		return alert("더 이상 축소할 수 없습니다.");
	}

	if(this.mapMaxLevel < lv){
		return alert("더 이상 확대할 수 없습니다.");
	}
  if(this.zoomCheck == true)  //줌 이벤트 연속 방지 - 2007.12.12 카이네스
  {
  	if (this.mLevel != lv) {
  		this.zoomCheck = false;
  		this.scrGeoBound = null;	// 화면의 표시 영역에 대한 Boundary
  		var cPoint = this.getCenter();
  		var oldmLevel = this.mLevel;
  		this.prevLevel = this.mLevel;
  		this.mLevel = lv;
  		this.setCenter(cPoint);
  		cPoint = null;
  		FreeMapEvent.trigger(this, "zoom", this.mLevel, oldmLevel);
  		this.reLocateTile();
  		//parent.Map_SetLevelIcon(this.mLevel); //YCK
  		/*if (typeof parent.Map_SetLevelIcon == 'function') {
        parent.Map_SetLevelIcon(this.mLevel);
      }*/

  		this.zoomCheck = true;
  	}
  }
};

