FreeMapMap.prototype.getMapLeftTop = function () {
  //var centerPt = this.getCenter();
  var centerPt = this.getCenterPointPx();
  var mapLeft = Math.round(centerPt.x - this.divCon.clientWidth / 2);
  var mapTop = Math.round(centerPt.y + this.divCon.clientHeight / 2);
  return new FreeMapPoint(mapLeft, mapTop);
};

FreeMapMap.prototype.coordtoScr = function(coord) {
  var marginLeft = parseInt(this.div.style.left);
  var marginTop = parseInt(this.div.style.top);
  var leftTopPt = this.getMapLeftTop();

  coord = this.options.tmmidPoint2pixel(coord, this.mLevel);

  coord.x = coord.x - leftTopPt.x - marginLeft; // 오차계산
  coord.y = leftTopPt.y - coord.y - marginTop;
  return coord;
};

FreeMapMap.prototype.getClickPoint = function (evtObj) {
  var clickPos = FreeMapEvent.getClickPos(evtObj, this.divCon);
  return clickPos;
};

FreeMapMap.prototype.getCurrentMousePoint = function (evtObj) {
	var evtObjPos = FreeMapEvent.getClickPos(evtObj, this.divCon);
	evtObjPos.add(- Math.round((this.offsetBound[0] - this.offsetBound[2])/2), - Math.round((this.offsetBound[1] - this.offsetBound[3])/2));
	return new FreeMapPoint(evtObjPos.x - Math.round(this.scrSize.width / 2), Math.round(this.scrSize.height / 2) - evtObjPos.y);
};

FreeMapMap.prototype.getCurrentObjectPoint = function (evtObj) {
		//--YCK--return this.options.pixel2tmmidPoint( this.getCurrentPointPx(evtObj), this.mLevel );
	var curObjPoint = this.options.pixel2tmmidPoint(this.getCurrentPointPx(evtObj), this.mLevel);
    // jsy 201605 지도와 레이어 좌표계 틀릴 경우 처리
    if (this.options.OptionMapOpener == "D") {
        if (typeof outChangePointEx == 'function') {
            curObjPoint = outChangePointEx("P", curObjPoint, this.options.OptionMapOpener);
            curObjPoint.x = parseInt(curObjPoint.x);
            curObjPoint.y = parseInt(curObjPoint.y);
        }
    }
    return curObjPoint;
};

