FreeMapMap.prototype.mouseDownHandler = function (evtObj) {
	if (!evtObj) evtObj = window.event;
	if(evtObj.button == 2)
	  return;
	window.clearTimeout(this.timerID);
	this.setCenterModify();
	switch (this.getCurrentEvent()) {
	case 0:	// 드래그 시작
		if (this.isDraggable) {
			this.imgConDiv.startDrag(evtObj);
		}
		break;
	case 1:	// 확대
		this.locateTile(this.getCurrentPointPx(evtObj));
		this.zoomIn();
		break;
	case 2:	// 축소
		this.locateTile(this.getCurrentPointPx(evtObj));
		this.zoomOut();
		break;
	case 3:	// 선택
		this.selectObj.startSelect(evtObj);
		break;
	}
	this.imgConDiv.movSize.copy(this.downpos);
	FreeMapEvent.trigger(this,"mousedown",this.getCurrentObjectPoint(evtObj));
};

FreeMapMap.prototype.clickHandler = function (evtObj) {
	if (!evtObj) { evtObj = window.event; }
	if (Math.pow((this.imgConDiv.movSize.width - this.downpos.width), 2) + Math.pow((this.imgConDiv.movSize.height - this.downpos.height), 2) < 100) {
		FreeMapEvent.trigger(this,"click",this.getCurrentObjectPoint(evtObj));
	}
}

