	FreeMapEvent.trigger(this,"contextmenu");
};

FreeMapMap.prototype.alignImage = function () {
	var arrImgOrderObj = this.sortImageArray(this.arrImgTile);
	for (var i=0; i<arrImgOrderObj.length; i++) {
		this.setImageTagURL(this.arrImgTile[arrImgOrderObj[i].xPos][arrImgOrderObj[i].yPos], arrImgOrderObj[i].xPos, arrImgOrderObj[i].yPos);
	}
};

FreeMapMap.prototype.setImageTagURL = function (imgObj, colNum, rowNum) {
	var mapLevel = this.getZoomLevel();
	var tileSize = this.options.tileSize;
	// 이미지 타일의 URL 설정.
	var imgTileURL = this.options.getTileUrl(this.imgLTCnt.x + colNum + this.imgTileOffset.x, this.imgLTCnt.y - rowNum + this.imgTileOffset.y, this.mLevel);

  /* 의미 없음
	if (imgTileURL != imgObj.src) {
		imgObj.src = this.options.preTileUrl;
	}
	*/
	imgObj.src		 = imgTileURL;
	var emptyTileUrl = this.options.emptyTileUrl;
	imgObj.onerror	 = function () { this.src = emptyTileUrl };

	// 이미지 타일의 위치 설정.
	imgObj.style.left = (colNum + this.imgTileOffset.x) * tileSize - this.marginSize.width + "px";
	imgObj.style.top  = (rowNum - this.imgTileOffset.y) * tileSize - this.marginSize.height + "px";
};

FreeMapMap.prototype.sortImageArray = function (arrImgTile) {
	var arrVal = new Array();
	for (var i = 0; i < arrImgTile.length; i++) {
		for (var j = 0; j < arrImgTile[i].length; j++) {
			var imgObj = arrImgTile[i][j];
			imgObj.xPos = i;
			imgObj.yPos = j;
			var col = Math.min(i, arrImgTile.length-i-1);
			var row = Math.min(j, arrImgTile[i].length-j-1);
			if (row == 0 || col == 0) {
				imgObj.order = 0;
			}
			else {
				imgObj.order = col + row;
			}
			arrVal.push(imgObj);
		}
	}
	arrVal.sort( function (firstImg, secondImg) { return secondImg.order - firstImg.order } );
	return arrVal;
};

FreeMapMap.prototype.setOffsetContainer = function (left, top, right, bottom) {
	if (left instanceof Array) {
		this.offsetBound = left;
	}else{
		this.offsetBound = new Array(left, top, right, bottom);
	}
	this.setCenter(this.getCenter());
	FreeMapEvent.trigger(this,"redraw");
};

FreeMapMap.prototype.getOffsetContainer = function () {
	return this.offsetBound;
};

FreeMapMap.prototype.getCenterPointPx = function (pt) {
	if (!(pt instanceof FreeMapPoint)) {
		pt = new FreeMapPoint(0,0);
	}
	pt.set(this.imgLTPos.x + Math.round((this.offsetBound[0] - this.offsetBound[2])/2) + Math.round(this.scrSize.width/2)  + this.marginSize.width - this.imgConDiv.movSize.width, this.imgLTPos.y - Math.round((this.offsetBound[1] - this.offsetBound[3])/2) - Math.round(this.scrSize.height/2) -  this.marginSize.height + this.imgConDiv.movSize.height);
	return pt;
};

FreeMapMap.prototype.getCurrentPointPx = function (evtObj) {
	var pt		 = this.getCurrentMousePoint(evtObj);
	var rtCPoint = this.getCenterPointPx();
	rtCPoint.add(pt.x, pt.y);
	return rtCPoint;
};

FreeMapMap.prototype.resizeHandler = function () {
	if (this.scrSize.width != this.divCon.offsetWidth || this.scrSize.height != this.divCon.offsetHeight) {
		var cpoint = this.getCenterPointPx();
		cpoint.add((this.divCon.offsetWidth - this.scrSize.width) * 0.5 * this.resizeType.x, (this.divCon.offsetHeight - this.scrSize.height) * 0.5 * this.resizeType.y);
		this.scrSize.width	= this.divCon.offsetWidth;
		this.scrSize.height	= this.divCon.offsetHeight;
		this.getTileCountAndMargin();
		this.setTileImageArray(this.arrImgTile);
		this.locateTile(cpoint);
		cpoint = null;
		FreeMapEvent.trigger(this,"resize");
	}
};

FreeMapMap.prototype.onWheelMove = function (evtObj) {
	if (!evtObj) evtObj = window.event;
	//alert(this.zoomCheck);

	if(nowBrowser != "firefox")
	{
  	if(this.zoomCheck == true)  //줌 이벤트 연속 방지 - 2007.12.12 카이네스
  	{
    	//2007.12.12 카이네수 추가 - 연속 휠 막음
    	var startTime = new Date();
    	if((startTime.getTime() - this.wheelTime.getTime()) < 800) {
    	  //alert(startTime.getTime() - this.wheelTime.getTime());
    		return;
    	}
    	//this.wheelTime = new Date();
    	//2007.12.12 카이네수 추가 - 연속 휠 막음
    	var delta = evtObj.wheelDelta;
    	if (delta > 0) {
    		this.zoomIn();
    	}
    	else if (delta < 0) {
    		this.zoomOut();
    	}
  	}
	}
	else
	{
    var delta;
    if (evtObj.wheelDelta) { /* IE/Opera. */
      delta = evtObj.wheelDelta/120;
      /** In Opera 9, delta differs in sign as compared to IE.
      */
      if (window.opera)
        delta = -delta;
    } else if (evtObj.detail) { /** Mozilla case. */
      /** In Mozilla, sign of delta is different than in IE.
      * Also, delta is multiple of 3.
      */
      delta = -evtObj.detail/3;
    }
    if(delta < 0){
      mapObj.zoomOut();
    }
    else if(delta > 0){
      mapObj.zoomIn();
    }
  }
  FreeMapEvent.disableNotifyEvent(evtObj);
	evtObj.cancelBubble = true;
};

FreeMapMap.prototype.enableWheelZoom = function () {
	this.divCon.onmousewheel = falsefunc;
	if(nowBrowser != "firefox")
  	FreeMapEvent.attachEvent(this.divCon, "mousewheel", this.fpWheel);
  else
    FreeMapEvent.attachEvent(this.divCon, "DOMMouseScroll", this.onWheelMove);
};

FreeMapMap.prototype.disableWheelZoom = function () {
	this.divCon.onmousewheel='';

	if(bIsMSIE)
  	FreeMapEvent.detachEvent(this.divCon, "mousewheel", this.fpWheel);
  else
    FreeMapEvent.detachEvent(this.divCon, "DOMMouseScroll", this.onWheelMove);
};

FreeMapMap.prototype.getPosition = function (pxPoint, rtPoint) {
	var tileSize = this.options.tileSize;
	if (!rtPoint) rtPoint = new FreeMapPoint(0,0);
	rtPoint.set(pxPoint.x - this.imgLTCnt.x * tileSize - this.marginSize.width, (this.imgLTCnt.y + 1) * tileSize - this.marginSize.height - pxPoint.y);
	return rtPoint;
};

