FreeMapMap.prototype.addLayer = function (obj, key) {
	this.arrLayerObj.push(Array(obj, key));
	obj.initialize(this);
	obj.redrawHandler(this);
};

FreeMapMap.prototype.removeLayer = function (obj) {
	if (!this.arrLayerObj || this.arrLayerObj.length < 1) return;
	for (var i = 0; i < this.arrLayerObj.length; i++) {
		if (obj == this.arrLayerObj[i][0]) {
			obj.unloadHandler();
			this.arrLayerObj.splice(i, 1);
			break;
		}
	}
};

FreeMapMap.prototype.removeKeyLayers = function (key) {
	var arrObj = new Array();
	var cnt = 0;
	if (this.arrLayerObj && this.arrLayerObj.length > 0) {
		for (var i=0; i<this.arrLayerObj.length; i++) {
			if (key && key == this.arrLayerObj[i][1]) {
				this.arrLayerObj[i][0].unloadHandler();
				this.arrLayerObj[i] = null;
			}
			else
			{
				arrObj[cnt] = this.arrLayerObj[i];
				cnt++;
			}
		}
		this.arrLayerObj = arrObj;
	}
};

