// Date: 2007-11-15
// writer : 서형진(kainess)
// Edit:
window.falsefunc=function (){return false;}
function FreeMapGraphics(mapObj){
  this.mapObj = mapObj; // 지도오브젝트
  this.drawLayer = this.createDIV(19);
  this.mapObj.div.appendChild(this.drawLayer);
  this.landDiv = this.createDIV(1);
  this.mapObj.landLayer.appendChild(this.landDiv);

  this.drawMode = "normal"; // 그리기모드(normal, line, area)
  this.drawIdx = 50;  // 그려진 Div 인덱스값(지우는데 사용될 값)
	this.isDraw = false;  // 그리기모드 확인
	this.drawAble = true; // 그리기가능(드레그시 false)
	this.clickCnt = 0;  // 클릭횟수
	this.totalDist = 0; // 총 이동거리
	this.lv;  // 레벨
	this.cursor;

	this.realPt = new Array();  // 좌표값저장
  this.drawDiv = new Array(); // 실제 그려질 Div
  this.textBoxDiv = new Array();  // 텍스트 박스 Div
  this.tmpDrawDiv = ""; // 임시로 그려질 Div
  this.tmpTextboxDiv = new Array(); // 이동거리계산출력
  this.tmpTextDiv = ""; // 이동하는 텍스트박스
  this.pointDiv="";  // 클릭한 점그림 Div
	this.container = new Array(); // 데이터 저장

  this.browse;  // 브라우져종류
  this.scrWidth;
  this.scrHeight;
  this.scrLeft;
  this.scrTop;
  this.marginLeft;
  this.marginTop;
  this.layerMargin = 0; // 레이어 여유(그려진것 짤리는것 방지)

  this.initialize();

  this.pDraw = new Array();
  this.svg = new Array(); // svg객체
  this.landData = "";
  this.radi = 0;
  this.circleCt;
  this.circleIdx = 0;

  this.tmpPoint;
  this.endPoint;
  this.moveLeft = 0;
  this.moveTop = 0;
  this.movingLeft = 0;
  this.movingTop = 0;

  this.drawingText = true;  // 텍스트박스 그리기 플레그
  this.fflag = false;  //그리기 취소
  this.boolLandDraw = true;
  this.txetboxClick = false;  //그리기 선택후 거리/면적
  this.nowdrawable = true;
  this.isDown = false;
};

// Name: initialize
// Desc: FreeMapGraphics 초기화
// Args:
// Date: 2007-11-15
// Edit:
FreeMapGraphics.prototype.initialize = function(){
  this.getStart();  // 좌표오차계산
  this.getInitMoving();
  this.options = new FreeMapOption(); // 옵션객체 생성

  //document.body.oncontextmenu = falsefunc;

  FreeMapEvent.link(this.mapObj.divCon, "click", this, this.clickHandler);  // 마우스 클릭시
  //FreeMapEvent.link(this.mapObj.divCon, "click", this, this.drawLand);
  FreeMapEvent.link(this.mapObj.divCon, "mousedown", this, this.mouseDownHandler);  // 마우스 다운시
  FreeMapEvent.link(this.mapObj.divCon, "mouseup", this, this.mouseUpHandler);  // 마우스 업시
	FreeMapEvent.link(this.mapObj.divCon, "mousemove", this, this.mouseMoveHandler);  // 마우스 이동시
	FreeMapEvent.link(window, "resize", this, this.resizeHandler);  // 리사이즈시

	FreeMapEvent.bind(this.mapObj.imgConDiv, "drag", this, this.dragHandler); // 드레그시
	FreeMapEvent.bind(this.mapObj.imgConDiv, "enddrag", this, this.endDragHandler); // 드레그시
	FreeMapEvent.bind(this.mapObj, "redrawGraphics", this, this.redrawGraphicsHandler); // 다시그리기

  // 브라우져 확인 그리기객체 생성
	if(bIsMSIE == true){
	  this.drawIt = new FreeMapGraphicsIE(this.mapObj); // 익스플로러용 객체 생성
	  this.browse = "MSIE";
	}
	else{
  	this.drawIt = new FreeMapGraphicsFF(this.mapObj); // 파이어폭스용 객체 생성
  	this.browse = "FF";
    this.layerMargin = 1000;
    this.drawLayer.style.left = -this.layerMargin + "px";
    this.drawLayer.style.top = -this.layerMargin + "px";
    this.landDiv.style.left = -this.layerMargin + "px";
    this.landDiv.style.top = -this.layerMargin + "px";
  }

  this.distcursor = "url('"+FreeMapImageServer+"/distCur.cur'),auto";
  this.areacursor = "url('"+FreeMapImageServer+"/areaCur.cur'),auto";
  this.mypincursor = "url('"+FreeMapImageServer+"/mypin.cur'),auto";
  this.circlecursor = "url('"+FreeMapImageServer+"/circleCur.cur'),auto";
  this.landcursor = "url('"+FreeMapImageServer+"/landCur.cur'),auto";
  this.handcursor = "url('"+FreeMapImageServer+"/handCur.cur'),auto";
};

// Name: mouseUpHandler
// Desc: 파이어폭스 svg레이어 이동을 위해
// Args:
// Date: 2007-11-17
// Edit:
FreeMapGraphics.prototype.mouseUpHandler = function(evtObj){
  if (!evtObj)  evtObj = event;

  this.isDown = false;
  if(this.browse == "FF")
  {
    this.getMoving();
    this.endPoint = this.mapObj.getCurrentMousePoint(evtObj);
    this.moveLeft = false;
    this.moveTop = false;

    if(this.txetboxClick == true)
      return;

    if (this.tmpPoint.x-this.endPoint.x < -2) {			// 오른쪽
  		this.moveLeft = true;
  	}
  	else if (this.tmpPoint.x-this.endPoint.x > 2) {		// 왼쪽
  		this.moveLeft = true;
  	}
  	if (this.tmpPoint.y-this.endPoint.y < -2) {			// 아래쪽
  		this.moveTop = true;
  	}
  	else if (this.tmpPoint.y-this.endPoint.y > 2) {		// 위쪽
  		this.moveTop = true;
  	}
  	if(this.moveLeft == true || this.moveTop == true)
  	{
      this.drawLayer.style.left = this.movingLeft-this.layerMargin + "px";
      this.drawLayer.style.top = this.movingTop-this.layerMargin + "px";
      this.redrawGraphics();
      //this.redrawPolyLand();
  	}
	}
};

// Name: clickHandler
// Desc: 클릭 이벤트시 호출
// Args:
// Date: 2007-11-15
// Edit:
FreeMapGraphics.prototype.clickHandler = function(evtObj){
  if (!evtObj) evtObj = event;

  this.isDown = false;
  if(this.txetboxClick) return ;
  if(this.nowdrawable == false) return;

  if(this.isDrawable()) // 그리기모드이면
  {
    if(this.isDraw == true) // 드레그 발생이 안했을때
    {
      if(this.clickCnt == 0)  // 최초클릭시
      {
        this.container[this.drawIdx-50] = new FreeMapDrawSet(); //데이터셋 생성
        this.container[this.drawIdx-50].pt[this.clickCnt] = this.realPt[this.clickCnt]; // 좌표저장
        this.drawDiv[this.drawIdx] = this.createDIV(this.drawIdx);  // 그려질 div객체 생성
        this.drawLayer.appendChild(this.drawDiv[this.drawIdx]);  // 어펜드

        if(this.browse == "FF") // 파이어폭스이면
        {
          this.svg[this.drawIdx] = this.drawIt.init(this.drawDiv[this.drawIdx]);  // 파이어폭스 객체생성
        }

        this.tmpDrawDiv = this.createDIV(11); // 임시로 그려지는 div생성
        this.drawDiv[this.drawIdx].appendChild(this.tmpDrawDiv);
        this.tmpTextDiv = this.createDIV(10); // 이동하는 텍스트박스 div생성
        this.drawDiv[this.drawIdx].appendChild(this.tmpTextDiv);
        this.container[this.drawIdx-50].drawMode = this.drawMode;
        if((this.drawMode == "line" || this.drawMode == "polyline") && this.drawingText == true) // 선그리기일때
        {
          this.tmpTextboxDiv[this.clickCnt] = this.createDIV(this.drawIdx); // 구간거리 표시 텍스트박스 div 생성
        	this.drawDiv[this.drawIdx].appendChild(this.tmpTextboxDiv[this.clickCnt]);
          this.tmpTextboxDiv[this.clickCnt].innerHTML = this.tmpDistTextbox("시작");  // 시작 표시
          var pix = this.tmtoScrPixel(this.realPt[this.clickCnt].x, this.realPt[this.clickCnt].y, this.getLevel()); // 중부좌표를 화면좌표로
          this.tmpTextboxDiv[this.clickCnt].style.left = pix.x+"px";  // 텍스트박스 위치조정
          this.tmpTextboxDiv[this.clickCnt].style.top = pix.y+"px";
        }
        if(this.drawMode == "circle")
        {
          //this.tmpDrawDiv = this.drawCircle(this.drawDiv[this.drawIdx], this.realPt[this.clickCnt].x, this.realPt[this.clickCnt].y, this.realPt[this.clickCnt].x, this.realPt[this.clickCnt].y);  // 원그리기
        }
      }
      else  // 클릭 두번 이상
      {
        this.container[this.drawIdx-50].pt[this.clickCnt] = this.realPt[this.clickCnt]; // 좌표 저장
        if(this.drawMode != "circle")
        {
          if(this.drawMode != "polyline")
          {
            this.drawIt.setStrokeOpacity("0.8");  // 투명도 설정
            this.pDraw[this.drawIdx] = this.drawLine(this.drawDiv[this.drawIdx], this.realPt[this.clickCnt].x, this.realPt[this.clickCnt].y, this.realPt[this.clickCnt-1].x, this.realPt[this.clickCnt-1].y); // 선그리기
            this.drawIt.setBasicStyle();  // 기본설정으로
          }
          else
          {
            this.drawIt.setStrokeOpacity("0.8");  // 투명도 설정
            this.pDraw[this.drawIdx] = this.drawPolyLine(this.drawDiv[this.drawIdx], this.realPt); // 선그리기
            this.drawIt.setBasicStyle();  // 기본설정으로
          }
        }

        if((this.drawMode == "line" || this.drawMode == "polyline") && this.drawingText == true) // 선그리기이면
        {
          var dist = this.calcDist(this.realPt[this.clickCnt].x, this.realPt[this.clickCnt].y, this.realPt[this.clickCnt-1].x, this.realPt[this.clickCnt-1].y); // 거리계산
          this.container[this.drawIdx-50].data[this.clickCnt] = dist; // 거리 계산
          this.totalDist += dist; // 총 이동거리
          this.tmpTextboxDiv[this.clickCnt] = this.createDIV(this.drawIdx); // 구간거리 표시 텍스트박스 div 생성
      	  this.drawDiv[this.drawIdx].appendChild(this.tmpTextboxDiv[this.clickCnt]);
      	  this.tmpTextboxDiv[this.clickCnt].innerHTML = this.tmpDistTextbox(dist);  // 거리 표시
          var pix = this.tmtoScrPixel(this.realPt[this.clickCnt].x, this.realPt[this.clickCnt].y, this.getLevel()); // 중부좌표를 화면좌표로
          this.tmpTextboxDiv[this.clickCnt].style.left = pix.x+"px";  // 텍스트박스 위치조정
          this.tmpTextboxDiv[this.clickCnt].style.top = pix.y+"px";
        }
        else if(this.drawMode == "circle")  // 원그리기 두번클릭으로 끝남
        {
          this.circleCt = new FreeMapPoint(this.realPt[this.clickCnt-1].x, this.realPt[this.clickCnt-1].y);
          this.circleIdx = this.drawIdx;
          this.tmpDrawDiv.parentNode.removeChild(this.tmpDrawDiv);

          this.pDraw[this.drawIdx] = this.drawCircle(this.drawDiv[this.drawIdx], this.realPt[this.clickCnt-1].x, this.realPt[this.clickCnt-1].y, this.realPt[this.clickCnt].x, this.realPt[this.clickCnt].y); // 원그리기
          this.tmpTextDiv.innerHTML = "";
          this.container[this.drawIdx-50].cnt = this.clickCnt+1
          this.clickCnt = 0;  // 클릭횟수 0
          this.total = 0; // 총 거리 0
          this.setDrawMode("normal"); // 모드 초기화
          this.drawIdx = this.drawIdx+1;
          delete this.realPt;
          this.realPt = new Array();
          FreeMapEvent.trigger(this, "endcircle");
          return ;
        }
      }
      if(this.drawMode != "circle")
        this.drawPoint(this.drawDiv[this.drawIdx], this.realPt[this.clickCnt].x, this.realPt[this.clickCnt].y); // 클릭한곳 표시
      this.clickCnt = this.clickCnt+1;  // 클릭횟수 증가
      this.container[this.drawIdx-50].cnt = this.clickCnt;
    }
  }
};

// Name: mouseDownHandler
// Desc: 마우스다운 이벤트시 호출(오른쪽 버튼으로 그리기 종료 이벤트 처리)
// Args:
// Date: 2007-11-15
// Edit:
FreeMapGraphics.prototype.mouseDownHandler = function(evtObj){
  if (!evtObj)  evtObj = event;

  this.isDown = true;
  this.boolLandDraw = true;
  if(this.nowdrawable == false) return;

  this.tmpPoint = this.mapObj.getCurrentMousePoint(evtObj); // 마우스 위치 저장(이동량 계산)
  if(this.isDrawable()) // 그리기모드일때
  {
    this.isDraw = true; // 그려지기 가능
    this.realPt[this.clickCnt] = this.mapObj.getCurrentObjectPoint(evtObj); // 좌표저장

    if(evtObj.button == 2 && this.clickCnt != 0)  // 오른버튼 클릭시(종료시)
    {
      if(this.chkEnd() == false)  // 그려질수 있는지 검사(line:점두개이상, area:점세개이상)
      {
        if((this.drawMode == "line" || this.drawMode == "polyline") && this.drawingText == true) // 선그리기이면
        {
          this.drawDiv[this.drawIdx].removeChild(this.tmpTextboxDiv[0]);  // 시작표시 제거
        }
        this.tmpTextDiv.parentNode.removeChild(this.tmpTextDiv);  // 이동텍스트박스 제거
        this.tmpDrawDiv.parentNode.removeChild(this.tmpDrawDiv);  // 임시그리기 제거

        this.container.pop();
        this.drawDiv[this.drawIdx].parentNode.removeChild(this.drawDiv[this.drawIdx]);  // 그려진 객체 제거
        this.isDraw = false;  // 그려지기 불가능
        this.clickCnt = 0;  // 클릭횟수 0
        this.fflag = true;
        this.endDragHandler();
        return; // 종료
      }
      // 정상종료가능시 (line:점두개이상, area:점세개이상)
      this.tmpDrawDiv.parentNode.removeChild(this.tmpDrawDiv);  // 임시그리기 제거

      if(this.drawingText == true)
      {
        this.textBoxDiv[this.drawIdx] = this.createDIV(this.drawIdx+50);  // 총 거리/면적 텍스트박스 div생성
        this.drawLayer.appendChild(this.textBoxDiv[this.drawIdx]);
      }

      if(this.drawMode == "line" && this.drawingText == true) // 선그리기이면
      {
        this.textBoxDiv[this.drawIdx].innerHTML = this.distTextbox(this.totalDist, this.drawIdx); // 총거리 텍스트박스
        var pix = this.tmtoScrPixel(this.realPt[this.clickCnt-1].x, this.realPt[this.clickCnt-1].y, this.getLevel());
        this.textBoxDiv[this.drawIdx].style.left = pix.x+"px";  // 텍스트박스 위치조정
        this.textBoxDiv[this.drawIdx].style.top = pix.y+"px";

        this.container[this.drawIdx-50].total = this.totalDist; // 총 거리 저장
      }
      else if(this.drawMode == "polyline" && this.drawingText == true) // 선그리기이면
      {
        this.textBoxDiv[this.drawIdx].innerHTML = this.distTextbox(this.totalDist, this.drawIdx); // 총거리 텍스트박스
        var pix = this.tmtoScrPixel(this.realPt[this.clickCnt-1].x, this.realPt[this.clickCnt-1].y, this.getLevel());
        this.textBoxDiv[this.drawIdx].style.left = pix.x+"px";  // 텍스트박스 위치조정
        this.textBoxDiv[this.drawIdx].style.top = pix.y+"px";

        this.container[this.drawIdx-50].total = this.totalDist; // 총 거리 저장
      }
      else if(this.drawMode == "area")  // 면적 그리기이면
      {
        var area = this.calcPolygon(this.realPt); // 넓이계산
        this.clickCnt = this.clickCnt-1;  // 클릭횟수감소
        this.drawIt.setStrokeOpacity("0.8");  // 투명도설정
        this.pDraw[this.drawIdx] = this.drawPolygon(this.drawDiv[this.drawIdx], this.realPt); // 다각형 그리기
        this.drawIt.setBasicStyle();  // 기본설정으로
        if(this.drawingText == true)
        {
          this.textBoxDiv[this.drawIdx].innerHTML = this.areaTextbox(area, this.drawIdx); // 넓이 텍스트박스 div생성
          var pix = this.tmtoScrPixel(this.realPt[this.clickCnt].x, this.realPt[this.clickCnt].y, this.getLevel());
          this.textBoxDiv[this.drawIdx].style.left = pix.x+"px";  // 텍스트박스 위치조정
          this.textBoxDiv[this.drawIdx].style.top = pix.y+"px";

          this.container[this.drawIdx-50].total = area; // 넓이 저장
        }
      }
      else
      {

      }
      this.container[this.drawIdx-50].cnt = this.clickCnt;  // 클릭횟수 저장
      this.container[this.drawIdx-50].drawMode = this.drawMode; // 모드 저장

      this.drawIdx = this.drawIdx+1;  // 그리기객체수 증가
      this.clickCnt = 0;  // 클릭횟수 0
      this.total = 0; // 총 거리 0
      this.totalDist = 0;
      this.setDrawMode("normal"); // 모드 초기화
      delete this.realPt;
      this.realPt = new Array();
      this.redrawGraphics();  // 다시그리기(움직이는 텍스트박스 안지워져서 강제로 다시그렸음)
    }
  }
};

// Name: mouseMoveHandler
// Desc: 마우스이동 이벤트시 호출
// Args:
// Date: 2007-11-15
// Edit:
FreeMapGraphics.prototype.mouseMoveHandler = function(evtObj){
