        this.tmpDrawDiv = this.drawPolyLine(this.drawDiv[this.drawIdx], this.realPt);  // 다각형 그리기
    	  var dist = this.calcDist(this.realPt[this.clickCnt].x, this.realPt[this.clickCnt].y, this.realPt[this.clickCnt-1].x, this.realPt[this.clickCnt-1].y); // 거리계산
    	  /*
    	  if(this.clickCnt < 2) // 클릭횟수 2회미만(다각형이 안될때)
    	  {
    	    this.tmpDrawDiv = this.drawLine(this.drawDiv[this.drawIdx], this.realPt[this.clickCnt].x, this.realPt[this.clickCnt].y, this.realPt[this.clickCnt-1].x, this.realPt[this.clickCnt-1].y);  // 선그리기
    	  }
    	  else
    	  {
    	    this.tmpDrawDiv = this.drawPolygon(this.drawDiv[this.drawIdx], this.realPt);  // 다각형 그리기
    	  }
    	  */
    	  if(this.drawingText == true)
          this.tmpTextDiv.innerHTML = this.moveDistTextbox(dist+this.totalDist); // 움직이는 텍스트박스에 거리표시
        else
          this.tmpTextDiv.innerHTML = this.moveTextbox();
        var pix = this.tmtoScrPixel(this.realPt[this.clickCnt].x, this.realPt[this.clickCnt].y, this.getLevel());

        this.tmpTextDiv.style.left = pix.x+18+"px";  // 텍스트박스 위치조정
        this.tmpTextDiv.style.top = pix.y+18+"px";
      }
      else if(this.drawMode == "area")  // 면적그리기일때
      {
        this.tmpDrawDiv.parentNode.removeChild(this.tmpDrawDiv);  // 임시그리기 제거
        if(this.clickCnt < 2) // 클릭횟수 2회미만(다각형이 안될때)
    	  {
    	    this.tmpDrawDiv = this.drawLine(this.drawDiv[this.drawIdx], this.realPt[this.clickCnt].x, this.realPt[this.clickCnt].y, this.realPt[this.clickCnt-1].x, this.realPt[this.clickCnt-1].y);  // 선그리기
    	  }
    	  else
    	  {
    	    this.tmpDrawDiv = this.drawPolygon(this.drawDiv[this.drawIdx], this.realPt);  // 다각형 그리기
    	  }
    	  this.tmpTextDiv.innerHTML = this.moveTextbox(); // 움직이는 텍스트박스에 메세지
        var pix = this.tmtoScrPixel(this.realPt[this.clickCnt].x, this.realPt[this.clickCnt].y, this.getLevel());
        this.tmpTextDiv.style.left = pix.x+18+"px";  // 텍스트박스 위치조정
        this.tmpTextDiv.style.top = pix.y+18+"px";
      }
      else if(this.drawMode == "circle")
      {
        //this.tmpDrawDiv = this.drawCircle(this.drawDiv[this.drawIdx], this.realPt[this.clickCnt-1].x, this.realPt[this.clickCnt-1].y, this.realPt[this.clickCnt].x, this.realPt[this.clickCnt].y);  // 원그리기
        this.radi = this.calcRadi(this.realPt[this.clickCnt].x, this.realPt[this.clickCnt].y, this.realPt[this.clickCnt-1].x, this.realPt[this.clickCnt-1].y);

        if(this.radi < Math.pow(2, 13-this.getLevel())*100){
          this.tmpDrawDiv.parentNode.removeChild(this.tmpDrawDiv);  // 임시그리기 제거
          this.tmpDrawDiv = this.drawCircle(this.drawDiv[this.drawIdx], this.realPt[this.clickCnt-1].x, this.realPt[this.clickCnt-1].y, this.realPt[this.clickCnt].x, this.realPt[this.clickCnt].y);  // 원그리기
          this.tmpTextDiv.innerHTML = this.moveRadiusTextbox(this.radi);
          var pix = this.tmtoScrPixel(this.realPt[this.clickCnt].x, this.realPt[this.clickCnt].y, this.getLevel());
          this.tmpTextDiv.style.left = pix.x+18+"px";  // 텍스트박스 위치조정
          this.tmpTextDiv.style.top = pix.y+18+"px";
        }
        else
        {
          this.radi = Math.pow(2, 13-this.getLevel())*100;
          this.tmpDrawDiv.parentNode.removeChild(this.tmpDrawDiv);  // 임시그리기 제거
          this.tmpDrawDiv = this.drawCircle(this.drawDiv[this.drawIdx], this.realPt[this.clickCnt-1].x, this.realPt[this.clickCnt-1].y, this.realPt[this.clickCnt].x, this.realPt[this.clickCnt].y);  // 원그리기
          this.tmpTextDiv.innerHTML = this.moveRadiusTextbox(this.radi);
          var pix = this.tmtoScrPixel(this.realPt[this.clickCnt].x, this.realPt[this.clickCnt].y, this.getLevel());
          this.tmpTextDiv.style.left = pix.x+18+"px";  // 텍스트박스 위치조정
          this.tmpTextDiv.style.top = pix.y+18+"px";
        }
      }
    }
  }
};

