// Name: getStart
// Desc: 초기 좌표오차 얻기
// Args:
// Date: 2007-11-15
// Edit:
FreeMapGraphics.prototype.getStart = function(){
  this.lv = this.mapObj.mLevel; // 레벨
  this.marginLeft = parseInt(this.mapObj.div.style.left); // 지도 왼쪽좌표
  this.marginTop = parseInt(this.mapObj.div.style.top); // 지도 위 좌표
  var pt = this.mapObj.getCenterPointPx();  // 중심 픽셀좌표
  this.scrWidth = this.mapObj.divCon.clientWidth; // 화면객체 넓이
  this.scrHeight = this.mapObj.divCon.clientHeight; // 화면객체 높이
  this.scrLeft = Math.round(pt.x - this.scrWidth / 2);  // 오차계산
  this.scrTop = Math.round(pt.y + this.scrHeight / 2);
};

