// Name: setDrawMode
// Desc: 그리기모드 설정
// Args:
// Date: 2007-11-15
// Edit:
FreeMapGraphics.prototype.setDrawMode = function(drawMode){ // 그리기모드설정
  if(this.drawMode != "normal" && this.clickCnt != 0){
    return;
  }
  this.drawMode = drawMode;
  if(drawMode == "line")
    setCursor(this.mapObj.div, this.distcursor);
  else if(drawMode == "polyline")
    setCursor(this.mapObj.div, this.distcursor);
  else if(drawMode == "area")
    setCursor(this.mapObj.div, this.areacursor);
  else if(drawMode == "mypin")
  	setCursor(this.mapObj.div, this.mypincursor);
  else if(this.drawMode == "circle")
    setCursor(this.mapObj.div, this.circlecursor);
  else if(this.drawMode == "land")
    setCursor(this.mapObj.div, this.landcursor);
  else
    setCursor(this.mapObj.div, this.handcursor);

  FreeMapEvent.trigger(this, "setmode", this.drawMode);
};

