// Name: tmtoScrPixel
// Desc: 중부좌표를 화면좌표로
// Args:
// Date: 2007-11-15
// Edit: 2007-11-17 파이어폭스 캔버스 여유 추가
FreeMapGraphics.prototype.tmtoScrPixel = function(ptX, ptY, level){
  var point = new FreeMapPoint(ptX, ptY);

  if (this.mapObj.options.OptionMapOpener == "D") {
      if (typeof inChangePointEx == 'function') {
