// 이  름 : methodTime
// 인  자 : dist - 거리, mpermin - 거리를 시간으로
// 내  용 : 거리를 도보, 자전거 시간으로 바꿔줌
// 날  짜 : 2007-10-28
// 작업자 : 서형진(Kainess)
// 수  정 :
FreeMapGraphics.prototype.methodTime = function(dist, mpermin){
  var result;
  var min;
  var hour;
	min = Math.round(dist/mpermin);
	hour = Math.round(min/60);
	min = Math.round(min%60);
	if((dist >= mpermin*60)&&(dist <= mpermin*60*10))
	  result = hour + "시간 " + min + "분";
	else if(dist > 40200)
	  result = hour + "시간";
	else
	  result = min + "분";
  return result;
};

// 이  름 : deleteObj
// 인  자 : id - 디바이드 인덱스번호
// 내  용 : 인덱스번호에 맞는 자식노드를 지워줌, 그리기, 텍스트, 임시텍스트 Div 지우기
// 날  짜 : 2007-10-23
// 작업자 : 서형진(Kainess)
// 수  정 :
FreeMapGraphics.prototype.deleteObj = function(id){
  if(this.drawingText == true)
    this.textBoxDiv[id].parentNode.removeChild(this.textBoxDiv[id]);
  this.drawDiv[id].parentNode.removeChild(this.drawDiv[id]);

  this.container[id-50].drawMode = "destroyed";
  this.change_txetboxClick(false);
};

FreeMapGraphics.prototype.deleteNow = function(){
  if(this.clickCnt == 0){
    return;
  }
  if((this.drawMode == "line" || this.drawMode == "polyline") && this.drawingText == true) // 선그리기이면
  {
    this.drawDiv[this.drawIdx].removeChild(this.tmpTextboxDiv[0]);  // 시작표시 제거
  }
  this.tmpTextDiv.parentNode.removeChild(this.tmpTextDiv);  // 이동텍스트박스 제거
  this.tmpDrawDiv.parentNode.removeChild(this.tmpDrawDiv);  // 임시그리기 제거

  this.container.pop();
  this.drawDiv[this.drawIdx].parentNode.removeChild(this.drawDiv[this.drawIdx]);  // 그려진 객체 제거
  this.isDraw = false;  // 그려지기 불가능
  this.clickCnt = 0;  // 클릭횟수 0
  this.realPt = new Array();
  return; // 종료
};

// 이  름 : drawBack
// 인  자 :
// 내  용 : 뒤로(마지막꺼지우기)
// 날  짜 : 2007-11-22
// 작업자 : 서형진(Kainess)
// 수  정 :
FreeMapGraphics.prototype.drawBack = function(){
  if(this.drawIdx >= 50){
    this.drawIdx = this.drawIdx-1;
    this.deleteObj(this.drawIdx);
  }
}

// 이  름 : deleteAllObj
// 인  자 :
// 내  용 : 전체 그리기 객체 삭제
// 날  짜 : 2007-11-19
// 작업자 : 서형진(Kainess)
// 수  정 :
FreeMapGraphics.prototype.deleteAllObj = function(){
  var len = this.container.length;
  for(var i=0; i<len; i++)
  {
    if(this.container[i].drawMode != "destroyed")
    {
      if(this.drawingText == true && this.container[i].drawMode != "circle")
        this.textBoxDiv[50+i].parentNode.removeChild(this.textBoxDiv[50+i]);
      this.drawDiv[50+i].parentNode.removeChild(this.drawDiv[50+i]);
    }
  }

  this.drawIdx = 50;
  delete(drawDiv);
  delete(textBoxDiv);
  delete(tmpTextboxDiv);
  delete(pDraw);
  delete(svg);
  delete(this.container);
  //this.drawDiv = new Array();
  this.textBoxDiv = new Array();
  this.tmpTextboxDiv = new Array();
  this.pDraw = new Array();
  this.svg = new Array();
  this.container = new Array();
};

