FreeMapGraphics.prototype.drawPolyLand = function(parentObj, point) {
  var pathInfo;
  if(this.browse == "FF") // 파이어폭스일때
  {
    parentObj = this.svg;  // parentObj는 svg객체
    pathInfo = this.getLandPathInfo2(point);  // 파이어폭스용 패스 생성
  }
  else{
    pathInfo = this.getLandPathInfo(point); // 익스플로러용 패스 생성
  }
  this.drawIt.setStrokeColor("blue");
  this.drawIt.setFillColor("#31acf8");
  return this.drawIt.drawPolyLand(parentObj, pathInfo);  // 다각형 그리기
};

FreeMapGraphics.prototype.getLandPathInfo = function(point) {
  var pathInfo = "";
  var tmpPt = new Array();
	for(var i=0; i<point.length; i++) {
	  if(i==0) {
	    pathInfo += "m";
		}

		pathInfo += point[i].x + "," + point[i].y;

    if (i==point.length-1) {
		  pathInfo += "xe";
		} else {
		  pathInfo += "l";
		}
	}
	return pathInfo;
};

FreeMapGraphics.prototype.getLandPathInfo2 = function(coordArr){
  var pathInfo = "";
  for(var i=0; i<coordArr.length; i++)
  {
    pathInfo += coordArr[i].x + ", " + coordArr[i].y;
    if(i != coordArr.length)
    {
      pathInfo += " ";
    }
  }
  return pathInfo;
};

FreeMapGraphics.prototype.coordArrtoScr = function(coordArr) {
  var tmpArr = new Array();

  for(var i = 0 ; i < coordArr.length ; i++)
  {
    tmpArr[i] = this.coordtoScr(coordArr[i]);
  }
  return tmpArr;
};

FreeMapGraphics.prototype.coordtoScr = function(coord) {
  var marginLeft = parseInt(this.mapObj.div.style.left);
  var marginTop = parseInt(this.mapObj.div.style.top);
  var leftTopPt = this.getMapLeftTop();
  coord = this.options.tmmidPoint2pixel(coord, this.mapObj.mLevel);
  if(this.browse == "FF")
  {
    coord.x = coord.x - leftTopPt.x - marginLeft - this.movingLeft + this.layerMargin; // 오차계산
    coord.y = leftTopPt.y - coord.y - marginTop - this.movingTop + this.layerMargin;
  }
  else
  {
    coord.x = coord.x - leftTopPt.x - marginLeft; // 오차계산
    coord.y = leftTopPt.y - coord.y - marginTop;
  }

  return coord;
};

FreeMapGraphics.prototype.getMapLeftTop = function () {
  //var centerPt = this.getCenter();
  var centerPt = this.mapObj.getCenterPointPx();
  var mapLeft = Math.round(centerPt.x - this.mapObj.divCon.clientWidth / 2);
  var mapTop = Math.round(centerPt.y + this.mapObj.divCon.clientHeight / 2);
  return new FreeMapPoint(mapLeft, mapTop);
};

FreeMapGraphics.prototype.redrawPolyLand = function() {
  var data = this.coordArrtoScr(this.landData);
  this.clearLandlayer();

  this.landDiv = this.createDIV(1);
  this.mapObj.landLayer.appendChild(this.landDiv);
  this.landDiv.style.left = this.movingLeft-this.layerMargin + "px";
  this.landDiv.style.top = this.movingTop-this.layerMargin + "px";
  if(this.browse == "FF")
  {
    this.svg = this.drawIt.init(this.landDiv);
  }
  this.landDiv = this.drawPolyLand(this.landDiv, data);
};

