FreeMapGraphicsIE.prototype.setBasicStyle = function(){
  this.setStrokeColor("#56ACD5");
  this.setStrokeWeight("2.5px");
  this.setStrokeStyle("single");
  this.setStrokeDashStyle("solid");
  this.setStrokeJoinStyle("miter");
  this.setStrokeOpacity("0.6");

  this.setFillColor("#56ACD5");
  this.setFillType("frame");
  this.setFillOpacity("0.3");
	this.setFillOn();
};

FreeMapGraphicsIE.prototype.setStrokes = function(parentObj){
  var obj = document.createElement("v:stroke");

	if(this.strokeColor)
	{
		parentObj.strokecolor = this.strokeColor;
		obj.color = this.strokeColor;
	}
	else
		obj.opacity = 0;
	if(this.strokeWeight)
	{
		parentObj.strokeweight = this.strokeWeight;
		obj.weight = this.strokeWeight;
	}
	if(this.strokeDashStyle)
		obj.dashstyle = this.strokeDashStyle;
	if(this.strokeLineStyle)
		obj.linestyle = this.strokeLineStyle;
	if(this.strokeJoinStyle)
		obj.joinstyle = this.strokeJoinStyle;
	if(this.strokeOpacity)
		obj.opacity = this.strokeOpacity;
	parentObj.appendChild(obj);

	return true;
};

FreeMapGraphicsIE.prototype.setFill = function(parentObj){
  var obj = document.createElement("v:fill");
	obj.on = this.onFlag;
	if (this.fillColor)
		obj.color = this.fillColor;
	if (this.fillType)
		obj.type = this.fillType;
	if (this.fillOpacity)
		obj.opacity = this.fillOpacity;
	parentObj.appendChild(obj);

	return true;
};

