FreeMapGraphicsFF.prototype.setBasicStyle = function(){
  this.setStrokeColor("#56ACD5");
  this.setStrokeWeight("2.5px");
  this.setStrokeStyle("single");
  this.setStrokeDashStyle("solid");
  this.setStrokeJoinStyle("miter");
  this.setStrokeOpacity("0.6");

  this.setFillColor("#56ACD5");
  this.setFillType("frame");
  this.setFillOpacity("0.3");
};

FreeMapGraphicsFF.prototype.setStrokes = function(parentObj){
  if (this.strokeColor && this.strokeColor.length > 0)
		parentObj.setAttribute("stroke", this.strokeColor);
	if (this.strokeWeight && this.strokeWeight.length > 0)
		parentObj.setAttribute("stroke-width", this.strokeWeight);
	if (this.strokeJoinStyle && this.strokeJoinStyle.length > 0)
		parentObj.setAttribute("stroke-linejoin", this.strokeJoinStyle);
	if (this.strokeOpacity && this.strokeOpacity.length > 0)
		parentObj.setAttribute("stroke-opacity", this.strokeOpacity);
};

FreeMapGraphicsFF.prototype.setFill = function(parentObj){
  if (this.fillColor && this.fillColor.length > 0)
		parentObj.setAttribute("fill", this.fillColor);
	if (this.fillOpacity && this.fillOpacity > 0)
	  parentObj.setAttribute("fill-opacity", this.fillOpacity);
		//parentObj.style.opacity = this.fillOpacity;
};

FreeMapGraphicsFF.prototype.setStrokeColor = function(strokeColor){
