FreeMapGraphicsFF.prototype.drawPolyLand = function(parentObj, pathInfo){
  var polygon = document.createElementNS("http://www.w3.org/2000/svg", "polygon");
	polygon.setAttribute("points", pathInfo);
	this.setStrokes(polygon);
	this.setFillEmpty();
	this.setFill(polygon);
	parentObj.appendChild(polygon);
	return polygon;
};

