FreeMapZoomControlScourt.prototype.onDragStart = function (evtObj) {
	var e = evtObj || window.event;
	this.stickHiehgt	= evtObj.clientY;
	this.stickTop		= parseInt(this.zoomStick.style.top);
	this.fpDrag			= FreeMapEvent.link(this.zoomStick, "mousemove", this, this.dragHandler);
	this.fpDragStop		= FreeMapEvent.link(this.zoomStick, "mouseup", this, this.onDragStop);
	if (this.zoomStick.setCapture) {
		this.zoomStick.setCapture();
	}
	// FreeMapEvent.disableNotifyEvent(e);
};

FreeMapZoomControlScourt.prototype.showFlashmap = function () {
  FreeMapEvent.trigger(this,"showFlashmap");
};

FreeMapZoomControlScourt.prototype.mouseoverhandler = function () {
  FreeMapEvent.trigger(this,"mouseover");
};

FreeMapZoomControlScourt.prototype.onmouseouthandler = function () {
  FreeMapEvent.trigger(this,"mouseout");
};

FreeMapZoomControlScourt.prototype.dragHandler = function (evtObj) {
	var e = evtObj || window.event;

	if(this.parentObj.mapMode == "circle"){
	  return;
	}
	var curStickHeight =  this.stickTop + evtObj.clientY - this.stickHiehgt;

	if (curStickHeight < 84) {
		curStickHeight = 84;
	}

	if (curStickHeight > 162) {
		curStickHeight = 162;
	}
	this.zoomStick.style.top = curStickHeight + "px";
	// FreeMapEvent.disableNotifyEvent(e);
};

FreeMapZoomControlScourt.prototype.onDragStop = function (evtObj) {
	var e = evtObj || window.event;
	var stickTop = parseInt(this.zoomStick.style.top);
	var zoomLevel = Math.max(Math.min(Math.ceil((155 - stickTop) / 6 + 1), 13), 0);
	if(stickTop == 162)
	  zoomLevel = 0;
	this.parentObj.setZoomLevel(zoomLevel);
	FreeMapEvent.detachEvent(this.zoomStick, "mousemove", this.fpDrag);
	FreeMapEvent.detachEvent(this.zoomStick, "mouseup", this.fpDragStop);

	if (document.releaseCapture) {
		document.releaseCapture();
	}
	// FreeMapEvent.disableNotifyEvent(e);
};

FreeMapZoomControlScourt.prototype.unloadHandler = function () {
	this.removeChild(this.zoomStick);
	this.removeChild(this.zoomScaler);
	this.removeChild(this.zoomInBtn);
	this.removeChild(this.zoomOutBtn);
	this.zoomStick	= null;
	this.zoomScaler	= null;
	this.zoomInBtn	= null;
	this.zoomOutBtn	= null;
	FreeMapLayer.prototype.unloadHandler.call(this);
};

FreeMapZoomControlScourt.prototype.zoomSize = function () {
	this.setSize(new FreeMapSize(70, 200));
	this.zoomStick.style.left = "30px";
	this.zoomScaler.style.left = "28px";
	this.zoomInBtn.style.left = "35px";
	this.zoomOutBtn.style.left = "35px";
};

FreeMapZoomControlScourt.prototype.getFlashmap = function () {
  return this.flashMap;
};

FreeMapZoomControlScourt.prototype.setScale = function (evtObj) {
	var e	= evtObj || window.event;

	if(this.parentObj.mapMode == "circle"){
	  return;
	}
	var pos	= FreeMapEvent.getClickPos(e, e.target||e.srcElement);

	if(pos.y < 23 || pos.y > 110)
	  return;
	var zoomStickHeight = pos.y+57;
	if (zoomStickHeight < 84) {
		zoomStickHeight = 84;
	}
	if (zoomStickHeight > 162) {
		zoomStickHeight = 162;
	}
	var curLevel = Math.max(Math.min(Math.round((162 - zoomStickHeight) / 6 + 1), 13), 1);
	if(zoomStickHeight == 162)
	  curLevel = 0;
	this.parentObj.setZoomLevel(curLevel);
	// FreeMapEvent.disableNotifyEvent(e);
};

FreeMapZoomControlScourt.prototype.onZoomIn = function () {
	this.parentObj.zoomIn();
};

FreeMapZoomControlScourt.prototype.onZoomOut = function () {
	this.parentObj.zoomOut();
};

FreeMapZoomControlScourt.prototype.onZoomHandler = function (curLevel) {
	var stickTop = 156 - (curLevel - 1) * 6;
	this.zoomStick.style.top = stickTop + "px";
};

FreeMapZoomControlScourt.prototype.setZIndex = function (zidx) {
	this.ctrlZIndex = zidx;
};
