function FreeMapText (offset) {
	this.parentObj = null;
	this.mkSize = new FreeMapSize(0,0);
	if (!offset) this.offset = new FreeMapPoint(0,0);
	else this.offset = offset;
}

FreeMapText.prototype.initialize = function (parentObj) {
	this.alignPos = new FreeMapPoint(1,0);
	this.textSize = new FreeMapSize(0, 0);
	this.redrawFunc = FreeMapEvent.createCallBackFunc(this,this.redrawHandler);
	this.parentObj = parentObj;
	this.textDiv = this.parentObj.createDIV(5);
	this.parentObj.textLayer.appendChild(this.textDiv);
	this.initText();
};

FreeMapText.prototype.initText = function () {
	this.textDiv.style.backgroundColor = "transparent";
	this.textDiv.style.padding = "0px 0px 0px 0px";
	this.setOpacity(1);
	this.textDiv.style.display = "none";
	this.contentsDiv = this.parentObj.createDIV(0);
	this.textDiv.appendChild(this.contentsDiv);
	this.contentsDiv.style.backgroundColor = "transparent";
	this.contentsDiv.style.position = "relative";
	this.contentsDiv.style.padding = "0px 0px 0px 0px";
	this.contentsDiv.style.left = "0px";
	this.contentsDiv.style.top = "0px";
};

FreeMapText.prototype.setContents = function (contents) {
	this.contentsDiv.style.width = this.textSize.width;
	this.contentsDiv.style.height = this.textSize.height;
	this.textDiv.style.width = this.textSize.width;
	this.textDiv.style.height = this.textSize.height;
	this.contentsDiv.innerHTML = contents;
	if (this.textDiv.style.display !="none") {
		this.redrawHandler();
	}
};

FreeMapText.prototype.setPosition = function (pos) {
	this.textPos = pos;
	if (this.textDiv.style.display !="none") {
		this.redrawHandler();
	}
};

FreeMapText.prototype.getPosition = function () {
	return this.textPos;
};

FreeMapText.prototype.setSize = function (winSize) {
	this.textSize.set(winSize.width, winSize.height);
};

FreeMapText.prototype.getSize = function () {
	return this.textSize;
};

FreeMapText.prototype.setOpacity = function (op) {
	this.textDiv.style.opacity = op;
	// IE에서 Opacity의 부모 자식간의 중복시 레이어의 사라짐 때문에 라벨일 경우만 Opacity적용.
	this.textDiv.style.filter ='alpha(opacity = '+(op*100)+')';
};

FreeMapText.prototype.getOpacity = function () {
	return this.textOp;
};

FreeMapText.prototype.show = function () {
	if (this.hideTimeout) {
		window.clearTimeout(this.hideTimeout);
		this.hideTimeout = null;
	}
	this.alignPos.set(1, 0);
	FreeMapEvent.addListener(this.parentObj, "redraw", this.redrawFunc);
	FreeMapEvent.addListener(this.parentObj, "move", this.redrawFunc);
	this.textDiv.style.display = '';
	this.redrawHandler();
};

FreeMapText.prototype.set = function (pos, contents) {
	this.textPos = pos;
	this.setContents(contents);
};

FreeMapText.prototype.redrawHandler = function () {
	if (null == this.parentObj || null == this.textPos || this.textDiv.style.display=='none') {
		return;
	}
	//this.textDiv.style.width = this.contentsDiv.offsetWidth;
	//this.textDiv.style.height = this.contentsDiv.offsetHeight;
	this.locateText();
};

FreeMapText.prototype.locateText = function () {
	var pxPos = this.parentObj.getPosition(this.parentObj.options.tmmidPoint2pixel(this.textPos, this.parentObj.mLevel));
	//var adjustX = Math.floor(this.textDiv.offsetWidth / 2);
	var adjustX = this.textSize.width/2;

	var topVal = 0;
	var leftVal = 0;
	leftVal = pxPos.x - adjustX;
	topVal = pxPos.y - this.textSize.height/2 - this.mkSize.height - 1;
	this.textDiv.style.left = leftVal + this.offset.x + "px";
	this.textDiv.style.top = topVal + this.offset.y + "px";
};

FreeMapText.prototype.unloadHandler = function () {
	if (this.textDiv != null) this.textDiv.removeChild(this.contentsDiv);
	this.contentsDiv = null;
	if (this.parentObj != null) this.parentObj.textLayer.removeChild(this.textDiv);
	this.textDiv = null;
	this.textPos = null;
	this.redrawFunc = null;
	this.parentObj = null;
	this.offset = null;
};

FreeMapText.prototype.setOffset = function (offset) {
	this.offset.set(offset.x, offset.y);
	this.redrawHandler();
};

FreeMapText.prototype.getOffset = function () {
	return this.offset;
};

function FreeMapEvent(){
}

FreeMapEvent.addListener = function (elemObj, sEvent, fpNotify){
	var eventString = this.createEventString(sEvent);
	if (elemObj[eventString]) {
		elemObj[eventString].push(fpNotify);
	}
	else {
		elemObj[eventString] = new Array(fpNotify);
	}
}

FreeMapEvent.createEventString=function (sEvent){
	return ("fm_event_" + sEvent);
}

FreeMapEvent.removeListener=function (elemObj, sEvent, fpNotify){
	var eventString = this.createEventString(sEvent);
	var tmpfpNotify = elemObj[eventString];
	if (tmpfpNotify && tmpfpNotify.length > 0) {
		var flag = false;
		for (var i=0; i < tmpfpNotify.length; i++) {
			if (tmpfpNotify[i] == fpNotify) {
				flag = true;
			}
			if ( flag && i != (tmpfpNotify.length - 1) ) {
				tmpfpNotify[i] = tmpfpNotify[i+1];
			}
		}
		if (flag) {
			tmpfpNotify.pop();
		}
	}
}

FreeMapEvent.attachEvent=function (elemObj, sEvent, fpNotify){
	if (elemObj.addEventListener) {
		// addEventListener는 이벤트 대상에 이벤트 Listener들을 등록한다.(DOM)
		elemObj.addEventListener(sEvent, fpNotify, false);
	}
	else{
		// 개체에서 이벤트가 발생되면 기능함수를 호출할 수 있도록 이벤트에 특정 엘레멘트를 연결한다.(JS)
		elemObj.attachEvent("on"+sEvent, fpNotify);
	}
}

FreeMapEvent.detachEvent = function (elemObj, sEvent, fpNotify) {
	if (elemObj.removeEventListener) {
		// 이벤트 대상 개체에서 해당 이벤트를 삭제한다.(DOM)
		elemObj.removeEventListener(sEvent, fpNotify, false);
	}
	else{
		// 이벤트가 발생되었는지를 알려주는 기능을 중지키시기 위하여 이벤트로 부터 지정된 기능을 해제한다.(JS)
		elemObj.detachEvent("on"+sEvent, fpNotify);
	}
}

FreeMapEvent.bind = function (elemObj, sEvent, srcObj, fpNotify) {

	var fpCreatedNotify = FreeMapEvent.createCallBackFunc(srcObj, fpNotify);
	FreeMapEvent.addListener(elemObj, sEvent, fpCreatedNotify);
	return fpCreatedNotify;
}

FreeMapEvent.link = function (elemObj,sEvent,srcObj,fpNotify) {

	var fpRegNotify = FreeMapEvent.regCallBackFunc(srcObj, fpNotify);
	FreeMapEvent.attachEvent(elemObj, sEvent, fpRegNotify);
	return fpRegNotify;
}

FreeMapEvent.trigger = function (elemObj, sEvent) {
	var eventString = FreeMapEvent.createEventString(sEvent);
	var arrMapEvent = elemObj[eventString];
	if (arrMapEvent && (arrMapEvent.length > 0)) {
		var args = new Array();
		for (var i=2;i<arguments.length;i++) {
			args.push(arguments[i]);
		}
		args.push(elemObj);
		for (var i=0;i<arrMapEvent.length;i++) {
			var mapEvent = arrMapEvent[i];
			if (mapEvent) {
				mapEvent.apply(elemObj,args);
			}
		}
	}
}

FreeMapEvent.regCallBackFunc = function (srcObj, fpNotify){
	return function ( evtObj ) {
		if (!evtObj) evtObj = window.event;
		if (evtObj && !evtObj.target) evtObj.target = evtObj.srcElement;
		fpNotify.call(srcObj, evtObj);
	}
}

FreeMapEvent.createCallBackFunc = function (srcObj, fpNotify){
	var rtnFunc = function () {
		fpNotify.apply(srcObj, arguments);
	}
	return rtnFunc;
}

FreeMapEvent.disableNotifyEvent = function(evtObj)
{
	if (bIsMSIE)	{	// I.E.
		window.event.cancelBubble = true;
		window.event.returnValue = false
	}
	else {
		if (evtObj)	{
			evtObj.cancelBubble = true;
			evtObj.preventDefault();
			evtObj.stopPropagation();
		}
	}
}

FreeMapEvent.getClickPos = function (evtObj, elemObj) {
	var pos = new FreeMapPoint(0, 0);
	if(!bIsMSIE) {
		pos.set(evtObj.pageX, evtObj.pageY);
		while(elemObj) {
			pos.add( -elemObj.offsetLeft, -elemObj.offsetTop);
			elemObj = elemObj.offsetParent;
		}
	}
	else if (typeof(evtObj.offsetX) != "undefined") {	// I.E.
		var evtTarget = evtObj.target || evtObj.srcElement;
		while( evtTarget && evtTarget != elemObj ) {
			pos.add( evtTarget.offsetLeft, evtTarget.offsetTop );
			evtTarget = evtTarget.offsetParent;
		}
		pos.add( evtObj.offsetX, evtObj.offsetY );
	}
	else if (typeof(evtObj.pageX) != "undefined" ) { // F.F.
		pos.set(evtObj.pageX, evtObj.pageY);
		while(elemObj) {
			pos.add( -elemObj.offsetLeft, -elemObj.offsetTop);
			elemObj = elemObj.offsetParent;
		}
	}
	return pos;
}
