function outChangePointEx(vMode, vPointBound, vOpenMapType)
{

    /* * vMode : B=Bound, P=Point
     * vPointBound : Mode에 따라
     * vBound : ( 최소좌표x, 최대좌표y, 최대좌표x, 최소좌표y ) 순의 MBR 배열
     * vPoint : X,Y (FreeMapPoint)
     * vOpenMapType : 맵 유형*/


    var pointBound = vPointBound;

    // s
    if (vOpenMapType == "D") {
        if (vMode == "B") {
            var tmp_min_cnt = new FreeMapPoint(pointBound[0], pointBound[3]);
            var tmp_max_cnt = new FreeMapPoint(pointBound[2], pointBound[1]);
            var cvt_min_cnt = Convert_UTMK_KATEC(tmp_min_cnt);
            var cvt_max_cnt = Convert_UTMK_KATEC(tmp_max_cnt);

            pointBound = Array(cvt_min_cnt.x, cvt_max_cnt.y, cvt_max_cnt.x, cvt_min_cnt.y);
        } else if (vMode == "P") {
            pointBound = Convert_UTMK_KATEC(pointBound);
        }
    }
    // e

    return pointBound;
}

