/* tooltip */
.toolTip {display: inline-block !important;vertical-align: middle;margin-left: 5px;}
.toolTipTxt { display: none !important; position: absolute;margin: 20px 0px 0px -2px;width: auto;max-width: 300px;border: 2px solid #889bab;border-radius: 5px;padding: 7px 7px 7px 5px;font-size: 13px;line-height: 1.5;letter-spacing: 0px;color: #222; text-align:left; background: #f4fbff;box-shadow: 0px 1px 3px #999;z-index: 101;}
.toolTipTxt::before {position: absolute;top: -5px;left: 6px;width: 5px;height: 5px;content: '';display: inline-block;border-top: 2px solid #889bab;border-right: 2px solid #889bab;background: #f4fbff;transform: rotate(-45deg);z-index: 3;}
.toolTipTxt.right { right: 0;}
.toolTipTxt.right::before {position: absolute;top: -5px;left: 286px;width: 5px;height: 5px;content: '';display: inline-block;border-top: 2px solid #889bab;border-right: 2px solid #889bab;background: #f4fbff;transform: rotate(-45deg);z-index: 3;}
.toolTipTxt.bottom{bottom:30px; margin:0 0 20px 0;}
.toolTipTxt.bottom::before{position: absolute; top:auto; bottom: -5px !important;left: 6px;width: 5px;height: 5px;content: '';display: inline-block;border-bottom: 2px solid #889bab !important ;border-left: 2px solid #889bab !important; border-right: none; border-top: none;background: #f4fbff;transform: rotate(-45deg);z-index: 3;}

.toolTipTxt.on{ display: block !important; }

.toolTipTxt dt {list-style: none; padding-left: 15px; text-indent: -10px; margin-bottom: 3px; color: #222; font-size: 13.4px; }
.toolTipTxt dt span, .txtBox dd span { color: #F00 }
.toolTipTxt dt:last-child { margin-bottom: 0px }
.toolTipTxt dt:before {content:'●';color: #848f98;font-size: 10px;vertical-align: text-bottom;margin-right: 5px;font-family: Arial;}
.toolTipTxt dd {list-style: none;padding-left: 20px;text-indent: -8px;margin-bottom: 3px;margin-inline-start: 7px;font-weight: 400;color: #444;}
.toolTipTxt dd:before { content:'-';color: #848f98;font-size: 10px;vertical-align: text-bottom;margin-right: 5px;font-family: Arial;}
