.topMenu > li > a {display:inline-block;width:100%;height:100%; line-height: 50px; border-left: 1px solid #1b6080; font-size: 16px; font-weight: 400;color: #FFF;}
.topMenu > li:last-child a{border-right: 1px solid #1b6080;}

/* Header Top info Box */
.infoTopBox {display: block;float:right;margin:28px 15px 0px 0px;}
.infoTopBox .w2trigger {display: inline-block;margin-left: 15px;line-height: 22px;padding: 0px 15px;}

/* header depth2 */
.topMenu .depth2{position:absolute;left:0;top:50px;width:100%;height:500px;padding:10px 0;border-left:1px solid rgba(255, 255, 255, .2);background:#41525a;z-index:2001;}
