.bot_option .linkbox .list{display:none;position:absolute;left:0;bottom:70px;width:100%;max-height:442px;background:#43464d;z-index:1999;overflow-y:auto;box-shadow:5px 5px 5px rgba(0, 0, 0, .2)}
