.bot_option .btn_foot{display:inline-block;height:70px;padding:17px 60px 17px 22px;border:0;border-left:1px solid #7c7e83;font-size:16px;text-align:left;color:#c4c4c4;background:url(/pgj/cm/images/contents/btn_foot.png) no-repeat 90% center;}
