.bot_option .policybox .w2anchor2:first-child{padding-left:0;}
.bot_option .policybox .w2anchor2::after{display:block;position:absolute;right:0;top:50%;width:5px;height:5px;margin-top:-2.5px;background:#6f6f6f;content:'';}
.bot_option .policybox .w2anchor2:last-child::after{display:none;}
.bot_option .policybox .w2anchor2:hover, .footer .policybox .w2anchor2:focus{color:#80b3ff}
.bot_option .bot_bottom{padding:25px 0;}
.bot_option .bot_bottom .w2span{display:inline-block;padding:0 6px;font-size:16px;line-height:30px;font-size:14px;vertical-align:middle;color:#c4c4c4;}

/* side menu */
.mainSide{background:#fff;float:left;margin:20px 10px 0px 10px}
.conBox{position:relative;right:unset;top:unset;bottom:unset;min-height:500px;margin-left:0;padding:20px 15px 50px 10px;overflow:hidden}
