ul.w2group.sMenu li > ul > li > a {font-size: 14px;font-weight: 400;text-indent: 30px;background: #f9f9f9;height: 30px;line-height: 30px;border: 1px solid #CCC;border-bottom: 0px;}
ul.w2group.sMenu li > ul > li > ul > li > a {font-size: 14px;font-weight: normal;text-indent: 40px;height: 30px;line-height: 30px;border-top: 0px;background: #f9f9f9;}
ul.w2group.sMenu li a.hover, ul.w2group.sMenu li a.active {background: #07425d;border: 1px solid #07425d;border-bottom: 0px;box-sizing: border-box;color: #FFF;}
.btn_aside {width: 28px;height: 70px;padding: 0;margin:0;font-size:0;line-height:0;overflow:hidden;background: #fff;position: absolute;top: 0px;border-radius: 0px 3px 3px 0px;text-align: center;border: 1px solid #999;box-sizing: border-box;border-left: 0px;}
