.conBox .sjtTit {color: #000;font-size: 21px;font-weight: 500;line-height: 35px;height: 35px;display: table;float: left;letter-spacing: -0.5px;}
.conBox .adminTit {color: #000;font-size: 22px;font-weight: 500;line-height: 1;height: 30px;display: block;clear: both;letter-spacing: -2px;width: auto;float: left;}

/* etc */
