/*------------------------------------------------------------------

[Main Page StyleSheet]

    Project:        대법원 법원경매정보
    Version:        1.0
    Last change:    2022.8.17.

-------------------------------------------------------------------*/

/* layout */
.main_ly{display:flex;flex-flow:wrap}
.main_ly .mainbox{width:100%}
.main_ly .mainbox .box{position:relative;height:calc(100% - 30px);margin:15px 20px;padding:30px;border-radius:3px;background:#fff}
.main_ly .mainbox.t_line .box{border-top:2px solid #222;border-top-left-radius:0;border-top-right-radius:0}
.main_ly .mainbox.bd .box{border:1px solid #ddd}
.main_ly .mainbox.col25{width:25%}
.main_ly .mainbox.col5{width:50%}
.main_ly .mainbox.col75{width:75%}
.main_container .main_top{padding:40px 0;background:#f5f5f5}
.main_container .main_bottom{padding:40px 0 60px}


/* main slider */
.slider_wrap{position:relative}
.wrap .main_container .slider_wrap .above_box{position:absolute;left:0;top:0;width:100%;height:100%;z-index:2}
.wrap .main_container .slider_wrap .above_box .inr{display:table;position:relative;height:100%;width:1240px}
.wrap .main_container .slider_wrap .bx-controls-direction{display:none}
.main_container .main_slider{width:600px;height:450px;position:relative}
.main_container .main_slider .slider_item{display:flex;justify-content:center;align-items:center;width:100%;height:450px;background:url(/pgj/cm/images/contents/bg_mainSlider1.png) no-repeat left top;background-size:cover}
.main_container .main_slider .slider_item.car{background-image:url(/pgj/cm/images/contents/bg_mainSlider2.png)}
.main_container .main_slider .slider_item.comm{background-image:url(/pgj/cm/images/contents/bg_mainSlider3.png)}
.main_container .main_slider .slider_item.land{background-image:url(/pgj/cm/images/contents/bg_mainSlider4.png)}
.main_container .main_slider .slider_item.indust{background-image:url(/pgj/cm/images/contents/bg_mainSlider5.png)}
.main_container .main_slider .slider_item.forest{background-image:url(/pgj/cm/images/contents/bg_mainSlider6.png)}
.main_info{position:absolute;right:0;top:35px;text-align:right;font-size:20px;color:#fff}
.main_info .txt_num{font-family:'Roboto';font-size:70px;font-weight:700}
.main_info .txt_per{font-family:'Roboto';font-size:30px}
.slider_wrap .slider_title{display:table-cell;vertical-align:middle}
.slider_wrap .slider_title > *{font-size:60px;font-weight:100;color:#fff;letter-spacing:-1px}
.slider_wrap .slider_list{position:absolute;right:0;bottom:40px;width:320px;border-radius:4px;overflow:hidden}
.slider_wrap .slider_list::after{display:block;clear:both;content:''}
.slider_wrap .slider_list a{display:inline-block;float:left;width:50%;height:80px;text-align:center;list-style:none;border:1px solid rgba(255, 255, 255, .1);background:rgba(0, 0, 0, .9);cursor:pointer}
.slider_wrap .slider_list a:hover, .slider_wrap .slider_list a:focus, .slider_wrap .slider_list a.active{background:rgba(12, 54, 186, .9);transition:all .2s}
.slider_wrap .slider_list a span{display:inline-block;margin-top:25px;padding-left:30px;font-size:20px;color:#fff;background:url(/pgj/cm/images/contents/ico_mainSlider.png) no-repeat left 5px}
.slider_wrap .slider_list a.car span{padding-left:34px;background-position:-156px 8px}
.slider_wrap .slider_list a.comm span{background-position:left -46px}
.slider_wrap .slider_list a.land span{padding-left:32px;background-position:-156px -48px}
.slider_wrap .slider_list a.indust span{background-position:left -105px}
.slider_wrap .slider_list a.forest span{padding-left:37px;background-position:-156px -100px}

/* main title */
.title_box{margin-bottom:15px}
.title_box::after{display:block;clear:both;content:''}
.title_box .main_title{display:inline-block;font-size:20px;font-weight:600;letter-spacing:-1px;color:#222}
.title_box .txt_ex{display:inline-block;margin-left:25px;font-size:16px;letter-spacing:-1px;color:#606060}

/* 로그인 */
.mainbox .btns_login{margin-bottom:15px}
.mainbox .btns_login .w2trigger{display:inline-block;width:50%;height:80px;border:1px solid #d4d4d4;font-size:20px;color:#222;background:#fff}
.mainbox .btns_login .w2trigger:nth-of-type(1){font-weight:500;border-color:#01998a;border-top-left-radius:6px;border-bottom-left-radius:6px;color:#fff;background:#01998a}
.mainbox .btns_login .w2trigger:nth-of-type(1):hover, .mainbox .btns_login .w2trigger:nth-of-type(1):focus{background:#038f81;transition:all .2s}
.mainbox .btns_login .w2trigger:nth-of-type(2){border-top-right-radius:6px;border-bottom-right-radius:6px}
.mainbox .btns_login .w2trigger:nth-of-type(2):hover, .mainbox .btns_login .w2trigger:nth-of-type(2):focus{background:#fbfbfb;transition:all .2s}
.mainbox .btns_idpw{margin-bottom:15px}
.mainbox .btns_idpw .w2trigger{display:inline-block;width:50%;height:60px;border:1px solid #e3e3e3;font-size:16px;color:#222;background:#fff}
.mainbox .btns_idpw .w2trigger:nth-of-type(1){border-top-left-radius:6px;border-bottom-left-radius:6px}
.mainbox .btns_idpw .w2trigger:nth-of-type(2){border-top-right-radius:6px;border-bottom-right-radius:6px}
.mainbox .btns_idpw .w2trigger:hover, .mainbox .btns_idpw .w2trigger:focus{background:#fbfbfb;transition:all .2s}
.mainbox .bt_favor{display:inline-block;width:180px;padding-left:40px;text-align:left;font-size:16px;color:#4b4b4b;background:url('/pgj/cm/images/contents/btn_favor.png') no-repeat left center;word-break:keep-all}
.mainbox .bt_favor:hover, .mainbox .bt_favor:focus{color:#0c36ba}

