.schd_tab_type1 > .w2tabcontrol_tabhost > li:last-child{border-top-right-radius:4px;border-bottom-right-radius:4px}
.schd_tab_type1 .w2tabcontrol_container{float:none;border:0}
.schd_tab_type1 .w2tabcontrol_contents_wrapper{overflow:inherit}
.schd_tab_type2{margin-top:20px}
