.schd_tab_type2 .w2tabcontrol_tabhost{float:none;height:40px}
.schd_tab_type2 .w2tabcontrol_tabhost li{width:33.333%;height:40px;margin:0;border:1px solid #fff;border-bottom:1px solid #cdcdcd}
.schd_tab_type2 .w2tabcontrol_tabhost li.w50{width:50%}
.schd_tab_type2 .w2tabcontrol_tabhost li.w2tabcontrol_active, .schd_tab_type2 .w2tabcontrol_tabhost li.w2tabcontrol_selected{background:#fff;border:1px solid #cdcdcd;border-bottom:0;border-top-left-radius:4px;border-top-right-radius:4px}
.schd_tab_type2 .w2tabcontrol_tabhost li a{display:inline-block;top:0;padding:12px 0;font-size:16px;font-weight:500;color:#6a6a6a}
.schd_tab_type2 .w2tabcontrol_tabhost li.w2tabcontrol_active a, .schd_tab_type2 .w2tabcontrol_tabhost li.w2tabcontrol_selected a{color:#222}
.schd_tab_type2 .w2tabcontrol_container{float:none;border:0;} /* padding 삭제 */

/* 공지사항 */
.notice_wrap{position:relative}
.notice_wrap .notice_list{position:relative; display: flex;}
.notice_wrap .notice_list li{flex:1; height:160px;padding:20px;border-radius:4px;font-size:18px;font-weight:500;letter-spacing:-1px;background:#f0f0f0}
.notice_wrap .notice_list li .w2anchor2{display:inline-block;position:relative;width:100%;line-height:1.5em;max-height:4.5em;margin-right:-1em;padding-right:1em;overflow:hidden;text-overflow:ellipsis;color:#555}
.notice_wrap .notice_list li .w2anchor2::before{content:'...';position:absolute;right:0;bottom:3px}
.notice_wrap .notice_list li .w2anchor2::after{content:'';position:absolute;right:0;width:1em;height:1em;margin-top:0.2em;background:#f0f0f0}
.notice_wrap .notice_list li .w2anchor2:hover, .notice_wrap .notice_list li .w2anchor2:focus{color:#222}
.notice_wrap .notice_list .txt_date{position:absolute;left:20px;bottom:20px;font-size:16px;font-weight:400;color:#605f70}
.notice_wrap .bx-wrapper .bx-controls{position:absolute;right:20px;bottom:15px}
.notice_wrap .bx-wrapper .bx-controls-direction a{display:inline-block;position:relative;top:0;right:0;left:0;margin:0;border:1px solid #e5e5e5;border-radius:4px;width:30px;height:30px;font-size:0;background:#fff url(/pgj/cm/images/contents/btn_mainNotice.png) no-repeat center 7px}
.notice_wrap .bx-wrapper .bx-controls-direction a:focus{outline:1px solid #222}
.notice_wrap .bx-wrapper .bx-controls-direction a.bx-prev{border-right:0;border-top-right-radius:0;border-bottom-right-radius:0}
.notice_wrap .bx-wrapper .bx-controls-direction a.bx-next{border-top-left-radius:0;border-bottom-left-radius:0;background-position:center -38px}

/* 용도별 물건정보 */
.mainbox .use_info{border:1px solid #ddd;border-left:0;border-bottom:0;border-radius:3px;oveflow:hidden}
.mainbox .use_info::after{display:block;clear:both;content:''}
.mainbox .use_info li{float:left;width:25%}
.mainbox .use_info li .w2anchor2{position:relative;display:inline-block;width:100%;padding:14px 10px;font-size:16px;letter-spacing:-1px;text-align:center;border-left:1px solid #ddd;border-bottom:1px solid #ddd;color:#323232}
.mainbox .use_info li .w2anchor2:hover, .use_info li .w2anchor2:focus{text-align:left;font-weight:500;color:#fff;background:#01998a; transition:all .2s}
.mainbox .use_info li:hover .w2anchor2::after{position:absolute;right:12px;top:50%;width:22px;height:8px;margin-top:-4px;background:url(/pgj/cm/images/contents/arr_useInfo.png) no-repeat left top;content:''}

/* 경매 도우미 */
.mainbox .help .inp{width:calc(100% - 55px);height:55px;border:0;border-top-left-radius:4px;border-bottom-left-radius:4px;font-size:16px;background:#f0f0f0}
.mainbox .help .bt_sch{display:inline-block;width:55px;height:55px;border:0;border-top-right-radius:4px;border-bottom-right-radius:4px;font-size:0;background:#0c36ba url(/pgj/cm/images/contents/ico_sch.png) no-repeat center}
.mainbox .help .bt_sch:hover, .mainbox .help .bt_sch:focus{background-color:#092c9c;transition:all .2s}
.mainbox .help .txt_ex{display:inline-block;padding:3px 15px;margin:10px 0 5px 0;font-size:16px;font-weight:500;border-radius:4px;color:#222;background:#f0f0f0}
.mainbox .ex_list .w2anchor2{display:inline-block;position:relative;margin:2px 4px;font-size:16px;color:#434343}
.mainbox .ex_list .w2anchor2:hover, .mainbox .ex_list .w2anchor2:focus{color:#0c36ba}
.mainbox .ex_list .w2anchor2::after{position:absolute;right:-8px;top:0;content:'/';color:#434343}
.mainbox .ex_list .w2anchor2:last-child::after{display:none}

/* 인포박스 - 제공서비스 안내, 잘활용하기, 나의동산집행정보 */
.mainbox .info_list li{position:relative;padding:25px 20px 25px 50px;font-size:15px;letter-spacing:-1px;color:#606060;background:url('/pgj/cm/images/contents/ico_mainInfo1.png') no-repeat left center;cursor:pointer}
.mainbox .info_list li::after{position:absolute;left:0;top:0;width:100%;height:5px;background:url('/pgj/cm/images/contents/bg_mainInfo.png') repeat-x left top;content:''}
.mainbox .info_list li:nth-of-type(1){padding-top:0;background-position:left 8px}
.mainbox .info_list li:nth-of-type(2){background-image:url('/pgj/cm/images/contents/ico_mainInfo2.png')}
.mainbox .info_list li:nth-of-type(1)::after{display:none}
.mainbox .info_list li:nth-of-type(3){padding-bottom:0;background-image:url('/pgj/cm/images/contents/ico_mainInfo3.png');background-position:left 35px}
.mainbox .info_list .tit{font-size:20px;font-weight:500;color:#222}

/* 다수 관심물건 */
.mainbox .inter_list{display:flex}
.mainbox .inter_list > li{width:calc(33.333% - 10px);border-radius:6px;font-size:16px;letter-spacing:-1px;color:#323232;transition:all .2s}
.mainbox .inter_list > li:hover, .mainbox .inter_list > li:focus{box-shadow:5px 5px 5px rgba(0, 0, 0, .2);cursor:pointer}
.mainbox .inter_list > li:nth-of-type(2){margin:0 30px}
.mainbox .inter_list .img_wrap{width:100%;border-radius:3px;overflow:hidden}
.mainbox .inter_list .img_wrap .w2image{width:100%;height:131px}
.mainbox .inter_list .w2textbox{padding-left:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mainbox .inter_list .tit{padding-top:20px;font-size:20px;font-weight:500;color:#222}
.mainbox .price_list{padding:8px 0 10px 10px}
.mainbox .price_list .txt_low{display:inline-block;margin:2px 23px 2px 0;padding:2px 12px;font-size:16px;border-radius:3px;color:#fff;background:#5d616a}
.mainbox .price_list .txt_app{display:inline-block;margin:2px 23px 2px 0;padding:2px 12px;font-size:16px;border-radius:3px;color:#fff;background:#0c36ba}

/*경매절차, 관련법률 */
.mainbox.know .box{display:flex}
.mainbox.know .title_box{width:30%}
.mainbox .know_list{display:flex;flex-flow:wrap;width:70%}
.mainbox .know_list li{position:relative;width:50%;padding-left:17px}
