*/

/*** 1-1 화면 타이틀   ***/

/* 화면상단 공통영역 */
.pgtbox{position:relative; display: flex; justify-content: space-between; align-items: center; width:100%;min-height:14px;padding:0;margin:0 0 14px;}
.pgtbox:after{display: none; visibility:hidden;clear:both;height:0;font-size:0;line-height:0;content:'.'}
.pgtbox .pgt_tit{display: inline-block; vertical-align: middle; margin:0 5px 0 0; font-size: 17px; font-weight: bold; color: #111;padding:0 0 0 30px;background:url(/pgj/cm/images/contents/bg_df_tit_ico.png) no-repeat;}
.pgtbox .pgt_tit.on:after {display:inline-block;}
.pgt_title_group {display: inline-block;}
.pgt.util_box{display: inline-block; vertical-align: middle; padding:0;margin:0;}
.pgt.util_box:after{display:block;visibility:hidden;clear:both;height:0;font-size:0;line-height:0;content:'.'}
.pgt_main {width: 100%; text-align: right; margin: 0 0 15px;}
.pgt_item {position: relative; display: inline-block; padding: 0 12px;}
.pgt_item:last-of-type {padding-right: 0;}
.pgt_item:not(:last-of-type)::after {position: absolute; display: block; content: ''; right: 0; width: 1px; top: 2px; bottom: 2px; background: #767676;}
.pgt_location_info {display: inline-block;}
.pgt_location_info::after {display: inline-block; vertical-align: middle; content: ''; width: 1px; height: 14px; margin: 0 10px 0 20px; background: #cdcdcd;}
.pgt_location_item {display: inline-block; vertical-align: middle;}
.pgt_location_item:not(:last-of-type)::after {display: inline-block; content: ''; vertical-align: middle; width: 5px; height: 8px; margin: 0 8px; background: url(/pgj/cm/images/contents/ico_loc_right.png) center no-repeat;}
.pgt_location_item a {padding: 1px 0; font-size: 12px; color: #767676; letter-spacing: .25px;}
.pgt_location_item a.current {color: #111; border-bottom: 1px solid rgba(17, 17, 17, .5);}
.pgt_util {display: inline-block; vertical-align: middle;}
.body_popup .pgt_util {position: relative;top: 6px}
.pgt_util > div {margin: 0 9px;}
.pgt_util > div:last-of-type {margin-right: 0;}

.pgt_view_toggle {position: relative;display: inline-block; border: 1px solid #dbdfe5; border-radius: 3px; background: #fff;}
.pgt_view_toggle a {display: inline-block; vertical-align: middle; width: 23px; height: 21px; font-size: 0; background: center no-repeat;}
.pgt_view_toggle a:not(:last-of-type) {border-right: 1px solid #dbdfe5;}
.pgt_view_toggle .view_type1 {background-image: url(/pgj/cm/images/contents/ico_viewtype1.png);}
.pgt_view_toggle .view_type2 {background-image: url(/pgj/cm/images/contents/ico_viewtype2.png);}
.pgt_view_toggle .view_type1.active {background-image: url(/pgj/cm/images/contents/ico_viewtype1on.png);}
.pgt_view_toggle .view_type2.active {background-image: url(/pgj/cm/images/contents/ico_viewtype2on.png);}
.pgt_view_toggle .view_type {display: inline-block; vertical-align: middle; width: 49px; height: 23px; font-size: 0;background: center no-repeat; }
.pgt_view_toggle .view_type {background-image: url(/pgj/cm/images/contents/ico_viewtype_1.png) ;}
.pgt_view_toggle .view_type.active {background-image: url(/pgj/cm/images/contents/ico_viewtype_2.png);}
.pgt_view_toggle.pdf {border: 1px solid #c24557; background: #fff;}
.pgt_view_toggle.pdf .view_type1 {font-size: 13px; color:#5a5a5a; width: auto;padding: 4px 7px 3px 36px;line-height: 20px;background: url(/pgj/cm/images/contents/btn_pdf_bg.png) left center no-repeat;}


/* 사건바구니 */
.selted_box {position: relative;display: inline-block; vertical-align: top;border:none;background:transparent;}
.selted_box .num_boxs {position:relative; display:inline-block;cursor: pointer;}
.selted_box .num_boxs .items_num{position: absolute; font-size: 12px;height: 16px;line-height: 15px;color:#fff;font-weight: 300;top: -9px;right:-7px;text-align: center;background-color: #c24557;padding: 2px 6px 2px 6px;border-radius: 12px;white-space: nowrap;}
.selted_box .num_boxs .num_box {width:19px; height:21px; display:inline-block; background: url(/pgj/cm/images/contents/ico_num_box.png) no-repeat center; font-size:0;}
.selted_box .items{display: none; position:absolute; top: -18px; left: -8px; min-width: 122px;z-index: 10;}
.selted_box .items.on{display: block; }
.selted_box .up-arrow {border: 1px solid #cdcdcd; text-decoration: none;border-radius:5px;padding:7px 14px;margin-top: 50px;background-color: #fff;box-shadow: 0 1px 4px rgba(0,0,0,.11);}
.selted_box .up-arrow:before {content: '';display: inline-block;position: absolute;top: -7px;left: 12px;border-right: 7px solid transparent;border-bottom: 7px solid #cdcdcd;border-left: 7px solid transparent;border-bottom-color: rgba(0,0,0,0.2);}
.selted_box .up-arrow:after {content: '';display: inline-block;position: absolute;top: -6px;left: 13px;border-right: 6px solid transparent;border-bottom: 6px solid #fff;border-left: 6px solid transparent;}
.selted_box .items a {display: inline-block; vertical-align: middle; width: 100%; height: 28px;line-height: 28px; font-size:12px;color:#5a5a5a; border-bottom: 1px solid #e6e6e6;background: center no-repeat;white-space: nowrap;}
.selted_box .items ul li:last-child a{border-bottom:none;}
.selted_box .items a:before{content:''; display:inline-block; width:4px; height:4px; margin-right:10px; background:#333; border-radius:50%; vertical-align:3px;}
.selted_box .items a:hover{color:#466ddc;background-color:#f4f6f8;}

/* 사건바구니 - 이전 css - 추후 삭제 */
.pgt_view_toggle.bn {border:none;background:transparent;}
.pgt_view_toggle .items{display: none; position:absolute; top: -18px; left: -8px; min-width: 122px;z-index: 10;}
.pgt_view_toggle .items.on{display: block; }
.pgt_view_toggle .items a {display: inline-block; vertical-align: middle; width: 100%; height: 28px;line-height: 28px; font-size:12px;color:#5a5a5a; border-bottom: 1px solid #e6e6e6;background: center no-repeat;white-space: nowrap;}
.pgt_view_toggle .items ul li:last-child a{border-bottom:none;}
.pgt_view_toggle .items a:before{content:''; display:inline-block; width:4px; height:4px; margin-right:10px; background:#333; border-radius:50%; vertical-align:3px;}
.pgt_view_toggle .items a:hover{color:#466ddc;background-color:#f4f6f8;}
.up-arrow {border: 1px solid #cdcdcd; text-decoration: none;border-radius:5px;padding:7px 14px;margin-top: 50px;background-color: #fff;box-shadow: 0 1px 4px rgba(0,0,0,.11);}
.up-arrow:before {content: '';display: inline-block;position: absolute;top: -7px;left: 12px;border-right: 7px solid transparent;border-bottom: 7px solid #cdcdcd;border-left: 7px solid transparent;border-bottom-color: rgba(0,0,0,0.2);}
.up-arrow:after {content: '';display: inline-block;position: absolute;top: -6px;left: 13px;border-right: 6px solid transparent;border-bottom: 6px solid #fff;border-left: 6px solid transparent;}
