.num_boxs .items_num{position: absolute; font-size: 12px;height: 16px;line-height: 15px;color:#fff;font-weight: 300;top: -9px;right:-7px;text-align: center;background-color: #c24557;padding: 2px 6px 2px 6px;border-radius: 12px;white-space: nowrap;}
.num_boxs .num_box {width:19px; height:21px; display:inline-block; background: url(/pgj/cm/images/contents/ico_num_box.png) no-repeat center; font-size:0;}

/* 상하좌우배치  */
.w2tabContainer_contents .inner_wrap .ly_column.active { width: 100%;}
.inner_wrap .ly_column.active { width: 100%;padding: 0;}

/* Favorite */
.pgtchkfav, .pgt_fav_tit {display: inline-block; vertical-align: middle;}
.pgtchkfav {padding: 3px 8px 3px 3px; border: 1px solid #dbdbdb; margin-right: 14px; background: #fff; border-radius: 100px;}
.pgt_fav_tit {font-size: 14px; color: #111;}
.btn_fav {display:inline-block;margin-right: 8px;overflow:hidden;width:22px;height:22px;border-radius:50%;background:#1e2a4c url(/pgj/cm/images/contents/ico_fav_star2.png) no-repeat center;text-indent:-9999px;}
.btn_fav.on {background-image: url(/pgj/cm/images/contents/ico_fav_star1.png)}

/*** 1-2 서브 타이틀 Form Title   ***/

/* box gap */
.stbox + .w2tb,
.stbox + .grid{margin-top:5px}

.frm_title {margin-right: 10px;padding:0 0 0 14px;display: inline-block; vertical-align: top; font-size:14px;font-weight:normal;color:#111;height:30px;line-height:36px;background:url(/pgj/cm/images/contents/bg_df_tit_ico_small.png) no-repeat 0 16px;}
.frm_title.bk {background:url(/pgj/cm/images/contents/bg_df_tit_ico_sm_bk.png) no-repeat 0 16px;}

.frm_title span.name{margin-right:4px;font-weight:600;}
.frm_title.b_name {font-weight:600;}

a.frm_title{color: #466ddc;}
.frm_title a{color: #466ddc;}

/* 타이틀 옆 아이콘 */
.frm_title + .title_list_updown {margin-right: 16px;position:relative;left:8px;top:10px;display: inline-block; width:16px;height:16px;cursor: pointer;background:url(/pgj/cm/images/contents/ic_info_up.png) 0 0 no-repeat;}

/* 사건조회 서브타이틀 옆 유틸버튼 */
.stbox .frm_title + .pgt.util_box{float:right;margin-top: 10px;}

/* 타이틀 박스 */
.stbox {position:relative;width:100%;min-height:14px;margin:0 0 5px 0}
.stbox:after {content:'';display:block;clear:both;}
.stbox .btn_serch {position:absolute; top:12px; right:10px; width:13px; height:14px; border-left:1px solid #cdcdcd;  background:url(/pgj/cm/images/contents/ico_addr_search.png) no-repeat 50% 100%; border-radius:3px; border:none; font-size:0; text-indent: -999px;}
.stbox.ty1:before {content:''; position:absolute; top: 12px;bottom: 12px;right: 43px;width: 1px; height:15px; background: #cdcdcd;}

.stbox .btn_g {float:right;margin: 4px 0;}
.stbox .btn_g .inp,
.stbox .btn_g .w2autoComplete{margin:0 10px 0 0 ;}

.stbox .w2input:not(:last-child),
.stbox .w2textarea:not(:last-child),
.stbox .w2selectbox:not(:last-child),
.stbox .w2radio:not(:last-child) {margin-right: 10px;}

.stbox .gvw_count_group{display: inline-block; padding: 11px 0 0;}

.stbox .comp_title {margin-right: 10px;padding:0 0 0 14px;display: inline-block; vertical-align: top; font-size:14px;font-weight:normal;color:#111;height:30px;line-height:36px;}
.stbox .comp_title:first-child{padding:0;}

.stbox .title_txt {margin-right: 10px;padding:0 0 0 4px;display: inline-block; vertical-align: top; font-size:14px;font-weight:normal;color:#111;height:30px;line-height:36px;}

.stbox .tb_noti {position: relative;top: 9px;}

/*사건메모지*/
.stbox .pgt_sub_tit{display: inline-block; font-size: 16px; font-weight: bold; color: #111; margin-top:20px;}
.stbox .pgt_sub_tit:before{content:''; display:inline-block; vertical-align:sub; background:url(/pgj/cm/images/contents/pgt_sub_tit_ico.png) no-repeat; width:20px; height:20px; margin-right:8px;}

.pgt_title_medium {margin:10px 0 0px 0; font-size:14px;font-weight:500;color:#111;}
.pgt_title_medium:before{content:''; display:inline-block; width:4px; height:4px; background-color:#000; border-radius:100%; vertical-align:middle; margin-right:8px;}
.pgt_info_text{line-height:1.7; color:#767676; font-size:14px; margin-top:14px;}

/*------------------------------------------------------------------
[2. Tab Style ]
*/

/* side tabControl */
.side_tbc .w2tabcontrol_control{height:40px;}
.side_tbc > .w2tabcontrol_control{background:url(/sm/pgj/cm/images/contents/tab_line.png) repeat-x left bottom}
.side_tbc .w2tabcontrol_control .mask{left:0;right:100px;margin-left:0;margin-right:0;}
.side_tbc .w2tabcontrol_tabhost {position: relative; z-index: 1; height:101px; border-bottom: 1px solid #e1e3e5;}
.side_tbc .w2tabcontrol_tabhost li{width:50%;height:100%;margin-right:0;_background:#757984;-moz-box-sizing:border-box;box-sizing:border-box; overflow: visible;}
