/* 사건관리 마우스 오른쪽버튼 팝업메뉴 -  w2grid_contextMenu - userMenu   */
.w2grid_contextMenu {color: #5a5a5a;font-size: 13px;border: 1px solid #cdcdcd;box-shadow: 0 1px 4px rgba(0,0,0,.11);}
.w2grid_contextMenu .userMenu.all.first{margin-top:4px;}
