.msg_box_txt {position:relative; min-height:20px; margin-top:20px;padding:14px 20px;background:#fff; border:1px solid #cdcdcd;border-radius: 4px;}
.msg_box_txt .txt_con {font-size:13px; font-weight:400; color:#767676;}
.msg_box_txt .txt_con:before{content:''; display:inline-block; width:4px; height:4px; margin-right:8px; background:#767676; border-radius:50%; vertical-align:3px;}
.msg_box_txt .txt_con.impt {color:#c24557;}
.msg_box_txt .txt_con.impt2 {color:#466ddc;}

/*툴팁  */
.tooltip_box_w {position:relative; display:inline-block;}
.tooltip_box {position: absolute; z-index:999; width:auto; height:auto; display:inline-block; min-width:170px;  margin:10px 0 0 10px;  padding:10px 15px; border:1px solid #cdcdcd; border-radius:5px; font-size:12px; color:#767676;background:#fff; box-shadow:1px 1px 1px rgba(6,0,1,.1); vertical-align:top;}
.tooltip_box.ty1 {display:none; margin:38px 0 0 -97px;}
.tips.on + .tooltip_box{display:inline-block;}
.tooltip_box::before {position:absolute;  top:-4px; left:19px; width:6px; height:6px; content:''; display:inline-block; border-top:1px solid #cdcdcd; border-right:1px solid #cdcdcd; background:#fff;transform:rotate(-45deg); z-index:3;}
.tooltip_box::after {position:absolute; top:-1px; left:18px; width:7px; content:''; display:inline-block; border:1px solid #fff;}
.tooltip_box > ul > li {position:relative; padding:8px 0; border-top:1px solid #eaeaea;}
.tooltip_box > ul > li:first-child {padding-top:0; border-top:none;}
.tooltip_box > ul > li:last-child {padding-bottom:0;}
.tooltip_box .tooltip_list > li:before {display: inline-block;width: 3px;height: 3px;content: '';margin-right: 9px;background: #1e2a4c;border-radius: 50%; vertical-align: middle; }
.tooltip_box .icon_list li {padding:6px 15px; }
.tooltip_box .icon_list li:before {content:none;}
.tooltip_box .icon_list li .txt {padding:0;font-size:12px; border:none; background:none;  color:#333;cursor:pointer;}
.tooltip_box .icon_list li .txt:hover {color:#466ddc;}

.tooltip_box .icon_list > li > .txt:before {display: inline-block; content:''; width:12px; height:12px; margin-right:10px; background:url(/pgj/cm/images/contents/ico_tooltip_user.png) no-repeat; vertical-align:-1px;}
.tooltip_box .icon_list > li > .txt.info:before{background:url(/pgj/cm/images/contents/ico_tooltip_user.png) no-repeat;}
.tooltip_box .icon_list > li > .txt.refresh:before{background:url(/pgj/cm/images/contents/ico_tooltip_refresh.png) no-repeat;}
.tooltip_box .icon_list > li > .txt.colorm:before{background:url(/pgj/cm/images/contents/ico_tooltip_setting.png) no-repeat;}
.tooltip_box .icon_list > li > .txt.court:before{background:url(/pgj/cm/images/contents/ico_tooltip_court.png) no-repeat;}
.tooltip_box .icon_list > li > .txt.fav:before{background:url(/pgj/cm/images/contents/ico_tooltip_fav.png) no-repeat;}
.tooltip_box .icon_list > li > .txt.help:before{background:url(/pgj/cm/images/contents/ico_tooltip_help.png) no-repeat;}

.tooltip_box .icon_list .list_item.on {background:#f4f6f8;}
.tooltip_box .icon_list .list_item.on > span.txt {color:#466ddc;}
.tooltip_box .icon_list .list_item.on > span.txt.tit {color:#466ddc;cursor:default;}

.tooltip_box .icon_list .items {padding-top:3px;}
.tooltip_box .icon_list .item {padding:3px 15px 3px 23px; border-bottom:1px dotted #ddd;}
.tooltip_box .icon_list .item:last-child {border:none;}
.tooltip_box .icon_list.ty1 > li > .txt:before {background:url(/pgj/cm/images/contents/ico_tooltip_setting.png) no-repeat;}
.tooltip_box .icon_list.ty1 > li:nth-child(2) > .txt:before {background:url(/pgj/cm/images/contents/ico_tooltip_lock.png) no-repeat;}
.tooltip_box .icon_list.ty1 > li:nth-child(3) > .txt:before {background:url(/pgj/cm/images/contents/ico_tooltip_help.png) no-repeat;}
.tooltip_box .tit {font-weight:500; color:#333;}
.tooltip_box .txt,.tooltip_box .tooltip_txt {padding-left:8px; font-size:12px; font-weight:400; color:#333;}
.tooltip_box .tooltip_txt {padding:0; }
.tooltip_box .chk .w2checkbox_row {padding:7px 12px;}
.tooltip_box .chk .w2checkbox_row:hover {background:#f5f6f8;}
.tooltip_box .chk .w2checkbox_row > td {padding:3px 12px;}
.tooltip_box .chk .w2checkbox_row .w2checkbox_td_input {padding-right:0;}
.tooltip_box .chk .w2checkbox_row .w2checkbox_td_label {padding-left:5px;}
.tooltip_box .chk .w2checkbox_row .w2checkbox_td_label.select {color:#496ee0;}
.tooltip_box + .tooltip_box {margin-left:10px;}

/* PageList */
.wq_pglist {margin-top:15px;}
.wq_pglist .w2pageList_ul li {width:34px;}
.wq_pglist .w2pageList_col_label {width:34px;height:34px}
.wq_pglist .w2pageList_label {height:100%;line-height:34px;color:#959595;font-size:13px;-webkit-transition: .2s all;-o-transition: .2s all;transition: .2s all;border-radius: 50%;}
.wq_pglist .w2pageList_label_over {color: #466ddc;}
.wq_pglist .w2pageList_label_selected {height:100%;line-height:34px;border-radius:50%;color:#466ddc;font-weight:bold;font-size: 13px;}
.wq_pglist .w2pageList_col_prev,
.wq_pglist .w2pageList_col_prevPage,
.wq_pglist .w2pageList_col_next,
.wq_pglist .w2pageList_col_nextPage {width:34px;height:34px;background:none;position:relative;}
.wq_pglist .w2pageList_col_prev:before {content:'';position:absolute;top:13px;right:10px;width:7px;height:7px;border-top:2px solid #959595;border-right:2px solid #959595;-webkit-transform:rotate(-135deg);-ms-transform:rotate(-135deg);transform:rotate(-135deg)}
.wq_pglist .w2pageList_col_prevPage:before {content:'';position:absolute;top:13px;right:13px;width:7px;height:7px;border-top:2px solid #959595;border-right:2px solid #959595;-webkit-transform:rotate(-135deg);-ms-transform:rotate(-135deg);transform:rotate(-135deg)}
.wq_pglist .w2pageList_col_prevPage:after {content:'';position:absolute;top:13px;right:7px;width:7px;height:7px;border-top:2px solid #959595;border-right:2px solid #959595;-webkit-transform:rotate(-135deg);-ms-transform:rotate(-135deg);transform:rotate(-135deg)}
.wq_pglist .w2pageList_col_next:before {content:'';position:absolute;top:13px;right:13px;width:7px;height:7px;border-top:2px solid #959595;border-right:2px solid #959595;-webkit-transform:rotate(45deg);-ms-transform:rotate(45deg);transform:rotate(45deg)}
.wq_pglist .w2pageList_col_nextPage:before {content:'';position:absolute;top:13px;right:16px;width:7px;height:7px;border-top:2px solid #959595;border-right:2px solid #959595;-webkit-transform:rotate(45deg);-ms-transform:rotate(45deg);transform:rotate(45deg)}
.wq_pglist .w2pageList_col_nextPage:after {content:'';position:absolute;top:13px;right:10px;width:7px;height:7px;border-top:2px solid #959595;border-right:2px solid #959595;-webkit-transform:rotate(45deg);-ms-transform:rotate(45deg);transform:rotate(45deg)}

