.result_wrap .w2tb .w2tb_th, .result_wrap .w2tb .w2tb_td{height:20px;padding:0 5px;letter-spacing:-1px}
.result_wrap .w2tb .w2tb_th{text-align:left;border:0;font-weight:500;background:#fff}
.result_wrap .w2tb .w2tb_td{border:0}
.result_wrap .w2tb tr:first-of-type .w2tb_th, .result_wrap .w2tb tr:first-of-type .w2tb_td{border:0}
.result_wrap .w2tb tr:last-of-type .w2tb_th, .result_wrap .w2tb tr:last-of-type .w2tb_td{border:0}
.ad_list{padding:0 20px;border-radius:4px;background:#f5f5f5}
.ad_list li{padding:10px 0;border-bottom:1px solid #bababa;font-size:13px;list-style:none}
.ad_list li:last-child{border-bottom:0}

