/*------------------------------------------------------------------
[2. Title Box ]
*/

/* 화면상단 공통영역 */
.user .pgtbox{display:block; padding:0 0 10px 0;margin:0 0 20px 0;border-bottom:1px solid #b0b0b0}
.user .pgtbox::after{display:block;clear:both;content:''}
.user .pgtbox .pgt_tit{float:left;font-size:30px;padding:0;background:none}
